const ALL_QUESTIONS = [{"id": 1, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Select all rows from the `users` table.", "sql": "SELECT * FROM users;", "explanation": "The asterisk (*) selects all columns from the table.", "db": "ecommerce_db"}, {"id": 2, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Select only `username` and `email` from the `users` table.", "sql": "SELECT username, email FROM users;", "explanation": "Specify column names to retrieve only needed data.", "db": "ecommerce_db"}, {"id": 3, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Select all products with their name and price, aliased as `product_name` and `product_price`.", "sql": "SELECT name AS product_name, base_price AS product_price FROM products;", "explanation": "AS keyword creates column aliases for readability.", "db": "ecommerce_db"}, {"id": 4, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all users whose role is 'admin'.", "sql": "SELECT * FROM users WHERE role = 'admin';", "explanation": "WHERE clause filters rows matching the condition.", "db": "ecommerce_db"}, {"id": 5, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all active products with a price greater than 100.", "sql": "SELECT * FROM products WHERE is_active = TRUE AND base_price > 100;", "explanation": "AND combines multiple conditions — both must be true.", "db": "ecommerce_db"}, {"id": 6, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all orders that are either 'shipped' or 'delivered'.", "sql": "SELECT * FROM orders WHERE status = 'shipped' OR status = 'delivered';", "explanation": "OR returns rows where at least one condition is true.", "db": "ecommerce_db"}, {"id": 7, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all products that are NOT in category_id 5.", "sql": "SELECT * FROM products WHERE category_id != 5;", "explanation": "!= (or <>) is the not-equal operator.", "db": "ecommerce_db"}, {"id": 8, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all products with a base_price between 50 and 200.", "sql": "SELECT * FROM products WHERE base_price BETWEEN 50 AND 200;", "explanation": "BETWEEN is inclusive of both boundary values.", "db": "ecommerce_db"}, {"id": 9, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all users whose role is either 'admin', 'vendor', or 'customer'.", "sql": "SELECT * FROM users WHERE role IN ('admin', 'vendor', 'customer');", "explanation": "IN checks if value matches any in the list.", "db": "ecommerce_db"}, {"id": 10, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all users whose role is NOT 'customer'.", "sql": "SELECT * FROM users WHERE role NOT IN ('customer');", "explanation": "NOT IN excludes matching values.", "db": "ecommerce_db"}, {"id": 11, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all products whose name contains 'phone' (case-insensitive).", "sql": "SELECT * FROM products WHERE name ILIKE '%phone%';", "explanation": "ILIKE is PostgreSQL's case-insensitive LIKE.", "db": "ecommerce_db"}, {"id": 12, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all users whose email ends with '@gmail.com'.", "sql": "SELECT * FROM users WHERE email LIKE '%@gmail.com';", "explanation": "% wildcard matches any sequence of characters.", "db": "ecommerce_db"}, {"id": 13, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all users whose username is exactly 5 characters long.", "sql": "SELECT * FROM users WHERE username LIKE '_____';", "explanation": "Each underscore (_) matches exactly one character.", "db": "ecommerce_db"}, {"id": 14, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all products where the description is NULL.", "sql": "SELECT * FROM products WHERE description IS NULL;", "explanation": "IS NULL checks for missing/null values. = NULL won't work.", "db": "ecommerce_db"}, {"id": 15, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all orders where shipped_at is NOT NULL.", "sql": "SELECT * FROM orders WHERE shipped_at IS NOT NULL;", "explanation": "IS NOT NULL finds rows with a value present.", "db": "ecommerce_db"}, {"id": 16, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Select the first 10 products ordered by base_price ascending.", "sql": "SELECT * FROM products ORDER BY base_price ASC LIMIT 10;", "explanation": "ORDER BY sorts; LIMIT restricts row count.", "db": "ecommerce_db"}, {"id": 17, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Select products 11–20 ordered by price (pagination).", "sql": "SELECT * FROM products ORDER BY base_price ASC LIMIT 10 OFFSET 10;", "explanation": "OFFSET skips rows — useful for pagination.", "db": "ecommerce_db"}, {"id": 18, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Get all distinct roles from the users table.", "sql": "SELECT DISTINCT role FROM users;", "explanation": "DISTINCT removes duplicate values from results.", "db": "ecommerce_db"}, {"id": 19, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Select distinct cities from the addresses table.", "sql": "SELECT DISTINCT city FROM addresses;", "explanation": "", "db": "ecommerce_db"}, {"id": 20, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Get the most recent order for each user using DISTINCT ON.", "sql": "SELECT DISTINCT ON (user_id) * FROM orders ORDER BY user_id, placed_at DESC;", "explanation": "DISTINCT ON keeps the first row per group after ORDER BY — PostgreSQL-specific.", "db": "ecommerce_db"}, {"id": 21, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Concatenate first_name and last_name of patients into a full_name column.", "sql": "SELECT first_name || ' ' || last_name AS full_name FROM patients;", "explanation": "|| is the string concatenation operator in PostgreSQL.", "db": "hospital_db"}, {"id": 22, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Select all orders sorted by total_amount descending.", "sql": "SELECT * FROM orders ORDER BY total_amount DESC;", "explanation": "DESC sorts in descending order (largest first).", "db": "ecommerce_db"}, {"id": 23, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Select all orders sorted by status ascending, then by placed_at descending.", "sql": "SELECT * FROM orders ORDER BY status ASC, placed_at DESC;", "explanation": "Multi-column sort: first by status, then by date within each status.", "db": "ecommerce_db"}, {"id": 24, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all students enrolled after 2024 with a GPA above 3.5.", "sql": "SELECT * FROM students WHERE batch_year > 2024 AND gpa > 3.5;", "explanation": "", "db": "university_db"}, {"id": 25, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all accounts with a balance of exactly 0.", "sql": "SELECT * FROM accounts WHERE balance = 0;", "explanation": "", "db": "bank_db"}, {"id": 26, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all posts that are public and not archived.", "sql": "SELECT * FROM posts WHERE visibility = 'public' AND is_archived = FALSE;", "explanation": "", "db": "social_db"}, {"id": 27, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all products with a SKU starting with 'SKU-'.", "sql": "SELECT * FROM products WHERE sku LIKE 'SKU-%';", "explanation": "LIKE with a prefix pattern still uses an index if available.", "db": "ecommerce_db"}, {"id": 28, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all verified reviews for a product.", "sql": "SELECT * FROM reviews WHERE is_verified = TRUE;", "explanation": "", "db": "ecommerce_db"}, {"id": 29, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Select brand name and country, sorted alphabetically by name.", "sql": "SELECT name, country FROM brands ORDER BY name ASC;", "explanation": "", "db": "ecommerce_db"}, {"id": 30, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all categories that have no parent (top-level categories).", "sql": "SELECT * FROM categories WHERE parent_id IS NULL;", "explanation": "Self-referencing FK — NULL parent means root node.", "db": "ecommerce_db"}, {"id": 31, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find users created in the last 30 days.", "sql": "SELECT * FROM users WHERE created_at >= NOW() - INTERVAL '30 days';", "explanation": "INTERVAL arithmetic is a powerful PostgreSQL feature.", "db": "ecommerce_db"}, {"id": 32, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all appointments scheduled for today.", "sql": "SELECT * FROM appointments WHERE scheduled_at::DATE = CURRENT_DATE;", "explanation": "::DATE casts timestamp to date for comparison.", "db": "hospital_db"}, {"id": 33, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all loans with status 'defaulted' or 'overdue'.", "sql": "SELECT * FROM loans WHERE status IN ('defaulted') UNION SELECT l.* FROM loans l JOIN loan_repayments lr ON l.loan_id = lr.loan_id WHERE lr.status = 'overdue';", "explanation": "", "db": "bank_db"}, {"id": 34, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Select the top 5 most expensive products.", "sql": "SELECT * FROM products ORDER BY base_price DESC LIMIT 5;", "explanation": "Combine ORDER BY DESC with LIMIT for top-N queries.", "db": "ecommerce_db"}, {"id": 35, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all users with a phone number provided.", "sql": "SELECT * FROM users WHERE phone IS NOT NULL AND phone != '';", "explanation": "Check both NULL and empty string for completeness.", "db": "ecommerce_db"}, {"id": 36, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all reviews with a rating of 1 or 5 (extreme ratings).", "sql": "SELECT * FROM reviews WHERE rating IN (1, 5);", "explanation": "", "db": "ecommerce_db"}, {"id": 37, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all product variants that are out of stock.", "sql": "SELECT * FROM product_variants WHERE stock_qty = 0;", "explanation": "", "db": "ecommerce_db"}, {"id": 38, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all orders placed in January 2025.", "sql": "SELECT * FROM orders WHERE placed_at >= '2025-01-01' AND placed_at < '2025-02-01';", "explanation": "Range comparison is more index-friendly than EXTRACT.", "db": "ecommerce_db"}, {"id": 39, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Select username, email, and created_at for inactive users.", "sql": "SELECT username, email, created_at FROM users WHERE is_active = FALSE;", "explanation": "", "db": "ecommerce_db"}, {"id": 40, "section": "Topic 1 — Basic SELECT (40 Qs)", "question": "Find all coupons that are currently valid.", "sql": "SELECT * FROM coupons WHERE is_active = TRUE AND valid_from <= CURRENT_DATE AND valid_until >= CURRENT_DATE;", "explanation": "Multiple conditions to check validity window.", "db": "ecommerce_db"}, {"id": 41, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Count the total number of users.", "sql": "SELECT COUNT(*) AS total_users FROM users;", "explanation": "COUNT(*) counts all rows including NULLs.", "db": "ecommerce_db"}, {"id": 42, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Count how many products have a non-null description.", "sql": "SELECT COUNT(description) AS with_desc FROM products;", "explanation": "COUNT(col) ignores NULLs.", "db": "ecommerce_db"}, {"id": 43, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find the total revenue from all orders.", "sql": "SELECT SUM(total_amount) AS total_revenue FROM orders;", "explanation": "", "db": "ecommerce_db"}, {"id": 44, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find the average product price.", "sql": "SELECT AVG(base_price) AS avg_price FROM products;", "explanation": "", "db": "ecommerce_db"}, {"id": 45, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find the cheapest and most expensive product prices.", "sql": "SELECT MIN(base_price) AS cheapest, MAX(base_price) AS most_expensive FROM products;", "explanation": "", "db": "ecommerce_db"}, {"id": 46, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Count orders grouped by status.", "sql": "SELECT status, COUNT(*) AS order_count FROM orders GROUP BY status;", "explanation": "GROUP BY groups rows; aggregate is calculated per group.", "db": "ecommerce_db"}, {"id": 47, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find total revenue per user.", "sql": "SELECT user_id, SUM(total_amount) AS user_revenue FROM orders GROUP BY user_id;", "explanation": "", "db": "ecommerce_db"}, {"id": 48, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find the average rating per product.", "sql": "SELECT product_id, ROUND(AVG(rating), 2) AS avg_rating FROM reviews GROUP BY product_id;", "explanation": "ROUND() limits decimal places.", "db": "ecommerce_db"}, {"id": 49, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find users who have placed more than 5 orders.", "sql": "SELECT user_id, COUNT(*) AS order_count FROM orders GROUP BY user_id HAVING COUNT(*) > 5;", "explanation": "HAVING filters groups (after GROUP BY), unlike WHERE which filters rows.", "db": "ecommerce_db"}, {"id": 50, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find the total stock across all product variants.", "sql": "SELECT SUM(stock_qty) AS total_stock FROM product_variants;", "explanation": "", "db": "ecommerce_db"}, {"id": 51, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Count orders per payment method.", "sql": "SELECT payment_method, COUNT(*) AS cnt FROM orders GROUP BY payment_method ORDER BY cnt DESC;", "explanation": "", "db": "ecommerce_db"}, {"id": 52, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Group orders by status and payment_status to get counts.", "sql": "SELECT status, payment_status, COUNT(*) FROM orders GROUP BY status, payment_status;", "explanation": "GROUP BY multiple columns creates combined groups.", "db": "ecommerce_db"}, {"id": 53, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find total paid vs unpaid amounts across all bills.", "sql": "SELECT status, SUM(total_amount) AS total FROM bills GROUP BY status;", "explanation": "", "db": "hospital_db"}, {"id": 54, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find the number of students per program.", "sql": "SELECT program_id, COUNT(*) AS student_count FROM students GROUP BY program_id;", "explanation": "", "db": "university_db"}, {"id": 55, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find the average salary per department for staff.", "sql": "SELECT dept_id, ROUND(AVG(salary),2) AS avg_salary FROM staff GROUP BY dept_id;", "explanation": "", "db": "hospital_db"}, {"id": 56, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find users with average order value above 500.", "sql": "SELECT user_id, ROUND(AVG(total_amount),2) AS avg_order FROM orders GROUP BY user_id HAVING AVG(total_amount) > 500;", "explanation": "", "db": "ecommerce_db"}, {"id": 57, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Count distinct brands in the products table.", "sql": "SELECT COUNT(DISTINCT brand_id) AS brand_count FROM products;", "explanation": "COUNT(DISTINCT col) counts unique non-null values.", "db": "ecommerce_db"}, {"id": 58, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find the total number of transactions per account.", "sql": "SELECT account_id, COUNT(*) AS txn_count FROM transactions GROUP BY account_id;", "explanation": "", "db": "bank_db"}, {"id": 59, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find the maximum loan amount per loan type.", "sql": "SELECT loan_type, MAX(principal) AS max_loan FROM loans GROUP BY loan_type;", "explanation": "", "db": "bank_db"}, {"id": 60, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find total likes per post.", "sql": "SELECT post_id, COUNT(*) AS like_count FROM likes GROUP BY post_id ORDER BY like_count DESC;", "explanation": "", "db": "social_db"}, {"id": 61, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find the number of products per category.", "sql": "SELECT category_id, COUNT(*) AS product_count FROM products GROUP BY category_id ORDER BY product_count DESC;", "explanation": "", "db": "ecommerce_db"}, {"id": 62, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find the sum of all discounts given.", "sql": "SELECT SUM(discount_amount) AS total_discounts FROM orders;", "explanation": "", "db": "ecommerce_db"}, {"id": 63, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find the minimum and maximum consultation fees across all doctors.", "sql": "SELECT MIN(consultation_fee) AS min_fee, MAX(consultation_fee) AS max_fee FROM doctors;", "explanation": "", "db": "hospital_db"}, {"id": 64, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Count how many reviews each rating value has.", "sql": "SELECT rating, COUNT(*) AS cnt FROM reviews GROUP BY rating ORDER BY rating;", "explanation": "", "db": "ecommerce_db"}, {"id": 65, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find the average GPA per batch year.", "sql": "SELECT batch_year, ROUND(AVG(gpa),2) AS avg_gpa FROM students GROUP BY batch_year ORDER BY batch_year;", "explanation": "", "db": "university_db"}, {"id": 66, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find total page views per product.", "sql": "SELECT product_id, COUNT(*) AS views FROM page_views GROUP BY product_id ORDER BY views DESC LIMIT 10;", "explanation": "Top 10 most viewed products.", "db": "ecommerce_db"}, {"id": 67, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find total deposit amount per customer in fixed deposits.", "sql": "SELECT customer_id, SUM(principal) AS total_fd FROM fixed_deposits GROUP BY customer_id;", "explanation": "", "db": "bank_db"}, {"id": 68, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find the total number of comments per post.", "sql": "SELECT post_id, COUNT(*) AS comment_count FROM comments GROUP BY post_id;", "explanation": "", "db": "social_db"}, {"id": 69, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find status-wise count of orders, only showing statuses with more than 10 orders.", "sql": "SELECT status, COUNT(*) AS cnt FROM orders GROUP BY status HAVING COUNT(*) > 10 ORDER BY cnt DESC;", "explanation": "", "db": "ecommerce_db"}, {"id": 70, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find the total shipping fees collected.", "sql": "SELECT SUM(shipping_fee) AS total_shipping FROM orders;", "explanation": "", "db": "ecommerce_db"}, {"id": 71, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find the average number of items per order.", "sql": "SELECT ROUND(AVG(item_count),2) AS avg_items FROM (SELECT order_id, COUNT(*) AS item_count FROM order_items GROUP BY order_id) sub;", "explanation": "Subquery calculates items per order, outer query averages them.", "db": "ecommerce_db"}, {"id": 72, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find the busiest day by order count.", "sql": "SELECT placed_at::DATE AS order_date, COUNT(*) AS cnt FROM orders GROUP BY order_date ORDER BY cnt DESC LIMIT 1;", "explanation": "", "db": "ecommerce_db"}, {"id": 73, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Count followers per user.", "sql": "SELECT following_id AS user_id, COUNT(*) AS follower_count FROM follows WHERE status = 'active' GROUP BY following_id ORDER BY follower_count DESC;", "explanation": "", "db": "social_db"}, {"id": 74, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find total credits per department in courses.", "sql": "SELECT dept_id, SUM(credits) AS total_credits FROM courses GROUP BY dept_id;", "explanation": "", "db": "university_db"}, {"id": 75, "section": "Topic 2 — Basic Aggregates (35 Qs)", "question": "Find the aggregate order summary: count, total, avg, min, max.", "sql": "SELECT COUNT(*) AS order_count, SUM(total_amount) AS total, ROUND(AVG(total_amount),2) AS avg_order, MIN(total_amount) AS min_order, MAX(total_amount) AS max_order FROM orders;", "explanation": "Multiple aggregates in a single query.", "db": "ecommerce_db"}, {"id": 76, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List all orders with the username of the user who placed them.", "sql": "SELECT o.order_id, o.total_amount, u.username FROM orders o INNER JOIN users u ON o.user_id = u.user_id;", "explanation": "INNER JOIN returns only matching rows from both tables.", "db": "ecommerce_db"}, {"id": 77, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List all products with their category name.", "sql": "SELECT p.name AS product, c.name AS category FROM products p INNER JOIN categories c ON p.category_id = c.category_id;", "explanation": "", "db": "ecommerce_db"}, {"id": 78, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List all products with their brand name.", "sql": "SELECT p.name AS product, b.name AS brand FROM products p INNER JOIN brands b ON p.brand_id = b.brand_id;", "explanation": "", "db": "ecommerce_db"}, {"id": 79, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List all users and their orders (including users with no orders).", "sql": "SELECT u.username, o.order_id, o.total_amount FROM users u LEFT JOIN orders o ON u.user_id = o.user_id;", "explanation": "LEFT JOIN keeps all rows from the left table even if no match.", "db": "ecommerce_db"}, {"id": 80, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "Find all users who have never placed an order.", "sql": "SELECT u.username, u.email FROM users u LEFT JOIN orders o ON u.user_id = o.user_id WHERE o.order_id IS NULL;", "explanation": "Anti-join pattern: LEFT JOIN + IS NULL finds unmatched rows.", "db": "ecommerce_db"}, {"id": 81, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List order items with product variant details and order info.", "sql": "SELECT oi.order_id, pv.product_id, pv.size, pv.color, oi.quantity, oi.unit_price FROM order_items oi JOIN product_variants pv ON oi.variant_id = pv.variant_id;", "explanation": "", "db": "ecommerce_db"}, {"id": 82, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List all reviews with the product name and reviewer username.", "sql": "SELECT r.rating, r.title, p.name AS product, u.username FROM reviews r JOIN products p ON r.product_id = p.product_id JOIN users u ON r.user_id = u.user_id;", "explanation": "Three-table join chains the ON clauses.", "db": "ecommerce_db"}, {"id": 83, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List all patients with their assigned doctor's name for appointments.", "sql": "SELECT p.first_name || ' ' || p.last_name AS patient, s.first_name || ' ' || s.last_name AS doctor, a.scheduled_at FROM appointments a JOIN patients p ON a.patient_id = p.patient_id JOIN doctors d ON a.doctor_id = d.doctor_id JOIN staff s ON d.staff_id = s.staff_id;", "explanation": "Four-table join through doctors→staff to get names.", "db": "hospital_db"}, {"id": 84, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List students with their program name.", "sql": "SELECT s.first_name, s.last_name, p.name AS program FROM students s JOIN programs p ON s.program_id = p.program_id;", "explanation": "", "db": "university_db"}, {"id": 85, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List all enrollments with student name, course name, and grade.", "sql": "SELECT st.first_name, st.last_name, co.name AS course, e.final_grade FROM enrollments e JOIN sections sec ON e.section_id = sec.section_id JOIN courses co ON sec.course_id = co.course_id JOIN students st ON e.student_id = st.student_id;", "explanation": "", "db": "university_db"}, {"id": 86, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List all accounts with customer name and branch name.", "sql": "SELECT c.first_name, c.last_name, a.account_no, a.balance, b.name AS branch FROM accounts a JOIN customers c ON a.customer_id = c.customer_id JOIN branches b ON a.branch_id = b.branch_id;", "explanation": "", "db": "bank_db"}, {"id": 87, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List all posts with the username of the author.", "sql": "SELECT p.post_id, p.content, u.username FROM posts p JOIN users u ON p.user_id = u.user_id;", "explanation": "", "db": "social_db"}, {"id": 88, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "Find all products that have NO reviews.", "sql": "SELECT p.name FROM products p LEFT JOIN reviews r ON p.product_id = r.product_id WHERE r.review_id IS NULL;", "explanation": "Anti-join to find products with zero reviews.", "db": "ecommerce_db"}, {"id": 89, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List all orders with their shipping information.", "sql": "SELECT o.order_id, o.status, s.tracking_no, s.carrier, s.status AS ship_status FROM orders o LEFT JOIN shipments s ON o.order_id = s.order_id;", "explanation": "", "db": "ecommerce_db"}, {"id": 90, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List all cart items with product name and variant details.", "sql": "SELECT ci.quantity, p.name AS product, pv.size, pv.color, pv.price FROM cart_items ci JOIN product_variants pv ON ci.variant_id = pv.variant_id JOIN products p ON pv.product_id = p.product_id;", "explanation": "", "db": "ecommerce_db"}, {"id": 91, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "Find all departments that have no staff assigned.", "sql": "SELECT d.name FROM departments d LEFT JOIN staff s ON d.dept_id = s.dept_id WHERE s.staff_id IS NULL;", "explanation": "", "db": "hospital_db"}, {"id": 92, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List prescriptions with patient name and doctor name.", "sql": "SELECT p.first_name || ' ' || p.last_name AS patient, s.first_name || ' ' || s.last_name AS doctor, pr.issued_at FROM prescriptions pr JOIN patients p ON pr.patient_id = p.patient_id JOIN doctors d ON pr.doctor_id = d.doctor_id JOIN staff s ON d.staff_id = s.staff_id;", "explanation": "", "db": "hospital_db"}, {"id": 93, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List lab order items with test name and result.", "sql": "SELECT lt.name AS test, loi.result_value, loi.is_abnormal FROM lab_order_items loi JOIN lab_tests lt ON loi.test_id = lt.test_id;", "explanation": "", "db": "hospital_db"}, {"id": 94, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "Find all courses with no enrolled students.", "sql": "SELECT co.code, co.name FROM courses co LEFT JOIN sections sec ON co.course_id = sec.course_id LEFT JOIN enrollments e ON sec.section_id = e.section_id WHERE e.enrollment_id IS NULL;", "explanation": "", "db": "university_db"}, {"id": 95, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List all transfers with from/to account numbers.", "sql": "SELECT t.transfer_id, a1.account_no AS from_acct, a2.account_no AS to_acct, t.amount FROM transfers t JOIN accounts a1 ON t.from_account = a1.account_id JOIN accounts a2 ON t.to_account = a2.account_id;", "explanation": "Self-join on the same table using different aliases.", "db": "bank_db"}, {"id": 96, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "Find mutual follows (users who follow each other).", "sql": "SELECT f1.follower_id, f1.following_id FROM follows f1 JOIN follows f2 ON f1.follower_id = f2.following_id AND f1.following_id = f2.follower_id WHERE f1.follower_id < f1.following_id;", "explanation": "Self-join on follows to find mutual relationships.", "db": "social_db"}, {"id": 97, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List all comments with the post content and commenter username.", "sql": "SELECT c.content AS comment, p.content AS post, u.username FROM comments c JOIN posts p ON c.post_id = p.post_id JOIN users u ON c.user_id = u.user_id;", "explanation": "", "db": "social_db"}, {"id": 98, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List all order items with the order status and product name.", "sql": "SELECT oi.order_item_id, o.status, p.name AS product FROM order_items oi JOIN orders o ON oi.order_id = o.order_id JOIN product_variants pv ON oi.variant_id = pv.variant_id JOIN products p ON pv.product_id = p.product_id;", "explanation": "", "db": "ecommerce_db"}, {"id": 99, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "FULL OUTER JOIN: Show all users and all orders including unmatched.", "sql": "SELECT u.username, o.order_id FROM users u FULL OUTER JOIN orders o ON u.user_id = o.user_id;", "explanation": "FULL OUTER JOIN keeps unmatched rows from both sides.", "db": "ecommerce_db"}, {"id": 100, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "Find all rooms with their department name.", "sql": "SELECT r.room_no, r.type, d.name AS department FROM rooms r JOIN departments d ON r.dept_id = d.dept_id;", "explanation": "", "db": "hospital_db"}, {"id": 101, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List sections with instructor name and course name.", "sql": "SELECT co.name AS course, i.first_name || ' ' || i.last_name AS instructor, sec.schedule FROM sections sec JOIN courses co ON sec.course_id = co.course_id JOIN instructors i ON sec.instructor_id = i.instructor_id;", "explanation": "", "db": "university_db"}, {"id": 102, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List all cards with account number and customer name.", "sql": "SELECT ca.card_no, ca.card_type, a.account_no, c.first_name || ' ' || c.last_name AS customer FROM cards ca JOIN accounts a ON ca.account_id = a.account_id JOIN customers c ON a.customer_id = c.customer_id;", "explanation": "", "db": "bank_db"}, {"id": 103, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "Find all wishlist items with product name and user.", "sql": "SELECT u.username, p.name AS product FROM wishlists w JOIN users u ON w.user_id = u.user_id JOIN product_variants pv ON w.variant_id = pv.variant_id JOIN products p ON pv.product_id = p.product_id;", "explanation": "", "db": "ecommerce_db"}, {"id": 104, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "Find the total order amount per user with their username.", "sql": "SELECT u.username, SUM(o.total_amount) AS total_spent FROM orders o JOIN users u ON o.user_id = u.user_id GROUP BY u.username ORDER BY total_spent DESC;", "explanation": "JOIN + GROUP BY + aggregate is a very common pattern.", "db": "ecommerce_db"}, {"id": 105, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "Find the average rating per product with the product name.", "sql": "SELECT p.name, ROUND(AVG(r.rating),2) AS avg_rating, COUNT(r.review_id) AS review_count FROM products p JOIN reviews r ON p.product_id = r.product_id GROUP BY p.name ORDER BY avg_rating DESC;", "explanation": "", "db": "ecommerce_db"}, {"id": 106, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "Find total transaction amount per customer.", "sql": "SELECT c.first_name, c.last_name, SUM(t.amount) AS total_txn FROM transactions t JOIN accounts a ON t.account_id = a.account_id JOIN customers c ON a.customer_id = c.customer_id GROUP BY c.customer_id, c.first_name, c.last_name;", "explanation": "", "db": "bank_db"}, {"id": 107, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "Find the number of appointments per doctor.", "sql": "SELECT s.first_name || ' ' || s.last_name AS doctor, COUNT(a.appointment_id) AS appt_count FROM appointments a JOIN doctors d ON a.doctor_id = d.doctor_id JOIN staff s ON d.staff_id = s.staff_id GROUP BY s.first_name, s.last_name;", "explanation": "", "db": "hospital_db"}, {"id": 108, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "Find posts with hashtag name.", "sql": "SELECT p.post_id, p.content, h.tag FROM post_hashtags ph JOIN posts p ON ph.post_id = p.post_id JOIN hashtags h ON ph.hashtag_id = h.hashtag_id;", "explanation": "Many-to-many join through junction table.", "db": "social_db"}, {"id": 109, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "Find categories with the count of products in each.", "sql": "SELECT c.name AS category, COUNT(p.product_id) AS product_count FROM categories c LEFT JOIN products p ON c.category_id = p.category_id GROUP BY c.name ORDER BY product_count DESC;", "explanation": "LEFT JOIN ensures categories with 0 products are shown.", "db": "ecommerce_db"}, {"id": 110, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "Find patients who have been admitted more than once.", "sql": "SELECT p.first_name, p.last_name, COUNT(a.admission_id) AS admissions FROM patients p JOIN admissions a ON p.patient_id = a.patient_id GROUP BY p.patient_id, p.first_name, p.last_name HAVING COUNT(a.admission_id) > 1;", "explanation": "", "db": "hospital_db"}, {"id": 111, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "Find all scholarship awards with student and scholarship name.", "sql": "SELECT s.first_name, s.last_name, sc.name AS scholarship, sa.amount FROM scholarship_awards sa JOIN students s ON sa.student_id = s.student_id JOIN scholarships sc ON sa.scholarship_id = sc.scholarship_id;", "explanation": "", "db": "university_db"}, {"id": 112, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "List notifications with both the actor and recipient usernames.", "sql": "SELECT n.type, n.message, u1.username AS recipient, u2.username AS actor FROM notifications n JOIN users u1 ON n.user_id = u1.user_id JOIN users u2 ON n.actor_id = u2.user_id;", "explanation": "Two joins to the same table with different aliases.", "db": "social_db"}, {"id": 113, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "Find all poll option results with the poll question.", "sql": "SELECT po.poll_id, pl.question, po.option_text, po.vote_count FROM poll_options po JOIN polls pl ON po.poll_id = pl.poll_id ORDER BY po.poll_id, po.vote_count DESC;", "explanation": "", "db": "social_db"}, {"id": 114, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "Find branches with no employees.", "sql": "SELECT b.name AS branch, b.city FROM branches b LEFT JOIN employees e ON b.branch_id = e.branch_id WHERE e.employee_id IS NULL;", "explanation": "", "db": "bank_db"}, {"id": 115, "section": "Topic 3 — Basic Joins (40 Qs)", "question": "Find the submission count per assignment with assignment title.", "sql": "SELECT a.title, COUNT(s.submission_id) AS submissions FROM assignments a LEFT JOIN submissions s ON a.assignment_id = s.assignment_id GROUP BY a.title;", "explanation": "", "db": "university_db"}, {"id": 116, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Insert a new user into the users table.", "sql": "INSERT INTO users (username, email, password_hash, full_name, role) VALUES ('john_doe', 'john@example.com', 'hashed_pw', 'John Doe', 'customer');", "explanation": "", "db": "ecommerce_db"}, {"id": 117, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Insert multiple products in a single statement.", "sql": "INSERT INTO products (name, base_price, category_id) VALUES ('Widget A', 29.99, 1), ('Widget B', 49.99, 1), ('Gadget C', 99.99, 2);", "explanation": "Multi-row INSERT is more efficient than multiple single inserts.", "db": "ecommerce_db"}, {"id": 118, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Update the status of order #101 to 'shipped'.", "sql": "UPDATE orders SET status = 'shipped', shipped_at = NOW() WHERE order_id = 101;", "explanation": "Always use WHERE to avoid updating all rows accidentally.", "db": "ecommerce_db"}, {"id": 119, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Update multiple columns: set role to 'admin' and is_active to true for user_id 5.", "sql": "UPDATE users SET role = 'admin', is_active = TRUE WHERE user_id = 5;", "explanation": "", "db": "ecommerce_db"}, {"id": 120, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Delete all cancelled orders.", "sql": "DELETE FROM orders WHERE status = 'cancelled';", "explanation": "DELETE removes specific rows matching the condition.", "db": "ecommerce_db"}, {"id": 121, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Explain the difference between DELETE and TRUNCATE.", "sql": "-- DELETE: Row-by-row removal, logged, can have WHERE, triggers fire\nDELETE FROM cart_items;\n\n-- TRUNCATE: Instant removal of all rows, resets sequences, no triggers\nTRUNCATE TABLE cart_items;", "explanation": "TRUNCATE is faster but cannot be filtered or rolled back in some contexts.", "db": "ecommerce_db"}, {"id": 122, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Insert a new patient and return the generated patient_id.", "sql": "INSERT INTO patients (first_name, last_name, dob, gender, blood_group) VALUES ('Jane', 'Smith', '1990-05-15', 'Female', 'O+') RETURNING patient_id;", "explanation": "RETURNING clause is PostgreSQL-specific — returns inserted values.", "db": "hospital_db"}, {"id": 123, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Update a product's price using a subquery (set to avg of its category).", "sql": "UPDATE products SET base_price = sub.avg_price FROM (SELECT category_id, AVG(base_price) AS avg_price FROM products GROUP BY category_id) sub WHERE products.category_id = sub.category_id AND products.base_price = 0;", "explanation": "UPDATE...FROM with subquery pattern.", "db": "ecommerce_db"}, {"id": 124, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Insert a new student into the students table.", "sql": "INSERT INTO students (program_id, first_name, last_name, email, roll_no, batch_year, status) VALUES (1, 'Alice', 'Johnson', 'alice@uni.edu', 'CS2025001', 2025, 'active');", "explanation": "", "db": "university_db"}, {"id": 125, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Update the balance of account after a credit transaction.", "sql": "UPDATE accounts SET balance = balance + 5000 WHERE account_id = 1;", "explanation": "Atomic increment avoids race conditions.", "db": "bank_db"}, {"id": 126, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Delete all expired stories (past 24 hours).", "sql": "DELETE FROM stories WHERE expires_at < NOW();", "explanation": "", "db": "social_db"}, {"id": 127, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Increment the used_count of a coupon by 1.", "sql": "UPDATE coupons SET used_count = used_count + 1 WHERE code = 'SAVE20';", "explanation": "", "db": "ecommerce_db"}, {"id": 128, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Deactivate all coupons that have exceeded their max_uses.", "sql": "UPDATE coupons SET is_active = FALSE WHERE used_count >= max_uses;", "explanation": "", "db": "ecommerce_db"}, {"id": 129, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Insert a new order and its items using RETURNING to chain.", "sql": "WITH new_order AS (\n  INSERT INTO orders (user_id, total_amount, status)\n  VALUES (1, 299.99, 'pending')\n  RETURNING order_id\n)\nINSERT INTO order_items (order_id, variant_id, quantity, unit_price)\nSELECT order_id, 5, 2, 149.99 FROM new_order;", "explanation": "CTE with INSERT...RETURNING to use the generated ID.", "db": "ecommerce_db"}, {"id": 130, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Update all staff salaries by a 10% raise in a department.", "sql": "UPDATE staff SET salary = salary * 1.10 WHERE dept_id = 3;", "explanation": "", "db": "hospital_db"}, {"id": 131, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Delete all unread notifications older than 90 days.", "sql": "DELETE FROM notifications WHERE is_read = FALSE AND created_at < NOW() - INTERVAL '90 days';", "explanation": "", "db": "social_db"}, {"id": 132, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Mark all pending appointments as cancelled for a specific doctor.", "sql": "UPDATE appointments SET status = 'cancelled' WHERE doctor_id = 5 AND status = 'scheduled';", "explanation": "", "db": "hospital_db"}, {"id": 133, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Insert a new course with INSERT INTO ... SELECT from another table.", "sql": "INSERT INTO courses (dept_id, code, name, credits)\nSELECT dept_id, 'CS999', 'Special Topics', 3\nFROM departments WHERE code = 'CS';", "explanation": "INSERT...SELECT copies data from one query into a table.", "db": "university_db"}, {"id": 134, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Upsert a user setting (insert or update on conflict).", "sql": "INSERT INTO user_settings (user_id, theme, language)\nVALUES (1, 'dark', 'en')\nON CONFLICT (user_id)\nDO UPDATE SET theme = EXCLUDED.theme, language = EXCLUDED.language;", "explanation": "ON CONFLICT DO UPDATE is PostgreSQL's UPSERT syntax.", "db": "social_db"}, {"id": 135, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Soft-delete a post by setting is_archived = TRUE.", "sql": "UPDATE posts SET is_archived = TRUE, updated_at = NOW() WHERE post_id = 42;", "explanation": "Soft delete preserves data for auditing.", "db": "social_db"}, {"id": 136, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Update the view_count of a post atomically.", "sql": "UPDATE posts SET view_count = view_count + 1 WHERE post_id = 42;", "explanation": "", "db": "social_db"}, {"id": 137, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Delete all cart items for a specific user's cart.", "sql": "DELETE FROM cart_items WHERE cart_id = (SELECT cart_id FROM carts WHERE user_id = 1);", "explanation": "Subquery in DELETE to find the right cart.", "db": "ecommerce_db"}, {"id": 138, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Swap the is_default flag between two addresses for a user.", "sql": "UPDATE addresses SET is_default = NOT is_default WHERE user_id = 1 AND address_id IN (2, 5);", "explanation": "", "db": "ecommerce_db"}, {"id": 139, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Insert a new branch and return all columns.", "sql": "INSERT INTO branches (bank_id, name, ifsc_code, city, state)\nVALUES (1, 'Downtown Branch', 'BANK0001234', 'Mumbai', 'Maharashtra')\nRETURNING *;", "explanation": "RETURNING * returns the full inserted row.", "db": "bank_db"}, {"id": 140, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Update the KYC status of all customers with verified documents.", "sql": "UPDATE customers c\nSET kyc_status = 'verified'\nFROM kyc_documents kd\nWHERE c.customer_id = kd.customer_id\nAND kd.verified = TRUE;", "explanation": "UPDATE...FROM joins another table during update.", "db": "bank_db"}, {"id": 141, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Delete duplicate reviews (keep the latest one per user/product).", "sql": "DELETE FROM reviews\nWHERE review_id NOT IN (\n  SELECT DISTINCT ON (user_id, product_id) review_id\n  FROM reviews\n  ORDER BY user_id, product_id, created_at DESC\n);", "explanation": "DISTINCT ON keeps one row per group — delete the rest.", "db": "ecommerce_db"}, {"id": 142, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Bulk update order statuses from a values list.", "sql": "UPDATE orders SET status = v.new_status\nFROM (VALUES (1,'shipped'),(2,'delivered'),(3,'cancelled')) AS v(oid, new_status)\nWHERE orders.order_id = v.oid;", "explanation": "VALUES clause creates an inline table for batch updates.", "db": "ecommerce_db"}, {"id": 143, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Archive all completed enrollments from the previous semester.", "sql": "UPDATE enrollments SET status = 'completed'\nWHERE section_id IN (\n  SELECT section_id FROM sections\n  WHERE semester_id = (\n    SELECT semester_id FROM semesters ORDER BY end_date DESC OFFSET 1 LIMIT 1\n  )\n);", "explanation": "Nested subquery to find previous semester.", "db": "university_db"}, {"id": 144, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Insert a new follow relationship with conflict handling.", "sql": "INSERT INTO follows (follower_id, following_id)\nVALUES (1, 2)\nON CONFLICT (follower_id, following_id) DO NOTHING;", "explanation": "ON CONFLICT DO NOTHING silently skips duplicates.", "db": "social_db"}, {"id": 145, "section": "Topic 4 — Data Modification (30 Qs)", "question": "Update room rates by 15% for all ICU rooms.", "sql": "UPDATE rooms SET rate_per_day = rate_per_day * 1.15 WHERE type = 'icu';", "explanation": "", "db": "hospital_db"}, {"id": 146, "section": "Topic 5 — String Operations (30 Qs)", "question": "Concatenate first_name and last_name with a space.", "sql": "SELECT CONCAT(first_name, ' ', last_name) AS full_name FROM patients;", "explanation": "CONCAT() handles NULLs better than || operator.", "db": "hospital_db"}, {"id": 147, "section": "Topic 5 — String Operations (30 Qs)", "question": "Convert all usernames to uppercase.", "sql": "SELECT UPPER(username) AS upper_name FROM users;", "explanation": "", "db": "ecommerce_db"}, {"id": 148, "section": "Topic 5 — String Operations (30 Qs)", "question": "Convert email addresses to lowercase.", "sql": "SELECT LOWER(email) AS lower_email FROM users;", "explanation": "", "db": "ecommerce_db"}, {"id": 149, "section": "Topic 5 — String Operations (30 Qs)", "question": "Trim whitespace from product names.", "sql": "SELECT TRIM(name) AS clean_name FROM products;", "explanation": "", "db": "ecommerce_db"}, {"id": 150, "section": "Topic 5 — String Operations (30 Qs)", "question": "Get the length of each product name.", "sql": "SELECT name, LENGTH(name) AS name_length FROM products ORDER BY name_length DESC;", "explanation": "", "db": "ecommerce_db"}, {"id": 151, "section": "Topic 5 — String Operations (30 Qs)", "question": "Extract the first 3 characters of each username.", "sql": "SELECT LEFT(username, 3) AS prefix FROM users;", "explanation": "LEFT() extracts from the start of the string.", "db": "ecommerce_db"}, {"id": 152, "section": "Topic 5 — String Operations (30 Qs)", "question": "Extract the domain from email addresses.", "sql": "SELECT email, SPLIT_PART(email, '@', 2) AS domain FROM users;", "explanation": "SPLIT_PART splits by delimiter and returns the nth part.", "db": "ecommerce_db"}, {"id": 153, "section": "Topic 5 — String Operations (30 Qs)", "question": "Find the position of '@' in email addresses.", "sql": "SELECT email, POSITION('@' IN email) AS at_pos FROM users;", "explanation": "", "db": "ecommerce_db"}, {"id": 154, "section": "Topic 5 — String Operations (30 Qs)", "question": "Replace 'customer' with 'buyer' in the role column.", "sql": "SELECT REPLACE(role, 'customer', 'buyer') AS updated_role FROM users;", "explanation": "", "db": "ecommerce_db"}, {"id": 155, "section": "Topic 5 — String Operations (30 Qs)", "question": "Pad account numbers with leading zeros to 20 characters.", "sql": "SELECT LPAD(account_no, 20, '0') AS padded_no FROM accounts;", "explanation": "LPAD left-pads a string to the specified length.", "db": "bank_db"}, {"id": 156, "section": "Topic 5 — String Operations (30 Qs)", "question": "Capitalize the first letter of each word in product names.", "sql": "SELECT INITCAP(name) AS title_case FROM products;", "explanation": "INITCAP() is PostgreSQL's title case function.", "db": "ecommerce_db"}, {"id": 157, "section": "Topic 5 — String Operations (30 Qs)", "question": "Find all products whose name contains 'pro' (case-insensitive).", "sql": "SELECT * FROM products WHERE name ILIKE '%pro%';", "explanation": "", "db": "ecommerce_db"}, {"id": 158, "section": "Topic 5 — String Operations (30 Qs)", "question": "Extract the year from a date stored as text.", "sql": "SELECT SUBSTRING(name FROM 1 FOR 4) AS prefix FROM products;", "explanation": "SUBSTRING extracts part of a string using position and length.", "db": "ecommerce_db"}, {"id": 159, "section": "Topic 5 — String Operations (30 Qs)", "question": "Reverse a string (product names).", "sql": "SELECT name, REVERSE(name) AS reversed FROM products LIMIT 5;", "explanation": "", "db": "ecommerce_db"}, {"id": 160, "section": "Topic 5 — String Operations (30 Qs)", "question": "Get the ASCII code of the first character of usernames.", "sql": "SELECT username, ASCII(username) AS first_char_code FROM users;", "explanation": "", "db": "ecommerce_db"}, {"id": 161, "section": "Topic 5 — String Operations (30 Qs)", "question": "Concatenate multiple fields with a separator using CONCAT_WS.", "sql": "SELECT CONCAT_WS(', ', street, city, state, country) AS full_address FROM addresses;", "explanation": "CONCAT_WS (with separator) joins non-null values.", "db": "ecommerce_db"}, {"id": 162, "section": "Topic 5 — String Operations (30 Qs)", "question": "Repeat a string N times.", "sql": "SELECT REPEAT('⭐', rating) AS stars, title FROM reviews;", "explanation": "Visual star rating using REPEAT().", "db": "ecommerce_db"}, {"id": 163, "section": "Topic 5 — String Operations (30 Qs)", "question": "Extract the local part of an email (before @).", "sql": "SELECT SPLIT_PART(email, '@', 1) AS local_part FROM users;", "explanation": "", "db": "ecommerce_db"}, {"id": 164, "section": "Topic 5 — String Operations (30 Qs)", "question": "Replace multiple characters using TRANSLATE.", "sql": "SELECT TRANSLATE(phone, '-() ', '') AS clean_phone FROM users;", "explanation": "TRANSLATE replaces each character individually — good for cleanup.", "db": "ecommerce_db"}, {"id": 165, "section": "Topic 5 — String Operations (30 Qs)", "question": "Format a product price as a currency string.", "sql": "SELECT name, '$' || TO_CHAR(base_price, 'FM999,999.00') AS formatted_price FROM products;", "explanation": "TO_CHAR formats numbers with patterns.", "db": "ecommerce_db"}, {"id": 166, "section": "Topic 5 — String Operations (30 Qs)", "question": "Find all users whose username starts with a vowel.", "sql": "SELECT * FROM users WHERE LOWER(LEFT(username, 1)) IN ('a','e','i','o','u');", "explanation": "", "db": "ecommerce_db"}, {"id": 167, "section": "Topic 5 — String Operations (30 Qs)", "question": "Create a slug from a product name (lowercase, hyphens).", "sql": "SELECT name, LOWER(REGEXP_REPLACE(name, '[^a-zA-Z0-9]+', '-', 'g')) AS slug FROM products;", "explanation": "REGEXP_REPLACE with 'g' flag for global replacement.", "db": "ecommerce_db"}, {"id": 168, "section": "Topic 5 — String Operations (30 Qs)", "question": "Mask a card number showing only last 4 digits.", "sql": "SELECT REPEAT('*', LENGTH(card_no)-4) || RIGHT(card_no, 4) AS masked FROM cards;", "explanation": "", "db": "bank_db"}, {"id": 169, "section": "Topic 5 — String Operations (30 Qs)", "question": "Split a comma-separated available_days into rows.", "sql": "SELECT doctor_id, UNNEST(STRING_TO_ARRAY(available_days, ',')) AS day FROM doctors;", "explanation": "STRING_TO_ARRAY + UNNEST expands delimited strings to rows.", "db": "hospital_db"}, {"id": 170, "section": "Topic 5 — String Operations (30 Qs)", "question": "Find usernames that match a pattern with regex.", "sql": "SELECT username FROM users WHERE username ~ '^[a-z]{3,}_\\d+$';", "explanation": "~ is PostgreSQL's regex match operator.", "db": "ecommerce_db"}, {"id": 171, "section": "Topic 5 — String Operations (30 Qs)", "question": "Calculate the MD5 hash of email addresses.", "sql": "SELECT email, MD5(email) AS email_hash FROM users;", "explanation": "", "db": "ecommerce_db"}, {"id": 172, "section": "Topic 5 — String Operations (30 Qs)", "question": "Right-pad course codes to 10 characters with dots.", "sql": "SELECT RPAD(code, 10, '.') AS padded_code FROM courses;", "explanation": "", "db": "university_db"}, {"id": 173, "section": "Topic 5 — String Operations (30 Qs)", "question": "Count words in post content.", "sql": "SELECT post_id, LENGTH(content) - LENGTH(REPLACE(content, ' ', '')) + 1 AS word_count FROM posts WHERE content IS NOT NULL;", "explanation": "Word count approximation using space counting.", "db": "social_db"}, {"id": 174, "section": "Topic 5 — String Operations (30 Qs)", "question": "Extract the file extension from image URLs.", "sql": "SELECT url, REVERSE(SPLIT_PART(REVERSE(url), '.', 1)) AS extension FROM product_images;", "explanation": "Reverse + split to get the last dot-separated part.", "db": "ecommerce_db"}, {"id": 175, "section": "Topic 5 — String Operations (30 Qs)", "question": "Format patient names as 'Last, First'.", "sql": "SELECT last_name || ', ' || first_name AS formatted_name FROM patients;", "explanation": "", "db": "hospital_db"}, {"id": 176, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Get the current date and time.", "sql": "SELECT NOW() AS current_timestamp, CURRENT_DATE AS today, CURRENT_TIME AS time_now;", "explanation": "NOW() returns timestamp with timezone.", "db": "ecommerce_db"}, {"id": 177, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Extract year, month, and day from order placed_at.", "sql": "SELECT order_id, EXTRACT(YEAR FROM placed_at) AS yr, EXTRACT(MONTH FROM placed_at) AS mo, EXTRACT(DAY FROM placed_at) AS dy FROM orders;", "explanation": "EXTRACT() pulls specific parts from dates.", "db": "ecommerce_db"}, {"id": 178, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Find all orders placed in the last 7 days.", "sql": "SELECT * FROM orders WHERE placed_at >= NOW() - INTERVAL '7 days';", "explanation": "INTERVAL arithmetic for relative date filtering.", "db": "ecommerce_db"}, {"id": 179, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Calculate the age of each patient from their DOB.", "sql": "SELECT first_name, last_name, dob, AGE(dob) AS age FROM patients;", "explanation": "AGE() returns an interval representing years/months/days.", "db": "hospital_db"}, {"id": 180, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Find all appointments scheduled for the next 3 days.", "sql": "SELECT * FROM appointments WHERE scheduled_at BETWEEN NOW() AND NOW() + INTERVAL '3 days';", "explanation": "", "db": "hospital_db"}, {"id": 181, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Format order dates as 'DD Mon YYYY'.", "sql": "SELECT order_id, TO_CHAR(placed_at, 'DD Mon YYYY') AS formatted_date FROM orders;", "explanation": "TO_CHAR() formats dates into custom string patterns.", "db": "ecommerce_db"}, {"id": 182, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Get the day of the week for each order.", "sql": "SELECT order_id, TO_CHAR(placed_at, 'Day') AS day_name FROM orders;", "explanation": "'Day' format gives the full day name.", "db": "ecommerce_db"}, {"id": 183, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Find orders placed on a Monday.", "sql": "SELECT * FROM orders WHERE EXTRACT(DOW FROM placed_at) = 1;", "explanation": "DOW: 0=Sunday, 1=Monday, ..., 6=Saturday.", "db": "ecommerce_db"}, {"id": 184, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Add 30 days to the current date.", "sql": "SELECT CURRENT_DATE + INTERVAL '30 days' AS future_date;", "explanation": "", "db": "ecommerce_db"}, {"id": 185, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Calculate the number of days between order placed_at and delivered_at.", "sql": "SELECT order_id, delivered_at::DATE - placed_at::DATE AS delivery_days FROM orders WHERE delivered_at IS NOT NULL;", "explanation": "Subtracting dates returns integer days in PostgreSQL.", "db": "ecommerce_db"}, {"id": 186, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Find all students enrolled in the current year.", "sql": "SELECT * FROM students WHERE EXTRACT(YEAR FROM enrolled_at) = EXTRACT(YEAR FROM NOW());", "explanation": "", "db": "university_db"}, {"id": 187, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Truncate timestamps to the month level.", "sql": "SELECT DATE_TRUNC('month', placed_at) AS order_month, COUNT(*) FROM orders GROUP BY order_month ORDER BY order_month;", "explanation": "DATE_TRUNC truncates to specified precision.", "db": "ecommerce_db"}, {"id": 188, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Find records from the last 30 days.", "sql": "SELECT * FROM transactions WHERE txn_date >= NOW() - INTERVAL '30 days';", "explanation": "", "db": "bank_db"}, {"id": 189, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Find the oldest and newest user registration dates.", "sql": "SELECT MIN(created_at) AS first_user, MAX(created_at) AS latest_user FROM users;", "explanation": "", "db": "ecommerce_db"}, {"id": 190, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Calculate how many months since each loan was disbursed.", "sql": "SELECT loan_id, EXTRACT(YEAR FROM AGE(disbursed_at)) * 12 + EXTRACT(MONTH FROM AGE(disbursed_at)) AS months_since FROM loans WHERE disbursed_at IS NOT NULL;", "explanation": "", "db": "bank_db"}, {"id": 191, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Count orders per month.", "sql": "SELECT TO_CHAR(placed_at, 'YYYY-MM') AS month, COUNT(*) AS order_count FROM orders GROUP BY month ORDER BY month;", "explanation": "", "db": "ecommerce_db"}, {"id": 192, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Find all coupons expiring in the next 7 days.", "sql": "SELECT * FROM coupons WHERE valid_until BETWEEN CURRENT_DATE AND CURRENT_DATE + 7;", "explanation": "Adding integer to DATE adds that many days.", "db": "ecommerce_db"}, {"id": 193, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Find the quarter of each transaction.", "sql": "SELECT txn_id, EXTRACT(QUARTER FROM txn_date) AS quarter FROM transactions;", "explanation": "QUARTER returns 1-4 for Q1-Q4.", "db": "bank_db"}, {"id": 194, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Generate a series of dates for the current month.", "sql": "SELECT d::DATE FROM GENERATE_SERIES(\n  DATE_TRUNC('month', CURRENT_DATE),\n  DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month' - INTERVAL '1 day',\n  INTERVAL '1 day'\n) AS d;", "explanation": "GENERATE_SERIES creates a set of sequential values.", "db": "ecommerce_db"}, {"id": 195, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Find users who registered on a weekend.", "sql": "SELECT * FROM users WHERE EXTRACT(DOW FROM created_at) IN (0, 6);", "explanation": "0=Sunday, 6=Saturday.", "db": "ecommerce_db"}, {"id": 196, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Calculate the duration of hospital admissions in days.", "sql": "SELECT admission_id, patient_id, COALESCE(discharged_at, NOW())::DATE - admitted_at::DATE AS stay_days FROM admissions;", "explanation": "COALESCE handles still-admitted patients.", "db": "hospital_db"}, {"id": 197, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Find the semester that a specific date falls into.", "sql": "SELECT * FROM semesters WHERE '2025-03-15' BETWEEN start_date AND end_date;", "explanation": "", "db": "university_db"}, {"id": 198, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Format timestamps with time component.", "sql": "SELECT order_id, TO_CHAR(placed_at, 'YYYY-MM-DD HH24:MI:SS') AS formatted FROM orders;", "explanation": "HH24 gives 24-hour format.", "db": "ecommerce_db"}, {"id": 199, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Find the first day of the current quarter.", "sql": "SELECT DATE_TRUNC('quarter', CURRENT_DATE) AS quarter_start;", "explanation": "", "db": "ecommerce_db"}, {"id": 200, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Calculate age in complete years only.", "sql": "SELECT first_name, EXTRACT(YEAR FROM AGE(dob))::INT AS age_years FROM patients;", "explanation": "", "db": "hospital_db"}, {"id": 201, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Find all FDs maturing in the next 30 days.", "sql": "SELECT * FROM fixed_deposits WHERE maturity_date BETWEEN CURRENT_DATE AND CURRENT_DATE + 30;", "explanation": "", "db": "bank_db"}, {"id": 202, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Find the time difference between story creation and expiry.", "sql": "SELECT story_id, expires_at - created_at AS duration FROM stories;", "explanation": "Timestamp subtraction returns INTERVAL.", "db": "social_db"}, {"id": 203, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Find orders grouped by day of the week with counts.", "sql": "SELECT TO_CHAR(placed_at, 'Day') AS day_name, COUNT(*) AS cnt FROM orders GROUP BY day_name ORDER BY cnt DESC;", "explanation": "", "db": "ecommerce_db"}, {"id": 204, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Convert a text date string to a proper date.", "sql": "SELECT TO_DATE('15-Mar-2025', 'DD-Mon-YYYY') AS parsed_date;", "explanation": "TO_DATE() parses text into DATE using a format pattern.", "db": "ecommerce_db"}, {"id": 205, "section": "Topic 6 — Date & Time Basics (30 Qs)", "question": "Find all records created in a specific ISO week.", "sql": "SELECT * FROM orders WHERE EXTRACT(WEEK FROM placed_at) = 10 AND EXTRACT(YEAR FROM placed_at) = 2025;", "explanation": "ISO week numbering (1-53).", "db": "ecommerce_db"}, {"id": 206, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find products priced above the overall average price.", "sql": "SELECT name, base_price FROM products WHERE base_price > (SELECT AVG(base_price) FROM products);", "explanation": "Scalar subquery returns a single value for comparison.", "db": "ecommerce_db"}, {"id": 207, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find the user who placed the most recent order.", "sql": "SELECT * FROM users WHERE user_id = (SELECT user_id FROM orders ORDER BY placed_at DESC LIMIT 1);", "explanation": "", "db": "ecommerce_db"}, {"id": 208, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find all products that have at least one review.", "sql": "SELECT * FROM products WHERE product_id IN (SELECT DISTINCT product_id FROM reviews);", "explanation": "IN subquery checks membership.", "db": "ecommerce_db"}, {"id": 209, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find products that have never been ordered.", "sql": "SELECT * FROM products WHERE product_id NOT IN (SELECT DISTINCT pv.product_id FROM order_items oi JOIN product_variants pv ON oi.variant_id = pv.variant_id);", "explanation": "", "db": "ecommerce_db"}, {"id": 210, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find users whose total spending is above the average user spending.", "sql": "SELECT user_id, SUM(total_amount) AS total FROM orders GROUP BY user_id HAVING SUM(total_amount) > (SELECT AVG(user_total) FROM (SELECT SUM(total_amount) AS user_total FROM orders GROUP BY user_id) sub);", "explanation": "Nested subquery: inner calculates per-user totals, outer averages them.", "db": "ecommerce_db"}, {"id": 211, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find orders where the total exceeds the user's average order.", "sql": "SELECT * FROM orders o WHERE total_amount > (SELECT AVG(total_amount) FROM orders WHERE user_id = o.user_id);", "explanation": "Correlated subquery references the outer query's row.", "db": "ecommerce_db"}, {"id": 212, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find users who have placed orders in every month of 2025.", "sql": "SELECT user_id FROM orders WHERE EXTRACT(YEAR FROM placed_at) = 2025 GROUP BY user_id HAVING COUNT(DISTINCT EXTRACT(MONTH FROM placed_at)) = 12;", "explanation": "", "db": "ecommerce_db"}, {"id": 213, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Use EXISTS to find users who have at least one order.", "sql": "SELECT * FROM users u WHERE EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.user_id);", "explanation": "EXISTS is often faster than IN for large datasets.", "db": "ecommerce_db"}, {"id": 214, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Use NOT EXISTS to find users with no orders.", "sql": "SELECT * FROM users u WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.user_id = u.user_id);", "explanation": "NOT EXISTS is an anti-semi-join pattern.", "db": "ecommerce_db"}, {"id": 215, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find departments where at least one doctor earns above 200000.", "sql": "SELECT * FROM departments d WHERE EXISTS (SELECT 1 FROM staff s WHERE s.dept_id = d.dept_id AND s.salary > 200000);", "explanation": "", "db": "hospital_db"}, {"id": 216, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find the most expensive product in each category using a subquery.", "sql": "SELECT * FROM products p WHERE base_price = (SELECT MAX(base_price) FROM products WHERE category_id = p.category_id);", "explanation": "Correlated subquery finds max per category.", "db": "ecommerce_db"}, {"id": 217, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find students whose GPA is higher than the average GPA of their program.", "sql": "SELECT * FROM students s WHERE gpa > (SELECT AVG(gpa) FROM students WHERE program_id = s.program_id);", "explanation": "", "db": "university_db"}, {"id": 218, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find accounts with balance above the branch average.", "sql": "SELECT * FROM accounts a WHERE balance > (SELECT AVG(balance) FROM accounts WHERE branch_id = a.branch_id);", "explanation": "", "db": "bank_db"}, {"id": 219, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Use ANY to find products cheaper than any product in category 3.", "sql": "SELECT * FROM products WHERE base_price < ANY (SELECT base_price FROM products WHERE category_id = 3);", "explanation": "ANY returns true if comparison is true for at least one subquery row.", "db": "ecommerce_db"}, {"id": 220, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Use ALL to find products more expensive than all products in category 1.", "sql": "SELECT * FROM products WHERE base_price > ALL (SELECT base_price FROM products WHERE category_id = 1);", "explanation": "ALL requires the comparison to be true for every row.", "db": "ecommerce_db"}, {"id": 221, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Subquery in FROM: Find the top 5 spending users with their details.", "sql": "SELECT u.username, sub.total_spent FROM users u JOIN (SELECT user_id, SUM(total_amount) AS total_spent FROM orders GROUP BY user_id ORDER BY total_spent DESC LIMIT 5) sub ON u.user_id = sub.user_id;", "explanation": "Derived table (subquery in FROM) is aliased and joined.", "db": "ecommerce_db"}, {"id": 222, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find the second highest salary among staff.", "sql": "SELECT MAX(salary) FROM staff WHERE salary < (SELECT MAX(salary) FROM staff);", "explanation": "Nested MAX to find second highest.", "db": "hospital_db"}, {"id": 223, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find posts with more likes than the average post.", "sql": "SELECT p.* FROM posts p WHERE (SELECT COUNT(*) FROM likes l WHERE l.post_id = p.post_id) > (SELECT AVG(cnt) FROM (SELECT COUNT(*) AS cnt FROM likes GROUP BY post_id) sub);", "explanation": "", "db": "social_db"}, {"id": 224, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find customers who have both savings and current accounts.", "sql": "SELECT * FROM customers c WHERE EXISTS (SELECT 1 FROM accounts a JOIN account_types at ON a.type_id = at.type_id WHERE a.customer_id = c.customer_id AND at.name = 'savings') AND EXISTS (SELECT 1 FROM accounts a JOIN account_types at ON a.type_id = at.type_id WHERE a.customer_id = c.customer_id AND at.name = 'current');", "explanation": "", "db": "bank_db"}, {"id": 225, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find the latest order for each user using a correlated subquery.", "sql": "SELECT * FROM orders o WHERE placed_at = (SELECT MAX(placed_at) FROM orders WHERE user_id = o.user_id);", "explanation": "", "db": "ecommerce_db"}, {"id": 226, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find products whose review count is above the median review count.", "sql": "SELECT p.product_id, p.name, COUNT(r.review_id) AS rev_count FROM products p JOIN reviews r ON p.product_id = r.product_id GROUP BY p.product_id, p.name HAVING COUNT(r.review_id) > (SELECT PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY cnt) FROM (SELECT COUNT(*) AS cnt FROM reviews GROUP BY product_id) sub);", "explanation": "", "db": "ecommerce_db"}, {"id": 227, "section": "Topic 7 — Subqueries (40 Qs)", "question": "List all doctors who have more appointments than the department average.", "sql": "SELECT d.doctor_id, COUNT(a.appointment_id) AS appt_count FROM doctors d JOIN appointments a ON d.doctor_id = a.doctor_id GROUP BY d.doctor_id HAVING COUNT(*) > (SELECT AVG(cnt) FROM (SELECT doctor_id, COUNT(*) AS cnt FROM appointments GROUP BY doctor_id) sub);", "explanation": "", "db": "hospital_db"}, {"id": 228, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find courses where the section capacity is above the average capacity.", "sql": "SELECT * FROM sections WHERE capacity > (SELECT AVG(capacity) FROM sections);", "explanation": "", "db": "university_db"}, {"id": 229, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find users who follow someone but are not followed back.", "sql": "SELECT DISTINCT f.follower_id FROM follows f WHERE NOT EXISTS (SELECT 1 FROM follows f2 WHERE f2.follower_id = f.following_id AND f2.following_id = f.follower_id);", "explanation": "", "db": "social_db"}, {"id": 230, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Scalar subquery in SELECT: show each order with the user's total order count.", "sql": "SELECT o.order_id, o.total_amount, (SELECT COUNT(*) FROM orders WHERE user_id = o.user_id) AS user_order_count FROM orders o;", "explanation": "Scalar subquery in SELECT list runs once per row.", "db": "ecommerce_db"}, {"id": 231, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find the brand with the highest average product price.", "sql": "SELECT b.name, AVG(p.base_price) AS avg_price FROM brands b JOIN products p ON b.brand_id = p.brand_id GROUP BY b.name ORDER BY avg_price DESC LIMIT 1;", "explanation": "", "db": "ecommerce_db"}, {"id": 232, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find patients with no medical records.", "sql": "SELECT * FROM patients p WHERE NOT EXISTS (SELECT 1 FROM medical_records mr WHERE mr.patient_id = p.patient_id);", "explanation": "", "db": "hospital_db"}, {"id": 233, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find all categories where every product is active.", "sql": "SELECT c.* FROM categories c WHERE NOT EXISTS (SELECT 1 FROM products p WHERE p.category_id = c.category_id AND p.is_active = FALSE) AND EXISTS (SELECT 1 FROM products p WHERE p.category_id = c.category_id);", "explanation": "Double EXISTS: ensure some products exist AND none are inactive.", "db": "ecommerce_db"}, {"id": 234, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find loans where at least one repayment is overdue.", "sql": "SELECT DISTINCT l.* FROM loans l WHERE EXISTS (SELECT 1 FROM loan_repayments lr WHERE lr.loan_id = l.loan_id AND lr.status = 'overdue');", "explanation": "", "db": "bank_db"}, {"id": 235, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Subquery rewrite: replace IN with JOIN for better performance.", "sql": "-- Slow: subquery\nSELECT * FROM products WHERE product_id IN (SELECT product_id FROM reviews WHERE rating = 5);\n\n-- Faster: JOIN\nSELECT DISTINCT p.* FROM products p JOIN reviews r ON p.product_id = r.product_id WHERE r.rating = 5;", "explanation": "JOINs often outperform IN subqueries for large tables.", "db": "ecommerce_db"}, {"id": 236, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find the top 3 departments by total salary expenditure.", "sql": "SELECT d.name, sub.total_salary FROM departments d JOIN (SELECT dept_id, SUM(salary) AS total_salary FROM staff GROUP BY dept_id ORDER BY total_salary DESC LIMIT 3) sub ON d.dept_id = sub.dept_id;", "explanation": "", "db": "hospital_db"}, {"id": 237, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find users whose first order was placed in 2025.", "sql": "SELECT DISTINCT user_id FROM orders WHERE user_id NOT IN (SELECT user_id FROM orders WHERE placed_at < '2025-01-01') AND EXTRACT(YEAR FROM placed_at) = 2025;", "explanation": "", "db": "ecommerce_db"}, {"id": 238, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find products in categories that have more than 10 products.", "sql": "SELECT * FROM products WHERE category_id IN (SELECT category_id FROM products GROUP BY category_id HAVING COUNT(*) > 10);", "explanation": "", "db": "ecommerce_db"}, {"id": 239, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find all students who scored above average in every assignment.", "sql": "SELECT s.student_id, s.first_name FROM students s WHERE NOT EXISTS (SELECT 1 FROM submissions sub JOIN assignments a ON sub.assignment_id = a.assignment_id WHERE sub.student_id = s.student_id AND sub.marks_obtained < (SELECT AVG(marks_obtained) FROM submissions WHERE assignment_id = sub.assignment_id));", "explanation": "", "db": "university_db"}, {"id": 240, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find the cheapest product variant for each product.", "sql": "SELECT * FROM product_variants pv WHERE price = (SELECT MIN(price) FROM product_variants WHERE product_id = pv.product_id);", "explanation": "", "db": "ecommerce_db"}, {"id": 241, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find instructors teaching more sections than the average.", "sql": "SELECT i.* FROM instructors i WHERE (SELECT COUNT(*) FROM sections WHERE instructor_id = i.instructor_id) > (SELECT AVG(cnt) FROM (SELECT COUNT(*) AS cnt FROM sections GROUP BY instructor_id) sub);", "explanation": "", "db": "university_db"}, {"id": 242, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find all orders where every item has quantity > 1.", "sql": "SELECT * FROM orders o WHERE NOT EXISTS (SELECT 1 FROM order_items oi WHERE oi.order_id = o.order_id AND oi.quantity <= 1) AND EXISTS (SELECT 1 FROM order_items oi WHERE oi.order_id = o.order_id);", "explanation": "", "db": "ecommerce_db"}, {"id": 243, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find users who have used all available payment methods.", "sql": "SELECT user_id FROM orders WHERE payment_method IS NOT NULL GROUP BY user_id HAVING COUNT(DISTINCT payment_method) = (SELECT COUNT(DISTINCT payment_method) FROM orders WHERE payment_method IS NOT NULL);", "explanation": "Division-like query: find users covering all distinct values.", "db": "ecommerce_db"}, {"id": 244, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find cards with transaction amounts above the card's average.", "sql": "SELECT ct.* FROM card_transactions ct WHERE ct.amount > (SELECT AVG(amount) FROM card_transactions WHERE card_id = ct.card_id);", "explanation": "", "db": "bank_db"}, {"id": 245, "section": "Topic 7 — Subqueries (40 Qs)", "question": "Find the most popular hashtag (most posts).", "sql": "SELECT h.tag, h.post_count FROM hashtags h WHERE h.post_count = (SELECT MAX(post_count) FROM hashtags);", "explanation": "", "db": "social_db"}, {"id": 246, "section": "Topic 8 — CTEs (35 Qs)", "question": "Basic CTE: Find users with their total order count.", "sql": "WITH user_orders AS (\n  SELECT user_id, COUNT(*) AS order_count\n  FROM orders GROUP BY user_id\n)\nSELECT u.username, COALESCE(uo.order_count, 0) AS orders\nFROM users u LEFT JOIN user_orders uo ON u.user_id = uo.user_id;", "explanation": "CTEs improve readability by naming intermediate result sets.", "db": "ecommerce_db"}, {"id": 247, "section": "Topic 8 — CTEs (35 Qs)", "question": "Multiple CTEs: Find users with both order count and total spending.", "sql": "WITH order_counts AS (\n  SELECT user_id, COUNT(*) AS cnt FROM orders GROUP BY user_id\n),\norder_totals AS (\n  SELECT user_id, SUM(total_amount) AS total FROM orders GROUP BY user_id\n)\nSELECT u.username, COALESCE(oc.cnt,0) AS orders, COALESCE(ot.total,0) AS spent\nFROM users u\nLEFT JOIN order_counts oc ON u.user_id = oc.user_id\nLEFT JOIN order_totals ot ON u.user_id = ot.user_id;", "explanation": "Multiple CTEs separated by commas.", "db": "ecommerce_db"}, {"id": 248, "section": "Topic 8 — CTEs (35 Qs)", "question": "CTE with aggregation: Average order value per month.", "sql": "WITH monthly AS (\n  SELECT DATE_TRUNC('month', placed_at) AS month, AVG(total_amount) AS avg_order\n  FROM orders GROUP BY month\n)\nSELECT TO_CHAR(month, 'YYYY-MM') AS month, ROUND(avg_order, 2) FROM monthly ORDER BY month;", "explanation": "", "db": "ecommerce_db"}, {"id": 249, "section": "Topic 8 — CTEs (35 Qs)", "question": "CTE referenced multiple times: Compare each user's spending to the average.", "sql": "WITH user_spend AS (\n  SELECT user_id, SUM(total_amount) AS total FROM orders GROUP BY user_id\n)\nSELECT us.user_id, us.total,\n  ROUND((SELECT AVG(total) FROM user_spend), 2) AS avg_spend,\n  CASE WHEN us.total > (SELECT AVG(total) FROM user_spend) THEN 'Above' ELSE 'Below' END AS vs_avg\nFROM user_spend us;", "explanation": "CTE can be referenced multiple times in the same query.", "db": "ecommerce_db"}, {"id": 250, "section": "Topic 8 — CTEs (35 Qs)", "question": "CTE for step-by-step logic: Identify VIP customers.", "sql": "WITH spending AS (\n  SELECT user_id, SUM(total_amount) AS total FROM orders GROUP BY user_id\n),\nvip AS (\n  SELECT user_id, total FROM spending WHERE total > 10000\n)\nSELECT u.username, u.email, v.total FROM vip v JOIN users u ON v.user_id = u.user_id ORDER BY v.total DESC;", "explanation": "Chain CTEs for readable multi-step analysis.", "db": "ecommerce_db"}, {"id": 251, "section": "Topic 8 — CTEs (35 Qs)", "question": "Recursive CTE: Traverse the category hierarchy.", "sql": "WITH RECURSIVE cat_tree AS (\n  SELECT category_id, name, parent_id, 0 AS depth\n  FROM categories WHERE parent_id IS NULL\n  UNION ALL\n  SELECT c.category_id, c.name, c.parent_id, ct.depth + 1\n  FROM categories c JOIN cat_tree ct ON c.parent_id = ct.category_id\n)\nSELECT * FROM cat_tree ORDER BY depth, name;", "explanation": "Recursive CTE: anchor (base case) UNION ALL recursive member.", "db": "ecommerce_db"}, {"id": 252, "section": "Topic 8 — CTEs (35 Qs)", "question": "Recursive CTE: Generate a number series 1 to 20.", "sql": "WITH RECURSIVE nums AS (\n  SELECT 1 AS n\n  UNION ALL\n  SELECT n + 1 FROM nums WHERE n < 20\n)\nSELECT n FROM nums;", "explanation": "Recursive number generation — stops when condition is false.", "db": "ecommerce_db"}, {"id": 253, "section": "Topic 8 — CTEs (35 Qs)", "question": "Recursive CTE: Find all sub-categories of category_id = 1.", "sql": "WITH RECURSIVE subcats AS (\n  SELECT category_id, name, parent_id FROM categories WHERE parent_id = 1\n  UNION ALL\n  SELECT c.category_id, c.name, c.parent_id FROM categories c JOIN subcats sc ON c.parent_id = sc.category_id\n)\nSELECT * FROM subcats;", "explanation": "Finds all descendants of a node in a tree.", "db": "ecommerce_db"}, {"id": 254, "section": "Topic 8 — CTEs (35 Qs)", "question": "Recursive CTE: Build the full path of each category.", "sql": "WITH RECURSIVE cat_path AS (\n  SELECT category_id, name, parent_id, name::TEXT AS path\n  FROM categories WHERE parent_id IS NULL\n  UNION ALL\n  SELECT c.category_id, c.name, c.parent_id, cp.path || ' > ' || c.name\n  FROM categories c JOIN cat_path cp ON c.parent_id = cp.category_id\n)\nSELECT category_id, path FROM cat_path ORDER BY path;", "explanation": "String concatenation in recursion builds breadcrumb paths.", "db": "ecommerce_db"}, {"id": 255, "section": "Topic 8 — CTEs (35 Qs)", "question": "Recursive CTE: Fibonacci sequence.", "sql": "WITH RECURSIVE fib AS (\n  SELECT 1 AS n, 0::BIGINT AS a, 1::BIGINT AS b\n  UNION ALL\n  SELECT n + 1, b, a + b FROM fib WHERE n < 20\n)\nSELECT n, a AS fibonacci FROM fib;", "explanation": "", "db": "ecommerce_db"}, {"id": 256, "section": "Topic 8 — CTEs (35 Qs)", "question": "CTE with INSERT: Archive old orders and return count.", "sql": "WITH archived AS (\n  DELETE FROM orders WHERE status = 'delivered' AND delivered_at < NOW() - INTERVAL '2 years'\n  RETURNING *\n)\nSELECT COUNT(*) AS archived_count FROM archived;", "explanation": "Writable CTE: DELETE inside CTE with RETURNING.", "db": "ecommerce_db"}, {"id": 257, "section": "Topic 8 — CTEs (35 Qs)", "question": "CTE to rank products by revenue.", "sql": "WITH product_revenue AS (\n  SELECT pv.product_id, SUM(oi.quantity * oi.unit_price) AS revenue\n  FROM order_items oi JOIN product_variants pv ON oi.variant_id = pv.variant_id\n  GROUP BY pv.product_id\n)\nSELECT p.name, pr.revenue FROM product_revenue pr JOIN products p ON pr.product_id = p.product_id ORDER BY pr.revenue DESC;", "explanation": "", "db": "ecommerce_db"}, {"id": 258, "section": "Topic 8 — CTEs (35 Qs)", "question": "CTE to find patients with most admissions.", "sql": "WITH admit_counts AS (\n  SELECT patient_id, COUNT(*) AS cnt FROM admissions GROUP BY patient_id\n)\nSELECT p.first_name, p.last_name, ac.cnt FROM admit_counts ac JOIN patients p ON ac.patient_id = p.patient_id ORDER BY ac.cnt DESC LIMIT 10;", "explanation": "", "db": "hospital_db"}, {"id": 259, "section": "Topic 8 — CTEs (35 Qs)", "question": "CTE to calculate department-wise budget.", "sql": "WITH dept_budget AS (\n  SELECT dept_id, SUM(salary) AS total_salary, COUNT(*) AS headcount\n  FROM staff GROUP BY dept_id\n)\nSELECT d.name, db.total_salary, db.headcount, ROUND(db.total_salary / db.headcount, 2) AS avg_salary\nFROM dept_budget db JOIN departments d ON db.dept_id = d.dept_id ORDER BY total_salary DESC;", "explanation": "", "db": "hospital_db"}, {"id": 260, "section": "Topic 8 — CTEs (35 Qs)", "question": "CTE to find top instructor by enrollments.", "sql": "WITH instr_enroll AS (\n  SELECT s.instructor_id, COUNT(e.enrollment_id) AS enroll_count\n  FROM sections s JOIN enrollments e ON s.section_id = e.section_id\n  GROUP BY s.instructor_id\n)\nSELECT i.first_name, i.last_name, ie.enroll_count\nFROM instr_enroll ie JOIN instructors i ON ie.instructor_id = i.instructor_id\nORDER BY ie.enroll_count DESC LIMIT 5;", "explanation": "", "db": "university_db"}, {"id": 261, "section": "Topic 8 — CTEs (35 Qs)", "question": "CTE to find account balance distribution.", "sql": "WITH balance_buckets AS (\n  SELECT CASE\n    WHEN balance < 1000 THEN 'Low (<1K)'\n    WHEN balance < 50000 THEN 'Medium (1K-50K)'\n    WHEN balance < 500000 THEN 'High (50K-500K)'\n    ELSE 'VIP (500K+)'\n  END AS bucket, COUNT(*) AS cnt\n  FROM accounts GROUP BY bucket\n)\nSELECT * FROM balance_buckets ORDER BY cnt DESC;", "explanation": "", "db": "bank_db"}, {"id": 262, "section": "Topic 8 — CTEs (35 Qs)", "question": "CTE to find the most engaged users on social media.", "sql": "WITH engagement AS (\n  SELECT user_id,\n    (SELECT COUNT(*) FROM posts WHERE user_id = u.user_id) AS posts,\n    (SELECT COUNT(*) FROM comments WHERE user_id = u.user_id) AS comments,\n    (SELECT COUNT(*) FROM likes WHERE user_id = u.user_id) AS likes\n  FROM users u\n)\nSELECT user_id, posts + comments + likes AS total_engagement\nFROM engagement ORDER BY total_engagement DESC LIMIT 10;", "explanation": "", "db": "social_db"}, {"id": 263, "section": "Topic 8 — CTEs (35 Qs)", "question": "Recursive CTE: Org chart — find all reports under a manager.", "sql": "WITH RECURSIVE reports AS (\n  SELECT staff_id, first_name, last_name, dept_id FROM staff WHERE staff_id = 1\n  UNION ALL\n  SELECT s.staff_id, s.first_name, s.last_name, s.dept_id\n  FROM staff s JOIN departments d ON s.dept_id = d.dept_id\n  JOIN reports r ON d.head_doc_id = r.staff_id\n  WHERE s.staff_id != r.staff_id\n)\nSELECT * FROM reports;", "explanation": "", "db": "hospital_db"}, {"id": 264, "section": "Topic 8 — CTEs (35 Qs)", "question": "CTE to pivot monthly order counts per status.", "sql": "WITH monthly AS (\n  SELECT DATE_TRUNC('month', placed_at) AS month, status, COUNT(*) AS cnt\n  FROM orders GROUP BY month, status\n)\nSELECT month,\n  SUM(CASE WHEN status='pending' THEN cnt END) AS pending,\n  SUM(CASE WHEN status='shipped' THEN cnt END) AS shipped,\n  SUM(CASE WHEN status='delivered' THEN cnt END) AS delivered\nFROM monthly GROUP BY month ORDER BY month;", "explanation": "", "db": "ecommerce_db"}, {"id": 265, "section": "Topic 8 — CTEs (35 Qs)", "question": "CTE to compute running order statistics.", "sql": "WITH daily AS (\n  SELECT placed_at::DATE AS day, COUNT(*) AS orders, SUM(total_amount) AS revenue\n  FROM orders GROUP BY day\n)\nSELECT day, orders, revenue,\n  SUM(revenue) OVER (ORDER BY day) AS cumulative_revenue\nFROM daily ORDER BY day;", "explanation": "CTE + window function combination.", "db": "ecommerce_db"}, {"id": 266, "section": "Topic 9 — Window Functions (45 Qs)", "question": "ROW_NUMBER: Assign a sequential number to each order per user.", "sql": "SELECT order_id, user_id, total_amount,\n  ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY placed_at) AS order_seq\nFROM orders;", "explanation": "ROW_NUMBER assigns unique sequential integers within each partition.", "db": "ecommerce_db"}, {"id": 267, "section": "Topic 9 — Window Functions (45 Qs)", "question": "RANK: Rank products by price within each category.", "sql": "SELECT product_id, name, category_id, base_price,\n  RANK() OVER (PARTITION BY category_id ORDER BY base_price DESC) AS price_rank\nFROM products;", "explanation": "RANK leaves gaps after ties (e.g., 1,2,2,4).", "db": "ecommerce_db"}, {"id": 268, "section": "Topic 9 — Window Functions (45 Qs)", "question": "DENSE_RANK: Rank without gaps.", "sql": "SELECT product_id, name, base_price,\n  DENSE_RANK() OVER (ORDER BY base_price DESC) AS dense_rnk\nFROM products;", "explanation": "DENSE_RANK has no gaps (e.g., 1,2,2,3).", "db": "ecommerce_db"}, {"id": 269, "section": "Topic 9 — Window Functions (45 Qs)", "question": "NTILE: Split products into 4 price quartiles.", "sql": "SELECT name, base_price,\n  NTILE(4) OVER (ORDER BY base_price) AS quartile\nFROM products;", "explanation": "NTILE divides rows into N roughly equal buckets.", "db": "ecommerce_db"}, {"id": 270, "section": "Topic 9 — Window Functions (45 Qs)", "question": "Running total: Cumulative revenue by date.", "sql": "SELECT placed_at::DATE AS day, total_amount,\n  SUM(total_amount) OVER (ORDER BY placed_at) AS running_total\nFROM orders ORDER BY placed_at;", "explanation": "SUM() OVER with ORDER BY creates a running total.", "db": "ecommerce_db"}, {"id": 271, "section": "Topic 9 — Window Functions (45 Qs)", "question": "Moving average: 7-day moving average of daily orders.", "sql": "WITH daily AS (\n  SELECT placed_at::DATE AS day, COUNT(*) AS cnt FROM orders GROUP BY day\n)\nSELECT day, cnt,\n  ROUND(AVG(cnt) OVER (ORDER BY day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW), 2) AS ma_7\nFROM daily ORDER BY day;", "explanation": "ROWS BETWEEN defines the window frame for the moving average.", "db": "ecommerce_db"}, {"id": 272, "section": "Topic 9 — Window Functions (45 Qs)", "question": "LAG: Compare each order's amount to the previous order for the same user.", "sql": "SELECT order_id, user_id, total_amount,\n  LAG(total_amount) OVER (PARTITION BY user_id ORDER BY placed_at) AS prev_amount,\n  total_amount - LAG(total_amount) OVER (PARTITION BY user_id ORDER BY placed_at) AS diff\nFROM orders;", "explanation": "LAG accesses a previous row's value.", "db": "ecommerce_db"}, {"id": 273, "section": "Topic 9 — Window Functions (45 Qs)", "question": "LEAD: Show the next appointment date for each patient.", "sql": "SELECT patient_id, scheduled_at,\n  LEAD(scheduled_at) OVER (PARTITION BY patient_id ORDER BY scheduled_at) AS next_appt\nFROM appointments;", "explanation": "LEAD accesses the next row's value.", "db": "hospital_db"}, {"id": 274, "section": "Topic 9 — Window Functions (45 Qs)", "question": "FIRST_VALUE: Find the cheapest product in each category.", "sql": "SELECT name, category_id, base_price,\n  FIRST_VALUE(name) OVER (PARTITION BY category_id ORDER BY base_price) AS cheapest\nFROM products;", "explanation": "FIRST_VALUE returns the first value in the window frame.", "db": "ecommerce_db"}, {"id": 275, "section": "Topic 9 — Window Functions (45 Qs)", "question": "LAST_VALUE: Find the most expensive product per category.", "sql": "SELECT name, category_id, base_price,\n  LAST_VALUE(name) OVER (PARTITION BY category_id ORDER BY base_price\n    ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS priciest\nFROM products;", "explanation": "LAST_VALUE needs the full frame specified to work correctly.", "db": "ecommerce_db"}, {"id": 276, "section": "Topic 9 — Window Functions (45 Qs)", "question": "Top N per group: Get the 3 most expensive products per category.", "sql": "SELECT * FROM (\n  SELECT name, category_id, base_price,\n    ROW_NUMBER() OVER (PARTITION BY category_id ORDER BY base_price DESC) AS rn\n  FROM products\n) t WHERE rn <= 3;", "explanation": "Classic top-N per group pattern using ROW_NUMBER.", "db": "ecommerce_db"}, {"id": 277, "section": "Topic 9 — Window Functions (45 Qs)", "question": "Percent of total: Each product's price as % of category total.", "sql": "SELECT name, category_id, base_price,\n  ROUND(base_price / SUM(base_price) OVER (PARTITION BY category_id) * 100, 2) AS pct_of_category\nFROM products;", "explanation": "Aggregate window function for per-partition totals.", "db": "ecommerce_db"}, {"id": 278, "section": "Topic 9 — Window Functions (45 Qs)", "question": "Cumulative count of orders per user.", "sql": "SELECT user_id, order_id, placed_at,\n  COUNT(*) OVER (PARTITION BY user_id ORDER BY placed_at) AS cumul_orders\nFROM orders;", "explanation": "", "db": "ecommerce_db"}, {"id": 279, "section": "Topic 9 — Window Functions (45 Qs)", "question": "CUME_DIST: Cumulative distribution of product prices.", "sql": "SELECT name, base_price,\n  ROUND(CUME_DIST() OVER (ORDER BY base_price)::NUMERIC, 4) AS cume_dist\nFROM products;", "explanation": "CUME_DIST returns the fraction of rows ≤ current row.", "db": "ecommerce_db"}, {"id": 280, "section": "Topic 9 — Window Functions (45 Qs)", "question": "PERCENT_RANK: Percentile rank of salaries.", "sql": "SELECT first_name, last_name, salary,\n  ROUND(PERCENT_RANK() OVER (ORDER BY salary)::NUMERIC, 4) AS pct_rank\nFROM staff;", "explanation": "PERCENT_RANK: (rank-1)/(total-1), ranges 0 to 1.", "db": "hospital_db"}, {"id": 281, "section": "Topic 9 — Window Functions (45 Qs)", "question": "Window SUM to show each order as % of user's total spending.", "sql": "SELECT order_id, user_id, total_amount,\n  SUM(total_amount) OVER (PARTITION BY user_id) AS user_total,\n  ROUND(total_amount / SUM(total_amount) OVER (PARTITION BY user_id) * 100, 2) AS pct\nFROM orders;", "explanation": "", "db": "ecommerce_db"}, {"id": 282, "section": "Topic 9 — Window Functions (45 Qs)", "question": "Rank students by GPA within each program.", "sql": "SELECT first_name, last_name, program_id, gpa,\n  RANK() OVER (PARTITION BY program_id ORDER BY gpa DESC) AS gpa_rank\nFROM students;", "explanation": "", "db": "university_db"}, {"id": 283, "section": "Topic 9 — Window Functions (45 Qs)", "question": "Running balance: Show the account balance after each transaction.", "sql": "SELECT txn_id, account_id, type, amount,\n  SUM(CASE WHEN type IN ('credit','transfer_in') THEN amount ELSE -amount END)\n    OVER (PARTITION BY account_id ORDER BY txn_date) AS running_balance\nFROM transactions;", "explanation": "", "db": "bank_db"}, {"id": 284, "section": "Topic 9 — Window Functions (45 Qs)", "question": "Gap detection: Find days between consecutive orders for each user.", "sql": "SELECT user_id, placed_at::DATE AS order_date,\n  placed_at::DATE - LAG(placed_at::DATE) OVER (PARTITION BY user_id ORDER BY placed_at) AS days_gap\nFROM orders;", "explanation": "LAG to detect gaps between events.", "db": "ecommerce_db"}, {"id": 285, "section": "Topic 9 — Window Functions (45 Qs)", "question": "Top earner per department.", "sql": "SELECT * FROM (\n  SELECT first_name, last_name, dept_id, salary,\n    ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC) AS rn\n  FROM staff\n) t WHERE rn = 1;", "explanation": "", "db": "hospital_db"}, {"id": 286, "section": "Topic 9 — Window Functions (45 Qs)", "question": "Moving sum over 3 months of revenue.", "sql": "WITH monthly AS (\n  SELECT DATE_TRUNC('month', placed_at) AS month, SUM(total_amount) AS revenue\n  FROM orders GROUP BY month\n)\nSELECT month, revenue,\n  SUM(revenue) OVER (ORDER BY month ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS rolling_3m\nFROM monthly;", "explanation": "", "db": "ecommerce_db"}, {"id": 287, "section": "Topic 9 — Window Functions (45 Qs)", "question": "Number each comment in a thread (by post, ordered by time).", "sql": "SELECT comment_id, post_id, content,\n  ROW_NUMBER() OVER (PARTITION BY post_id ORDER BY created_at) AS comment_num\nFROM comments;", "explanation": "", "db": "social_db"}, {"id": 288, "section": "Topic 9 — Window Functions (45 Qs)", "question": "Most recent 3 transactions per account.", "sql": "SELECT * FROM (\n  SELECT *, ROW_NUMBER() OVER (PARTITION BY account_id ORDER BY txn_date DESC) AS rn\n  FROM transactions\n) t WHERE rn <= 3;", "explanation": "", "db": "bank_db"}, {"id": 289, "section": "Topic 9 — Window Functions (45 Qs)", "question": "Show each review's rating vs the product's average rating.", "sql": "SELECT review_id, product_id, rating,\n  ROUND(AVG(rating) OVER (PARTITION BY product_id), 2) AS prod_avg,\n  rating - ROUND(AVG(rating) OVER (PARTITION BY product_id), 2) AS diff_from_avg\nFROM reviews;", "explanation": "", "db": "ecommerce_db"}, {"id": 290, "section": "Topic 9 — Window Functions (45 Qs)", "question": "Running count of followers over time.", "sql": "SELECT following_id, followed_at,\n  COUNT(*) OVER (PARTITION BY following_id ORDER BY followed_at) AS cumul_followers\nFROM follows;", "explanation": "", "db": "social_db"}, {"id": 291, "section": "Topic 9 — Window Functions (45 Qs)", "question": "Days since last transaction per account.", "sql": "SELECT account_id, txn_date,\n  txn_date - LAG(txn_date) OVER (PARTITION BY account_id ORDER BY txn_date) AS days_since_last\nFROM transactions;", "explanation": "", "db": "bank_db"}, {"id": 292, "section": "Topic 9 — Window Functions (45 Qs)", "question": "NTH_VALUE: Find the 2nd most expensive product per category.", "sql": "SELECT name, category_id, base_price,\n  NTH_VALUE(name, 2) OVER (PARTITION BY category_id ORDER BY base_price DESC\n    ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS second_priciest\nFROM products;", "explanation": "NTH_VALUE gets the Nth row in the window.", "db": "ecommerce_db"}, {"id": 293, "section": "Topic 9 — Window Functions (45 Qs)", "question": "ROWS vs RANGE: Demonstrate the difference.", "sql": "-- ROWS: counts exact row positions\nSELECT order_id, total_amount,\n  SUM(total_amount) OVER (ORDER BY total_amount ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING) AS rows_sum,\n  SUM(total_amount) OVER (ORDER BY total_amount RANGE BETWEEN 10 PRECEDING AND 10 FOLLOWING) AS range_sum\nFROM orders LIMIT 20;", "explanation": "ROWS = physical rows. RANGE = logical value range.", "db": "ecommerce_db"}, {"id": 294, "section": "Topic 9 — Window Functions (45 Qs)", "question": "Rank posts by engagement (likes + comments).", "sql": "WITH engagement AS (\n  SELECT p.post_id, p.content,\n    COUNT(DISTINCT l.like_id) AS likes,\n    COUNT(DISTINCT c.comment_id) AS comments\n  FROM posts p LEFT JOIN likes l ON p.post_id = l.post_id\n  LEFT JOIN comments c ON p.post_id = c.post_id\n  GROUP BY p.post_id, p.content\n)\nSELECT *, RANK() OVER (ORDER BY likes + comments DESC) AS eng_rank FROM engagement;", "explanation": "", "db": "social_db"}, {"id": 295, "section": "Topic 9 — Window Functions (45 Qs)", "question": "Identify consecutive days a user placed orders (streak).", "sql": "WITH user_days AS (\n  SELECT DISTINCT user_id, placed_at::DATE AS d FROM orders\n),\nstreaks AS (\n  SELECT *, d - ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY d)::INT AS grp\n  FROM user_days\n)\nSELECT user_id, MIN(d) AS streak_start, MAX(d) AS streak_end, COUNT(*) AS streak_len\nFROM streaks GROUP BY user_id, grp HAVING COUNT(*) >= 3 ORDER BY streak_len DESC;", "explanation": "Classic gaps-and-islands using ROW_NUMBER.", "db": "ecommerce_db"}, {"id": 296, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "FILTER clause: Count orders by status in one query.", "sql": "SELECT\n  COUNT(*) FILTER (WHERE status = 'pending') AS pending,\n  COUNT(*) FILTER (WHERE status = 'shipped') AS shipped,\n  COUNT(*) FILTER (WHERE status = 'delivered') AS delivered,\n  COUNT(*) FILTER (WHERE status = 'cancelled') AS cancelled\nFROM orders;", "explanation": "FILTER is PostgreSQL's elegant conditional aggregate.", "db": "ecommerce_db"}, {"id": 297, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "GROUPING SETS: Get totals by category, brand, and overall.", "sql": "SELECT category_id, brand_id, COUNT(*) AS cnt, SUM(base_price) AS total_price\nFROM products\nGROUP BY GROUPING SETS ((category_id), (brand_id), ());", "explanation": "GROUPING SETS produces multiple GROUP BY in one query.", "db": "ecommerce_db"}, {"id": 298, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "ROLLUP: Subtotals and grand total for orders by status and month.", "sql": "SELECT status, DATE_TRUNC('month', placed_at)::DATE AS month, COUNT(*), SUM(total_amount)\nFROM orders\nGROUP BY ROLLUP (status, DATE_TRUNC('month', placed_at)::DATE)\nORDER BY status NULLS LAST, month NULLS LAST;", "explanation": "ROLLUP creates hierarchical subtotals.", "db": "ecommerce_db"}, {"id": 299, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "CUBE: All combinations of category and brand.", "sql": "SELECT category_id, brand_id, COUNT(*), AVG(base_price)::NUMERIC(10,2)\nFROM products\nGROUP BY CUBE (category_id, brand_id)\nORDER BY category_id NULLS LAST, brand_id NULLS LAST;", "explanation": "CUBE generates all possible grouping combinations.", "db": "ecommerce_db"}, {"id": 300, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "Conditional aggregate: Pivot gender counts per department.", "sql": "SELECT dept_id,\n  COUNT(*) FILTER (WHERE role = 'doctor') AS doctors,\n  COUNT(*) FILTER (WHERE role = 'nurse') AS nurses,\n  COUNT(*) FILTER (WHERE role = 'admin') AS admins\nFROM staff GROUP BY dept_id;", "explanation": "SUM(CASE WHEN) also works but FILTER is cleaner.", "db": "hospital_db"}, {"id": 301, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "Pivot: Monthly revenue by year.", "sql": "SELECT EXTRACT(MONTH FROM placed_at) AS month,\n  SUM(total_amount) FILTER (WHERE EXTRACT(YEAR FROM placed_at) = 2024) AS y2024,\n  SUM(total_amount) FILTER (WHERE EXTRACT(YEAR FROM placed_at) = 2025) AS y2025\nFROM orders GROUP BY month ORDER BY month;", "explanation": "", "db": "ecommerce_db"}, {"id": 302, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "PERCENTILE_CONT: Find the median product price.", "sql": "SELECT PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY base_price) AS median_price FROM products;", "explanation": "PERCENTILE_CONT interpolates between values.", "db": "ecommerce_db"}, {"id": 303, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "PERCENTILE_DISC: Find the exact median (discrete).", "sql": "SELECT PERCENTILE_DISC(0.5) WITHIN GROUP (ORDER BY base_price) AS median_price FROM products;", "explanation": "PERCENTILE_DISC returns an actual value from the set.", "db": "ecommerce_db"}, {"id": 304, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "MODE: Find the most common order status.", "sql": "SELECT MODE() WITHIN GROUP (ORDER BY status) AS most_common_status FROM orders;", "explanation": "MODE returns the most frequent value.", "db": "ecommerce_db"}, {"id": 305, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "ARRAY_AGG: Collect all product names per category.", "sql": "SELECT c.name AS category, ARRAY_AGG(p.name ORDER BY p.name) AS products\nFROM products p JOIN categories c ON p.category_id = c.category_id\nGROUP BY c.name;", "explanation": "ARRAY_AGG builds an array from grouped values.", "db": "ecommerce_db"}, {"id": 306, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "STRING_AGG: Comma-separated list of skills per doctor.", "sql": "SELECT doctor_id, STRING_AGG(specialization, ', ' ORDER BY specialization) AS specializations\nFROM doctors GROUP BY doctor_id;", "explanation": "STRING_AGG concatenates with a delimiter.", "db": "hospital_db"}, {"id": 307, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "JSON_AGG: Return orders as JSON array per user.", "sql": "SELECT user_id, JSON_AGG(JSON_BUILD_OBJECT('id', order_id, 'amount', total_amount, 'status', status)) AS orders_json\nFROM orders GROUP BY user_id;", "explanation": "JSON_AGG is powerful for API-style responses.", "db": "ecommerce_db"}, {"id": 308, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "BOOL_AND / BOOL_OR: Check if all/any reviews are verified.", "sql": "SELECT product_id,\n  BOOL_AND(is_verified) AS all_verified,\n  BOOL_OR(is_verified) AS any_verified\nFROM reviews GROUP BY product_id;", "explanation": "BOOL_AND=true only if all are true; BOOL_OR=true if any is true.", "db": "ecommerce_db"}, {"id": 309, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "Conditional SUM for revenue vs refunds.", "sql": "SELECT DATE_TRUNC('month', placed_at) AS month,\n  SUM(total_amount) FILTER (WHERE status != 'refunded') AS revenue,\n  SUM(total_amount) FILTER (WHERE status = 'refunded') AS refunds\nFROM orders GROUP BY month ORDER BY month;", "explanation": "", "db": "ecommerce_db"}, {"id": 310, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "ROLLUP with named levels using GROUPING().", "sql": "SELECT\n  CASE WHEN GROUPING(status) = 1 THEN 'ALL' ELSE status END AS status,\n  COUNT(*), SUM(total_amount)\nFROM orders GROUP BY ROLLUP(status);", "explanation": "GROUPING() returns 1 for aggregated (null) groups.", "db": "ecommerce_db"}, {"id": 311, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "Count votes per poll option with percentage.", "sql": "SELECT po.poll_id, po.option_text, po.vote_count,\n  ROUND(po.vote_count * 100.0 / SUM(po.vote_count) OVER (PARTITION BY po.poll_id), 1) AS pct\nFROM poll_options po ORDER BY po.poll_id, po.vote_count DESC;", "explanation": "", "db": "social_db"}, {"id": 312, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "Find the P90 transaction amount.", "sql": "SELECT PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY amount) AS p90_amount FROM transactions;", "explanation": "90th percentile — useful for SLA analysis.", "db": "bank_db"}, {"id": 313, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "ARRAY_AGG with DISTINCT to get unique values.", "sql": "SELECT user_id, ARRAY_AGG(DISTINCT payment_method ORDER BY payment_method) AS methods_used\nFROM orders WHERE payment_method IS NOT NULL GROUP BY user_id;", "explanation": "", "db": "ecommerce_db"}, {"id": 314, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "Multiple FILTER aggregates for attendance summary.", "sql": "SELECT section_id,\n  COUNT(*) FILTER (WHERE status = 'present') AS present,\n  COUNT(*) FILTER (WHERE status = 'absent') AS absent,\n  COUNT(*) FILTER (WHERE status = 'late') AS late,\n  ROUND(COUNT(*) FILTER (WHERE status = 'present') * 100.0 / COUNT(*), 1) AS attendance_pct\nFROM attendance GROUP BY section_id;", "explanation": "", "db": "university_db"}, {"id": 315, "section": "Topic 10 — Advanced Aggregates (30 Qs)", "question": "STRING_AGG hashtags for each post.", "sql": "SELECT p.post_id, STRING_AGG(h.tag, ', ' ORDER BY h.tag) AS hashtags\nFROM post_hashtags ph JOIN hashtags h ON ph.hashtag_id = h.hashtag_id JOIN posts p ON ph.post_id = p.post_id\nGROUP BY p.post_id;", "explanation": "", "db": "social_db"}, {"id": 316, "section": "Topic 11 — Set Operations (20 Qs)", "question": "UNION: Combine active customers from two sources.", "sql": "SELECT user_id, username, email FROM users WHERE role = 'customer'\nUNION\nSELECT user_id, username, email FROM users WHERE role = 'vendor';", "explanation": "UNION removes duplicates from the combined result.", "db": "ecommerce_db"}, {"id": 317, "section": "Topic 11 — Set Operations (20 Qs)", "question": "UNION ALL: Keep all rows including duplicates.", "sql": "SELECT product_id, 'reviewed' AS status FROM reviews\nUNION ALL\nSELECT product_id, 'wishlisted' FROM wishlists;", "explanation": "UNION ALL is faster since it skips deduplication.", "db": "ecommerce_db"}, {"id": 318, "section": "Topic 11 — Set Operations (20 Qs)", "question": "INTERSECT: Find users who are both buyers and reviewers.", "sql": "SELECT user_id FROM orders\nINTERSECT\nSELECT user_id FROM reviews;", "explanation": "INTERSECT returns only rows present in both queries.", "db": "ecommerce_db"}, {"id": 319, "section": "Topic 11 — Set Operations (20 Qs)", "question": "EXCEPT: Find users who ordered but never wrote a review.", "sql": "SELECT user_id FROM orders\nEXCEPT\nSELECT user_id FROM reviews;", "explanation": "EXCEPT returns rows in the first query not in the second.", "db": "ecommerce_db"}, {"id": 320, "section": "Topic 11 — Set Operations (20 Qs)", "question": "UNION with ORDER BY on the combined result.", "sql": "(SELECT 'Order' AS type, order_id AS id, placed_at AS ts FROM orders)\nUNION ALL\n(SELECT 'Payment', payment_id, paid_at FROM payments WHERE paid_at IS NOT NULL)\nORDER BY ts DESC LIMIT 20;", "explanation": "ORDER BY applies to the final combined result.", "db": "ecommerce_db"}, {"id": 321, "section": "Topic 11 — Set Operations (20 Qs)", "question": "Combine doctors and patients into a single contact list.", "sql": "SELECT first_name, last_name, 'Doctor' AS type FROM staff WHERE role = 'doctor'\nUNION\nSELECT first_name, last_name, 'Patient' FROM patients;", "explanation": "", "db": "hospital_db"}, {"id": 322, "section": "Topic 11 — Set Operations (20 Qs)", "question": "Find students enrolled in both CS101 and MATH201.", "sql": "SELECT student_id FROM enrollments e JOIN sections s ON e.section_id = s.section_id JOIN courses c ON s.course_id = c.course_id WHERE c.code = 'CS101'\nINTERSECT\nSELECT student_id FROM enrollments e JOIN sections s ON e.section_id = s.section_id JOIN courses c ON s.course_id = c.course_id WHERE c.code = 'MATH201';", "explanation": "", "db": "university_db"}, {"id": 323, "section": "Topic 11 — Set Operations (20 Qs)", "question": "Find customers who have accounts but no loans.", "sql": "SELECT customer_id FROM accounts\nEXCEPT\nSELECT customer_id FROM loans;", "explanation": "", "db": "bank_db"}, {"id": 324, "section": "Topic 11 — Set Operations (20 Qs)", "question": "UNION to create a unified activity feed.", "sql": "SELECT user_id, 'post' AS action, created_at FROM posts\nUNION ALL\nSELECT user_id, 'comment', created_at FROM comments\nUNION ALL\nSELECT user_id, 'like', liked_at FROM likes\nORDER BY created_at DESC LIMIT 50;", "explanation": "", "db": "social_db"}, {"id": 325, "section": "Topic 11 — Set Operations (20 Qs)", "question": "EXCEPT: Find products in category 1 but not in any order.", "sql": "SELECT product_id FROM products WHERE category_id = 1\nEXCEPT\nSELECT pv.product_id FROM order_items oi JOIN product_variants pv ON oi.variant_id = pv.variant_id;", "explanation": "", "db": "ecommerce_db"}, {"id": 326, "section": "Topic 11 — Set Operations (20 Qs)", "question": "Set operations with aggregates.", "sql": "SELECT 'Total Orders' AS metric, COUNT(*)::TEXT AS value FROM orders\nUNION ALL\nSELECT 'Total Revenue', ROUND(SUM(total_amount), 2)::TEXT FROM orders\nUNION ALL\nSELECT 'Avg Order Value', ROUND(AVG(total_amount), 2)::TEXT FROM orders;", "explanation": "Build a summary report using UNION ALL.", "db": "ecommerce_db"}, {"id": 327, "section": "Topic 11 — Set Operations (20 Qs)", "question": "Find hashtags used in public posts but not in private ones.", "sql": "SELECT DISTINCT h.tag FROM post_hashtags ph JOIN posts p ON ph.post_id = p.post_id JOIN hashtags h ON ph.hashtag_id = h.hashtag_id WHERE p.visibility = 'public'\nEXCEPT\nSELECT DISTINCT h.tag FROM post_hashtags ph JOIN posts p ON ph.post_id = p.post_id JOIN hashtags h ON ph.hashtag_id = h.hashtag_id WHERE p.visibility = 'private';", "explanation": "", "db": "social_db"}, {"id": 328, "section": "Topic 12 — CASE Expressions & Conditional Logic (30 Qs)", "question": "Simple CASE: Label orders by amount tier.", "sql": "SELECT order_id, total_amount,\n  CASE\n    WHEN total_amount < 100 THEN 'Small'\n    WHEN total_amount < 500 THEN 'Medium'\n    WHEN total_amount < 2000 THEN 'Large'\n    ELSE 'Premium'\n  END AS order_tier\nFROM orders;", "explanation": "Searched CASE evaluates conditions in order, returns first match.", "db": "ecommerce_db"}, {"id": 329, "section": "Topic 12 — CASE Expressions & Conditional Logic (30 Qs)", "question": "Simple CASE with equality: Map status codes.", "sql": "SELECT order_id,\n  CASE status\n    WHEN 'pending' THEN '⏳ Pending'\n    WHEN 'shipped' THEN '🚚 Shipped'\n    WHEN 'delivered' THEN '✅ Delivered'\n    WHEN 'cancelled' THEN '❌ Cancelled'\n    ELSE '❓ Unknown'\n  END AS status_label\nFROM orders;", "explanation": "Simple CASE compares one expression against multiple values.", "db": "ecommerce_db"}, {"id": 330, "section": "Topic 12 — CASE Expressions & Conditional Logic (30 Qs)", "question": "CASE in ORDER BY: Custom sort priority.", "sql": "SELECT * FROM orders ORDER BY\n  CASE status\n    WHEN 'pending' THEN 1\n    WHEN 'shipped' THEN 2\n    WHEN 'delivered' THEN 3\n    WHEN 'cancelled' THEN 4\n    ELSE 5\n  END;", "explanation": "CASE in ORDER BY enables custom sort orders.", "db": "ecommerce_db"}, {"id": 331, "section": "Topic 12 — CASE Expressions & Conditional Logic (30 Qs)", "question": "CASE with aggregate: Conditional counting.", "sql": "SELECT\n  SUM(CASE WHEN rating >= 4 THEN 1 ELSE 0 END) AS positive,\n  SUM(CASE WHEN rating = 3 THEN 1 ELSE 0 END) AS neutral,\n  SUM(CASE WHEN rating <= 2 THEN 1 ELSE 0 END) AS negative\nFROM reviews;", "explanation": "CASE inside SUM for cross-tabulation / pivot.", "db": "ecommerce_db"}, {"id": 332, "section": "Topic 12 — CASE Expressions & Conditional Logic (30 Qs)", "question": "CASE to create a Boolean flag.", "sql": "SELECT product_id, name,\n  CASE WHEN base_price > 500 THEN TRUE ELSE FALSE END AS is_premium\nFROM products;", "explanation": "", "db": "ecommerce_db"}, {"id": 333, "section": "Topic 12 — CASE Expressions & Conditional Logic (30 Qs)", "question": "COALESCE: Replace NULL with a default.", "sql": "SELECT username, COALESCE(phone, 'N/A') AS phone FROM users;", "explanation": "COALESCE returns the first non-null value.", "db": "ecommerce_db"}, {"id": 334, "section": "Topic 12 — CASE Expressions & Conditional Logic (30 Qs)", "question": "NULLIF: Avoid division by zero.", "sql": "SELECT coupon_id, code, used_count, max_uses,\n  ROUND(used_count * 100.0 / NULLIF(max_uses, 0), 1) AS usage_pct\nFROM coupons;", "explanation": "NULLIF returns NULL if both args are equal, preventing /0.", "db": "ecommerce_db"}, {"id": 335, "section": "Topic 12 — CASE Expressions & Conditional Logic (30 Qs)", "question": "GREATEST and LEAST for clamping values.", "sql": "SELECT product_id, stock_qty,\n  GREATEST(stock_qty, 0) AS safe_stock,\n  LEAST(stock_qty, 100) AS capped_stock\nFROM product_variants;", "explanation": "GREATEST/LEAST return max/min of their arguments.", "db": "ecommerce_db"}, {"id": 336, "section": "Topic 12 — CASE Expressions & Conditional Logic (30 Qs)", "question": "Nested CASE for complex classification.", "sql": "SELECT patient_id, first_name,\n  CASE\n    WHEN EXTRACT(YEAR FROM AGE(dob)) < 18 THEN 'Pediatric'\n    WHEN EXTRACT(YEAR FROM AGE(dob)) BETWEEN 18 AND 64 THEN\n      CASE gender WHEN 'Male' THEN 'Adult Male' ELSE 'Adult Female' END\n    ELSE 'Geriatric'\n  END AS category\nFROM patients;", "explanation": "Nested CASE for multi-dimensional classification.", "db": "hospital_db"}, {"id": 337, "section": "Topic 12 — CASE Expressions & Conditional Logic (30 Qs)", "question": "CASE in UPDATE statement.", "sql": "UPDATE orders SET payment_status =\n  CASE\n    WHEN total_amount = 0 THEN 'free'\n    WHEN payment_method IS NULL THEN 'unpaid'\n    ELSE 'paid'\n  END\nWHERE payment_status IS NULL;", "explanation": "", "db": "ecommerce_db"}, {"id": 338, "section": "Topic 12 — CASE Expressions & Conditional Logic (30 Qs)", "question": "Label students by GPA band.", "sql": "SELECT first_name, last_name, gpa,\n  CASE\n    WHEN gpa >= 3.7 THEN 'Dean''s List'\n    WHEN gpa >= 3.0 THEN 'Honor Roll'\n    WHEN gpa >= 2.0 THEN 'Good Standing'\n    ELSE 'Academic Probation'\n  END AS standing\nFROM students;", "explanation": "", "db": "university_db"}, {"id": 339, "section": "Topic 12 — CASE Expressions & Conditional Logic (30 Qs)", "question": "CASE to classify transactions.", "sql": "SELECT txn_id, amount,\n  CASE type\n    WHEN 'credit' THEN '+' || amount::TEXT\n    WHEN 'debit' THEN '-' || amount::TEXT\n    ELSE amount::TEXT\n  END AS display_amount\nFROM transactions;", "explanation": "", "db": "bank_db"}, {"id": 340, "section": "Topic 12 — CASE Expressions & Conditional Logic (30 Qs)", "question": "CASE for custom date ranges.", "sql": "SELECT order_id, placed_at,\n  CASE\n    WHEN placed_at >= NOW() - INTERVAL '7 days' THEN 'This Week'\n    WHEN placed_at >= NOW() - INTERVAL '30 days' THEN 'This Month'\n    WHEN placed_at >= NOW() - INTERVAL '90 days' THEN 'This Quarter'\n    ELSE 'Older'\n  END AS recency\nFROM orders;", "explanation": "", "db": "ecommerce_db"}, {"id": 341, "section": "Topic 12 — CASE Expressions & Conditional Logic (30 Qs)", "question": "Use CASE to pivot attendance.", "sql": "SELECT student_id,\n  SUM(CASE WHEN status = 'present' THEN 1 ELSE 0 END) AS present_days,\n  SUM(CASE WHEN status = 'absent' THEN 1 ELSE 0 END) AS absent_days,\n  ROUND(SUM(CASE WHEN status = 'present' THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 1) AS pct\nFROM attendance GROUP BY student_id;", "explanation": "", "db": "university_db"}, {"id": 342, "section": "Topic 12 — CASE Expressions & Conditional Logic (30 Qs)", "question": "CASE with IN for grouping.", "sql": "SELECT post_id, type,\n  CASE\n    WHEN type IN ('text', 'link') THEN 'Text-based'\n    WHEN type IN ('image', 'video', 'story') THEN 'Media'\n    ELSE 'Other'\n  END AS content_type\nFROM posts;", "explanation": "", "db": "social_db"}, {"id": 343, "section": "Topic 12 — CASE Expressions & Conditional Logic (30 Qs)", "question": "COALESCE chain: Multi-level fallback.", "sql": "SELECT COALESCE(phone, email, username) AS contact FROM users;", "explanation": "COALESCE checks arguments left-to-right, returns first non-null.", "db": "ecommerce_db"}, {"id": 344, "section": "Topic 12 — CASE Expressions & Conditional Logic (30 Qs)", "question": "CASE in JOIN condition.", "sql": "SELECT o.order_id, o.total_amount, c.code AS coupon_used\nFROM orders o\nLEFT JOIN coupons c ON c.coupon_id = (\n  CASE WHEN o.discount_amount > 0 THEN o.order_id END\n);", "explanation": "CASE can control join behavior dynamically.", "db": "ecommerce_db"}, {"id": 345, "section": "Topic 12 — CASE Expressions & Conditional Logic (30 Qs)", "question": "Classify loan risk using CASE.", "sql": "SELECT loan_id, principal, interest_rate,\n  CASE\n    WHEN interest_rate < 8 THEN 'Low Risk'\n    WHEN interest_rate < 15 THEN 'Medium Risk'\n    ELSE 'High Risk'\n  END AS risk_level\nFROM loans;", "explanation": "", "db": "bank_db"}, {"id": 346, "section": "Topic 13 — Date/Time Advanced (25 Qs)", "question": "EXTRACT all parts from a timestamp.", "sql": "SELECT NOW() AS ts,\n  EXTRACT(YEAR FROM NOW()) AS yr, EXTRACT(MONTH FROM NOW()) AS mo,\n  EXTRACT(DAY FROM NOW()) AS dy, EXTRACT(HOUR FROM NOW()) AS hr,\n  EXTRACT(MINUTE FROM NOW()) AS min, EXTRACT(SECOND FROM NOW()) AS sec,\n  EXTRACT(DOW FROM NOW()) AS dow, EXTRACT(EPOCH FROM NOW()) AS epoch;", "explanation": "", "db": "ecommerce_db"}, {"id": 347, "section": "Topic 13 — Date/Time Advanced (25 Qs)", "question": "Find gaps between consecutive appointments per doctor.", "sql": "SELECT doctor_id, scheduled_at,\n  scheduled_at - LAG(scheduled_at) OVER (PARTITION BY doctor_id ORDER BY scheduled_at) AS gap\nFROM appointments;", "explanation": "Window function + timestamp arithmetic for gap analysis.", "db": "hospital_db"}, {"id": 348, "section": "Topic 13 — Date/Time Advanced (25 Qs)", "question": "DATE_TRUNC at various levels.", "sql": "SELECT\n  DATE_TRUNC('year', NOW()) AS year_start,\n  DATE_TRUNC('quarter', NOW()) AS quarter_start,\n  DATE_TRUNC('month', NOW()) AS month_start,\n  DATE_TRUNC('week', NOW()) AS week_start,\n  DATE_TRUNC('day', NOW()) AS day_start,\n  DATE_TRUNC('hour', NOW()) AS hour_start;", "explanation": "", "db": "ecommerce_db"}, {"id": 349, "section": "Topic 13 — Date/Time Advanced (25 Qs)", "question": "Generate a monthly calendar for 2025.", "sql": "SELECT m::DATE AS first_of_month,\n  (m + INTERVAL '1 month' - INTERVAL '1 day')::DATE AS last_of_month\nFROM GENERATE_SERIES('2025-01-01'::DATE, '2025-12-01'::DATE, '1 month') AS m;", "explanation": "", "db": "ecommerce_db"}, {"id": 350, "section": "Topic 13 — Date/Time Advanced (25 Qs)", "question": "Find orders per hour of the day.", "sql": "SELECT EXTRACT(HOUR FROM placed_at) AS hour, COUNT(*) AS orders\nFROM orders GROUP BY hour ORDER BY hour;", "explanation": "Useful for understanding peak hours.", "db": "ecommerce_db"}, {"id": 351, "section": "Topic 13 — Date/Time Advanced (25 Qs)", "question": "Calculate business days between two dates (approx).", "sql": "SELECT order_id,\n  (delivered_at::DATE - placed_at::DATE) -\n  2 * ((delivered_at::DATE - placed_at::DATE) / 7) AS approx_business_days\nFROM orders WHERE delivered_at IS NOT NULL;", "explanation": "Rough business days calculation excluding weekends.", "db": "ecommerce_db"}, {"id": 352, "section": "Topic 13 — Date/Time Advanced (25 Qs)", "question": "Time zones: Convert UTC to EST.", "sql": "SELECT placed_at,\n  placed_at AT TIME ZONE 'UTC' AT TIME ZONE 'America/New_York' AS est_time\nFROM orders LIMIT 5;", "explanation": "AT TIME ZONE converts between time zones.", "db": "ecommerce_db"}, {"id": 353, "section": "Topic 13 — Date/Time Advanced (25 Qs)", "question": "OVERLAPS: Find appointments that conflict.", "sql": "SELECT a1.appointment_id, a2.appointment_id\nFROM appointments a1\nJOIN appointments a2 ON a1.doctor_id = a2.doctor_id\n  AND a1.appointment_id < a2.appointment_id\n  AND (a1.scheduled_at, a1.scheduled_at + (a1.duration_min || ' minutes')::INTERVAL)\n      OVERLAPS\n      (a2.scheduled_at, a2.scheduled_at + (a2.duration_min || ' minutes')::INTERVAL);", "explanation": "OVERLAPS operator checks if two time ranges intersect.", "db": "hospital_db"}, {"id": 354, "section": "Topic 13 — Date/Time Advanced (25 Qs)", "question": "Find the start and end of the current ISO week.", "sql": "SELECT DATE_TRUNC('week', CURRENT_DATE) AS week_start,\n  DATE_TRUNC('week', CURRENT_DATE) + INTERVAL '6 days' AS week_end;", "explanation": "", "db": "ecommerce_db"}, {"id": 355, "section": "Topic 13 — Date/Time Advanced (25 Qs)", "question": "Calculate semester duration in weeks.", "sql": "SELECT name, start_date, end_date,\n  EXTRACT(DAY FROM (end_date - start_date)) / 7 AS weeks\nFROM semesters;", "explanation": "", "db": "university_db"}, {"id": 356, "section": "Topic 13 — Date/Time Advanced (25 Qs)", "question": "Generate hourly time slots for a day.", "sql": "SELECT slot::TIME AS time_slot\nFROM GENERATE_SERIES('2025-01-01 08:00'::TIMESTAMP, '2025-01-01 18:00'::TIMESTAMP, '1 hour') AS slot;", "explanation": "", "db": "ecommerce_db"}, {"id": 357, "section": "Topic 13 — Date/Time Advanced (25 Qs)", "question": "Year-over-year comparison of monthly revenue.", "sql": "WITH monthly AS (\n  SELECT EXTRACT(YEAR FROM placed_at) AS yr, EXTRACT(MONTH FROM placed_at) AS mo,\n    SUM(total_amount) AS revenue\n  FROM orders GROUP BY yr, mo\n)\nSELECT m1.mo AS month, m1.revenue AS this_year, m2.revenue AS last_year,\n  ROUND((m1.revenue - m2.revenue) / NULLIF(m2.revenue, 0) * 100, 1) AS yoy_pct\nFROM monthly m1 LEFT JOIN monthly m2 ON m1.mo = m2.mo AND m1.yr = m2.yr + 1\nWHERE m1.yr = 2025 ORDER BY m1.mo;", "explanation": "", "db": "ecommerce_db"}, {"id": 358, "section": "Topic 13 — Date/Time Advanced (25 Qs)", "question": "MAKE_INTERVAL: Build intervals programmatically.", "sql": "SELECT loan_id, tenure_months,\n  disbursed_at + MAKE_INTERVAL(months => tenure_months) AS expected_closure\nFROM loans;", "explanation": "MAKE_INTERVAL constructs an interval from named parts.", "db": "bank_db"}, {"id": 359, "section": "Topic 13 — Date/Time Advanced (25 Qs)", "question": "Find stories that expired within the last hour.", "sql": "SELECT * FROM stories\nWHERE expires_at BETWEEN NOW() - INTERVAL '1 hour' AND NOW();", "explanation": "", "db": "social_db"}, {"id": 360, "section": "Topic 13 — Date/Time Advanced (25 Qs)", "question": "Identify peak order day per month.", "sql": "WITH daily AS (\n  SELECT placed_at::DATE AS d, COUNT(*) AS cnt FROM orders GROUP BY d\n),\nranked AS (\n  SELECT d, cnt, DATE_TRUNC('month', d) AS mo,\n    ROW_NUMBER() OVER (PARTITION BY DATE_TRUNC('month', d) ORDER BY cnt DESC) AS rn\n  FROM daily\n)\nSELECT TO_CHAR(mo, 'YYYY-MM') AS month, d AS peak_day, cnt AS orders FROM ranked WHERE rn = 1;", "explanation": "", "db": "ecommerce_db"}, {"id": 361, "section": "Topic 13 — Date/Time Advanced (25 Qs)", "question": "Age buckets for patients.", "sql": "SELECT\n  COUNT(*) FILTER (WHERE EXTRACT(YEAR FROM AGE(dob)) < 18) AS under_18,\n  COUNT(*) FILTER (WHERE EXTRACT(YEAR FROM AGE(dob)) BETWEEN 18 AND 40) AS age_18_40,\n  COUNT(*) FILTER (WHERE EXTRACT(YEAR FROM AGE(dob)) BETWEEN 41 AND 65) AS age_41_65,\n  COUNT(*) FILTER (WHERE EXTRACT(YEAR FROM AGE(dob)) > 65) AS over_65\nFROM patients;", "explanation": "", "db": "hospital_db"}, {"id": 362, "section": "Topic 13 — Date/Time Advanced (25 Qs)", "question": "Find the average response time (first comment after post).", "sql": "WITH first_comment AS (\n  SELECT post_id, MIN(created_at) AS first_reply FROM comments GROUP BY post_id\n)\nSELECT AVG(fc.first_reply - p.created_at) AS avg_response_time\nFROM first_comment fc JOIN posts p ON fc.post_id = p.post_id;", "explanation": "", "db": "social_db"}, {"id": 363, "section": "Topic 14 — Numeric & Math Functions (20 Qs)", "question": "ROUND, CEIL, FLOOR, TRUNC on product prices.", "sql": "SELECT base_price,\n  ROUND(base_price, 1) AS rounded,\n  CEIL(base_price) AS ceiling,\n  FLOOR(base_price) AS floored,\n  TRUNC(base_price, 1) AS truncated\nFROM products LIMIT 5;", "explanation": "ROUND rounds to nearest, CEIL up, FLOOR down, TRUNC toward zero.", "db": "ecommerce_db"}, {"id": 364, "section": "Topic 14 — Numeric & Math Functions (20 Qs)", "question": "ABS: Absolute value of balance differences.", "sql": "SELECT account_id, balance,\n  ABS(balance - (SELECT AVG(balance) FROM accounts)) AS diff_from_avg\nFROM accounts;", "explanation": "", "db": "bank_db"}, {"id": 365, "section": "Topic 14 — Numeric & Math Functions (20 Qs)", "question": "MOD: Find even/odd order IDs.", "sql": "SELECT order_id,\n  CASE WHEN MOD(order_id, 2) = 0 THEN 'Even' ELSE 'Odd' END AS parity\nFROM orders;", "explanation": "MOD returns the remainder of division.", "db": "ecommerce_db"}, {"id": 366, "section": "Topic 14 — Numeric & Math Functions (20 Qs)", "question": "POWER and SQRT: Compound interest calculation.", "sql": "SELECT fd_id, principal, interest_rate, tenure_days,\n  ROUND(principal * POWER(1 + interest_rate/100, tenure_days/365.0), 2) AS maturity_value\nFROM fixed_deposits;", "explanation": "", "db": "bank_db"}, {"id": 367, "section": "Topic 14 — Numeric & Math Functions (20 Qs)", "question": "LOG and LN: Logarithmic values.", "sql": "SELECT base_price,\n  ROUND(LOG(base_price)::NUMERIC, 4) AS log10,\n  ROUND(LN(base_price)::NUMERIC, 4) AS natural_log\nFROM products WHERE base_price > 0 LIMIT 5;", "explanation": "", "db": "ecommerce_db"}, {"id": 368, "section": "Topic 14 — Numeric & Math Functions (20 Qs)", "question": "RANDOM: Select a random sample of 5 products.", "sql": "SELECT * FROM products ORDER BY RANDOM() LIMIT 5;", "explanation": "ORDER BY RANDOM() shuffles rows — use for sampling.", "db": "ecommerce_db"}, {"id": 369, "section": "Topic 14 — Numeric & Math Functions (20 Qs)", "question": "Generate random prices between 10 and 100.", "sql": "SELECT ROUND((RANDOM() * 90 + 10)::NUMERIC, 2) AS random_price\nFROM GENERATE_SERIES(1, 10);", "explanation": "", "db": "ecommerce_db"}, {"id": 370, "section": "Topic 14 — Numeric & Math Functions (20 Qs)", "question": "SIGN: Classify balance as positive/negative/zero.", "sql": "SELECT account_id, balance,\n  SIGN(balance) AS balance_sign\nFROM accounts;", "explanation": "SIGN returns -1, 0, or 1.", "db": "bank_db"}, {"id": 371, "section": "Topic 14 — Numeric & Math Functions (20 Qs)", "question": "DIV: Integer division.", "sql": "SELECT 17 / 5 AS int_div, 17.0 / 5 AS float_div, DIV(17, 5) AS div_func, MOD(17, 5) AS remainder;", "explanation": "DIV performs integer division.", "db": "ecommerce_db"}, {"id": 372, "section": "Topic 14 — Numeric & Math Functions (20 Qs)", "question": "WIDTH_BUCKET: Histogram of product prices.", "sql": "SELECT WIDTH_BUCKET(base_price, 0, 1000, 10) AS bucket,\n  COUNT(*) AS count,\n  MIN(base_price) AS min_price,\n  MAX(base_price) AS max_price\nFROM products GROUP BY bucket ORDER BY bucket;", "explanation": "WIDTH_BUCKET assigns values to histogram bins.", "db": "ecommerce_db"}, {"id": 373, "section": "Topic 14 — Numeric & Math Functions (20 Qs)", "question": "Calculate standard deviation and variance.", "sql": "SELECT\n  ROUND(STDDEV(base_price)::NUMERIC, 2) AS std_dev,\n  ROUND(VARIANCE(base_price)::NUMERIC, 2) AS variance,\n  ROUND(STDDEV_POP(base_price)::NUMERIC, 2) AS pop_stddev\nFROM products;", "explanation": "STDDEV is sample std dev, STDDEV_POP is population.", "db": "ecommerce_db"}, {"id": 374, "section": "Topic 14 — Numeric & Math Functions (20 Qs)", "question": "Calculate EMI for loans.", "sql": "SELECT loan_id, principal AS p, interest_rate AS r, tenure_months AS n,\n  ROUND(\n    principal * (interest_rate/1200) * POWER(1 + interest_rate/1200, tenure_months)\n    / (POWER(1 + interest_rate/1200, tenure_months) - 1)\n  , 2) AS calculated_emi\nFROM loans WHERE interest_rate > 0;", "explanation": "Standard EMI formula using POWER.", "db": "bank_db"}, {"id": 375, "section": "Topic 14 — Numeric & Math Functions (20 Qs)", "question": "Normalize values to 0-1 range.", "sql": "WITH stats AS (SELECT MIN(base_price) AS mn, MAX(base_price) AS mx FROM products)\nSELECT p.name, p.base_price,\n  ROUND((p.base_price - s.mn) / NULLIF(s.mx - s.mn, 0), 4) AS normalized\nFROM products p, stats s ORDER BY normalized;", "explanation": "Min-max normalization formula.", "db": "ecommerce_db"}, {"id": 376, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "Create a JSON object from columns.", "sql": "SELECT JSON_BUILD_OBJECT(\n  'id', user_id, 'name', username, 'email', email\n) AS user_json FROM users LIMIT 5;", "explanation": "JSON_BUILD_OBJECT creates key-value pairs.", "db": "ecommerce_db"}, {"id": 377, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "Create a JSON array of values.", "sql": "SELECT JSON_BUILD_ARRAY(1, 'hello', TRUE, NULL) AS arr;", "explanation": "", "db": "ecommerce_db"}, {"id": 378, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "Aggregate rows into a JSON array.", "sql": "SELECT JSON_AGG(JSON_BUILD_OBJECT('id', product_id, 'name', name, 'price', base_price)) AS products_json\nFROM products WHERE category_id = 1;", "explanation": "", "db": "ecommerce_db"}, {"id": 379, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "Cast text to JSONB and query it.", "sql": "SELECT '{\"name\": \"John\", \"age\": 30}'::JSONB ->> 'name' AS name;", "explanation": "->>' extracts as text, -> extracts as JSON.", "db": "ecommerce_db"}, {"id": 380, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "Access nested JSON fields.", "sql": "SELECT '{\"address\": {\"city\": \"NYC\", \"zip\": \"10001\"}}'::JSONB -> 'address' ->> 'city' AS city;", "explanation": "Chain -> for objects, ->> for final text value.", "db": "ecommerce_db"}, {"id": 381, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "JSONB_EACH: Iterate over JSON keys.", "sql": "SELECT key, value FROM JSONB_EACH('{\"a\": 1, \"b\": 2, \"c\": 3}'::JSONB);", "explanation": "JSONB_EACH returns key-value pairs as rows.", "db": "ecommerce_db"}, {"id": 382, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "JSONB_ARRAY_ELEMENTS: Expand a JSON array to rows.", "sql": "SELECT JSONB_ARRAY_ELEMENTS('[\"red\", \"blue\", \"green\"]'::JSONB) AS color;", "explanation": "", "db": "ecommerce_db"}, {"id": 383, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "Check if a JSONB object contains a key.", "sql": "SELECT '{\"name\": \"test\", \"active\": true}'::JSONB ? 'name' AS has_name;", "explanation": "? operator checks key existence.", "db": "ecommerce_db"}, {"id": 384, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "JSONB containment: Check if one JSON contains another.", "sql": "SELECT '{\"a\": 1, \"b\": 2, \"c\": 3}'::JSONB @> '{\"a\": 1, \"b\": 2}'::JSONB AS contains;", "explanation": "@> is the containment operator.", "db": "ecommerce_db"}, {"id": 385, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "JSONB_SET: Update a value in a JSON object.", "sql": "SELECT JSONB_SET(\n  '{\"name\": \"John\", \"age\": 30}'::JSONB,\n  '{age}', '31'::JSONB\n) AS updated;", "explanation": "JSONB_SET modifies a value at a specified path.", "db": "ecommerce_db"}, {"id": 386, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "Remove a key from JSONB.", "sql": "SELECT '{\"a\": 1, \"b\": 2, \"c\": 3}'::JSONB - 'b' AS without_b;", "explanation": "The - operator removes a key from JSONB.", "db": "ecommerce_db"}, {"id": 387, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "JSONB_PRETTY: Format JSON for display.", "sql": "SELECT JSONB_PRETTY(JSON_BUILD_OBJECT('id', 1, 'items', JSON_BUILD_ARRAY('a','b'))::JSONB) AS pretty;", "explanation": "", "db": "ecommerce_db"}, {"id": 388, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "Store and query JSONB metadata column.", "sql": "CREATE TABLE IF NOT EXISTS product_meta (\n  product_id INT PRIMARY KEY,\n  metadata JSONB DEFAULT '{}'\n);\n\n-- Insert\nINSERT INTO product_meta VALUES (1, '{\"color\": \"red\", \"weight\": 2.5, \"tags\": [\"sale\", \"new\"]}');\n\n-- Query by nested value\nSELECT * FROM product_meta WHERE metadata ->> 'color' = 'red';\n\n-- Query array contains\nSELECT * FROM product_meta WHERE metadata -> 'tags' ? 'sale';", "explanation": "JSONB columns enable schema-flexible storage.", "db": "ecommerce_db"}, {"id": 389, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "JSONB_OBJECT_KEYS: List all keys in a JSON object.", "sql": "SELECT DISTINCT JSONB_OBJECT_KEYS('{\"a\": 1, \"b\": 2, \"c\": 3}'::JSONB) AS key;", "explanation": "", "db": "ecommerce_db"}, {"id": 390, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "Aggregate orders as nested JSON per user.", "sql": "SELECT u.username,\n  JSON_AGG(JSON_BUILD_OBJECT(\n    'order_id', o.order_id,\n    'amount', o.total_amount,\n    'status', o.status,\n    'items', (SELECT JSON_AGG(JSON_BUILD_OBJECT('variant', oi.variant_id, 'qty', oi.quantity))\n              FROM order_items oi WHERE oi.order_id = o.order_id)\n  )) AS orders\nFROM users u JOIN orders o ON u.user_id = o.user_id\nGROUP BY u.username LIMIT 3;", "explanation": "Deeply nested JSON with correlated subquery.", "db": "ecommerce_db"}, {"id": 391, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "JSONB_STRIP_NULLS: Remove null-valued keys.", "sql": "SELECT JSONB_STRIP_NULLS('{\"a\": 1, \"b\": null, \"c\": 3}'::JSONB) AS cleaned;", "explanation": "", "db": "ecommerce_db"}, {"id": 392, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "TO_JSONB: Convert a row to JSONB.", "sql": "SELECT TO_JSONB(u.*) AS user_jsonb FROM users u LIMIT 3;", "explanation": "TO_JSONB converts any SQL value to JSONB.", "db": "ecommerce_db"}, {"id": 393, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "JSONB path queries (SQL/JSON @ operator).", "sql": "SELECT '{\"items\": [{\"name\": \"A\", \"price\": 10}, {\"name\": \"B\", \"price\": 20}]}'::JSONB\n  @? '$.items[*] ? (@.price > 15)' AS has_expensive;", "explanation": "@? checks if a JSON path returns any items (PostgreSQL 12+).", "db": "ecommerce_db"}, {"id": 394, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "GIN index on JSONB for fast queries.", "sql": "-- Create GIN index for fast JSONB queries\nCREATE INDEX idx_product_meta_gin ON product_meta USING GIN (metadata);\n\n-- This query now uses the GIN index\nSELECT * FROM product_meta WHERE metadata @> '{\"color\": \"red\"}';", "explanation": "GIN indexes support @>, ?, and other JSONB operators.", "db": "ecommerce_db"}, {"id": 395, "section": "Topic 15 — JSON & JSONB Operations (25 Qs)", "question": "Combine JSONB with window functions.", "sql": "SELECT user_id,\n  JSON_BUILD_OBJECT(\n    'order', order_id,\n    'amount', total_amount,\n    'rank', RANK() OVER (PARTITION BY user_id ORDER BY total_amount DESC)\n  ) AS order_info\nFROM orders LIMIT 20;", "explanation": "Mix JSONB builders with window functions for rich output.", "db": "ecommerce_db"}, {"id": 396, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "Create a simple view of active products.", "sql": "CREATE VIEW active_products AS\nSELECT product_id, name, base_price, category_id\nFROM products WHERE is_active = TRUE;", "explanation": "Views are virtual tables — query is executed each time the view is referenced.", "db": "ecommerce_db"}, {"id": 397, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "Query the view like a regular table.", "sql": "SELECT * FROM active_products WHERE base_price > 100 ORDER BY base_price DESC;", "explanation": "", "db": "ecommerce_db"}, {"id": 398, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "Create a view joining orders with user info.", "sql": "CREATE VIEW order_details AS\nSELECT o.order_id, o.placed_at, o.total_amount, o.status,\n  u.username, u.email\nFROM orders o JOIN users u ON o.user_id = u.user_id;", "explanation": "Views simplify complex joins for repeated use.", "db": "ecommerce_db"}, {"id": 399, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "Create a view with aggregation: category stats.", "sql": "CREATE VIEW category_stats AS\nSELECT c.name AS category, COUNT(p.product_id) AS product_count,\n  ROUND(AVG(p.base_price), 2) AS avg_price, SUM(p.base_price) AS total_value\nFROM categories c LEFT JOIN products p ON c.category_id = p.category_id\nGROUP BY c.name;", "explanation": "", "db": "ecommerce_db"}, {"id": 400, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "Create OR REPLACE to update a view definition.", "sql": "CREATE OR REPLACE VIEW active_products AS\nSELECT product_id, name, base_price, category_id, sku\nFROM products WHERE is_active = TRUE;", "explanation": "OR REPLACE updates without DROP — preserves grants/dependencies.", "db": "ecommerce_db"}, {"id": 401, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "Drop a view.", "sql": "DROP VIEW IF EXISTS active_products;", "explanation": "IF EXISTS prevents errors if the view doesn't exist.", "db": "ecommerce_db"}, {"id": 402, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "Create a view with WITH CHECK OPTION.", "sql": "CREATE VIEW premium_products AS\nSELECT * FROM products WHERE base_price > 500\nWITH CHECK OPTION;", "explanation": "WITH CHECK OPTION prevents INSERT/UPDATE that would make the row disappear from the view.", "db": "ecommerce_db"}, {"id": 403, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "Create a materialized view for expensive reports.", "sql": "CREATE MATERIALIZED VIEW monthly_revenue AS\nSELECT DATE_TRUNC('month', placed_at) AS month,\n  COUNT(*) AS order_count, SUM(total_amount) AS revenue\nFROM orders GROUP BY month ORDER BY month;", "explanation": "Materialized views store results physically — much faster for complex queries.", "db": "ecommerce_db"}, {"id": 404, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "Refresh a materialized view.", "sql": "REFRESH MATERIALIZED VIEW monthly_revenue;", "explanation": "Must be refreshed manually to get updated data.", "db": "ecommerce_db"}, {"id": 405, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "Refresh materialized view concurrently (no lock).", "sql": "REFRESH MATERIALIZED VIEW CONCURRENTLY monthly_revenue;", "explanation": "CONCURRENTLY allows reads during refresh — requires a unique index.", "db": "ecommerce_db"}, {"id": 406, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "Create an index on a materialized view.", "sql": "CREATE UNIQUE INDEX idx_monthly_revenue_month ON monthly_revenue (month);", "explanation": "Indexes on materialized views improve query performance and enable CONCURRENTLY.", "db": "ecommerce_db"}, {"id": 407, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "Create a view for patient dashboard.", "sql": "CREATE VIEW patient_dashboard AS\nSELECT p.patient_id, p.first_name || ' ' || p.last_name AS name,\n  COUNT(DISTINCT a.appointment_id) AS appointments,\n  COUNT(DISTINCT mr.record_id) AS records,\n  COUNT(DISTINCT pr.prescription_id) AS prescriptions\nFROM patients p\nLEFT JOIN appointments a ON p.patient_id = a.patient_id\nLEFT JOIN medical_records mr ON p.patient_id = mr.patient_id\nLEFT JOIN prescriptions pr ON p.patient_id = pr.patient_id\nGROUP BY p.patient_id, p.first_name, p.last_name;", "explanation": "", "db": "hospital_db"}, {"id": 408, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "Create a materialized view for student transcripts.", "sql": "CREATE MATERIALIZED VIEW student_transcripts AS\nSELECT s.student_id, s.first_name, s.last_name, s.roll_no,\n  c.code AS course_code, c.name AS course_name, c.credits,\n  e.final_grade, e.grade_points,\n  sem.name AS semester\nFROM enrollments e\nJOIN sections sec ON e.section_id = sec.section_id\nJOIN courses c ON sec.course_id = c.course_id\nJOIN students s ON e.student_id = s.student_id\nJOIN semesters sem ON sec.semester_id = sem.semester_id\nWHERE e.final_grade IS NOT NULL;", "explanation": "", "db": "university_db"}, {"id": 409, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "Create a view for account summary.", "sql": "CREATE VIEW account_summary AS\nSELECT a.account_id, a.account_no, at.name AS account_type,\n  c.first_name || ' ' || c.last_name AS customer,\n  a.balance, b.name AS branch,\n  (SELECT COUNT(*) FROM transactions t WHERE t.account_id = a.account_id) AS txn_count\nFROM accounts a\nJOIN customers c ON a.customer_id = c.customer_id\nJOIN branches b ON a.branch_id = b.branch_id\nJOIN account_types at ON a.type_id = at.type_id;", "explanation": "", "db": "bank_db"}, {"id": 410, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "Create a view for user feed.", "sql": "CREATE VIEW user_feed AS\nSELECT p.post_id, p.content, p.type, p.created_at,\n  u.username, u.display_name, u.avatar_url,\n  (SELECT COUNT(*) FROM likes l WHERE l.post_id = p.post_id) AS like_count,\n  (SELECT COUNT(*) FROM comments c WHERE c.post_id = p.post_id) AS comment_count\nFROM posts p JOIN users u ON p.user_id = u.user_id\nWHERE p.is_archived = FALSE AND p.visibility = 'public'\nORDER BY p.created_at DESC;", "explanation": "", "db": "social_db"}, {"id": 411, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "List all views in the current database.", "sql": "SELECT table_name, view_definition\nFROM information_schema.views\nWHERE table_schema = 'public'\nORDER BY table_name;", "explanation": "information_schema.views lists all view definitions.", "db": "ecommerce_db"}, {"id": 412, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "List all materialized views.", "sql": "SELECT matviewname, definition\nFROM pg_matviews\nWHERE schemaname = 'public';", "explanation": "pg_matviews is specific to PostgreSQL.", "db": "ecommerce_db"}, {"id": 413, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "Create a recursive view for category hierarchy.", "sql": "CREATE RECURSIVE VIEW category_tree (id, name, path, depth) AS\n  SELECT category_id, name, name::TEXT, 0 FROM categories WHERE parent_id IS NULL\n  UNION ALL\n  SELECT c.category_id, c.name, ct.path || ' > ' || c.name, ct.depth + 1\n  FROM categories c JOIN category_tree ct ON c.parent_id = ct.id;\n\nSELECT * FROM category_tree ORDER BY path;", "explanation": "CREATE RECURSIVE VIEW is syntactic sugar for WITH RECURSIVE.", "db": "ecommerce_db"}, {"id": 414, "section": "Topic 16 — Views & Materialized Views (25 Qs)", "question": "Updatable view: INSERT through a view.", "sql": "CREATE VIEW active_users AS\nSELECT user_id, username, email, role FROM users WHERE is_active = TRUE;\n\n-- This INSERT goes through the view to the base table\nINSERT INTO active_users (username, email, role)\nVALUES ('new_user', 'new@example.com', 'customer');", "explanation": "Simple views on single tables are automatically updatable in PostgreSQL.", "db": "ecommerce_db"}, {"id": 415, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "Create a B-tree index on a frequently queried column.", "sql": "CREATE INDEX idx_orders_user_id ON orders (user_id);", "explanation": "B-tree is the default index type — good for equality and range queries.", "db": "ecommerce_db"}, {"id": 416, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "Create a unique index.", "sql": "CREATE UNIQUE INDEX idx_users_email ON users (email);", "explanation": "Unique indexes enforce uniqueness and speed up lookups.", "db": "ecommerce_db"}, {"id": 417, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "Create a composite (multi-column) index.", "sql": "CREATE INDEX idx_orders_user_status ON orders (user_id, status);", "explanation": "Column order matters — put the most selective column first.", "db": "ecommerce_db"}, {"id": 418, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "Create a partial (conditional) index.", "sql": "CREATE INDEX idx_orders_pending ON orders (user_id, placed_at)\nWHERE status = 'pending';", "explanation": "Partial indexes are smaller and only index rows matching the WHERE condition.", "db": "ecommerce_db"}, {"id": 419, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "Create an expression index (functional index).", "sql": "CREATE INDEX idx_users_lower_email ON users (LOWER(email));", "explanation": "Indexes the result of an expression — useful for case-insensitive searches.", "db": "ecommerce_db"}, {"id": 420, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "Create a GIN index for full-text search.", "sql": "CREATE INDEX idx_products_name_gin ON products USING GIN (to_tsvector('english', name));", "explanation": "GIN (Generalized Inverted Index) is optimized for full-text search and arrays.", "db": "ecommerce_db"}, {"id": 421, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "Create a GiST index for range types.", "sql": "CREATE INDEX idx_appointments_schedule ON appointments USING GIST (\n  tsrange(scheduled_at, scheduled_at + (duration_min || ' minutes')::INTERVAL)\n);", "explanation": "GiST supports range queries, geometric types, and nearest-neighbor.", "db": "hospital_db"}, {"id": 422, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "Create a BRIN index for time-series data.", "sql": "CREATE INDEX idx_page_views_time ON page_views USING BRIN (viewed_at);", "explanation": "BRIN is tiny and effective for naturally ordered columns (e.g., timestamp on append-only tables).", "db": "ecommerce_db"}, {"id": 423, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "EXPLAIN: View the query execution plan.", "sql": "EXPLAIN SELECT * FROM orders WHERE user_id = 5 AND status = 'pending';", "explanation": "EXPLAIN shows the planner's chosen strategy without executing.", "db": "ecommerce_db"}, {"id": 424, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "EXPLAIN ANALYZE: View the actual execution stats.", "sql": "EXPLAIN ANALYZE SELECT * FROM orders WHERE user_id = 5 AND status = 'pending';", "explanation": "ANALYZE actually runs the query and shows real timing/row counts.", "db": "ecommerce_db"}, {"id": 425, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "EXPLAIN with options for maximum detail.", "sql": "EXPLAIN (ANALYZE, BUFFERS, FORMAT TEXT)\nSELECT o.order_id, u.username FROM orders o JOIN users u ON o.user_id = u.user_id WHERE o.total_amount > 1000;", "explanation": "BUFFERS shows cache hit/miss info — crucial for performance tuning.", "db": "ecommerce_db"}, {"id": 426, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "Identify unused indexes.", "sql": "SELECT schemaname, tablename, indexname, idx_scan,\n  pg_size_pretty(pg_relation_size(indexrelid)) AS index_size\nFROM pg_stat_user_indexes\nWHERE idx_scan = 0\nORDER BY pg_relation_size(indexrelid) DESC;", "explanation": "Unused indexes waste disk and slow writes — candidates for removal.", "db": "ecommerce_db"}, {"id": 427, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "Find the size of all indexes on a table.", "sql": "SELECT indexname, pg_size_pretty(pg_relation_size(indexrelid)) AS size\nFROM pg_stat_user_indexes\nWHERE relname = 'orders'\nORDER BY pg_relation_size(indexrelid) DESC;", "explanation": "", "db": "ecommerce_db"}, {"id": 428, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "Drop an index.", "sql": "DROP INDEX IF EXISTS idx_orders_pending;", "explanation": "Always use IF EXISTS for safety in scripts.", "db": "ecommerce_db"}, {"id": 429, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "REINDEX: Rebuild a corrupted or bloated index.", "sql": "REINDEX INDEX idx_orders_user_id;", "explanation": "REINDEX rebuilds the index from scratch.", "db": "ecommerce_db"}, {"id": 430, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "Create an index CONCURRENTLY (no lock).", "sql": "CREATE INDEX CONCURRENTLY idx_products_category ON products (category_id);", "explanation": "CONCURRENTLY avoids locking the table during index creation — essential for production.", "db": "ecommerce_db"}, {"id": 431, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "Covering index with INCLUDE.", "sql": "CREATE INDEX idx_orders_covering ON orders (user_id)\nINCLUDE (total_amount, status);", "explanation": "INCLUDE adds non-key columns — enables index-only scans.", "db": "ecommerce_db"}, {"id": 432, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "Check table and index sizes.", "sql": "SELECT\n  pg_size_pretty(pg_total_relation_size('orders')) AS total_size,\n  pg_size_pretty(pg_relation_size('orders')) AS table_size,\n  pg_size_pretty(pg_indexes_size('orders')) AS indexes_size;", "explanation": "", "db": "ecommerce_db"}, {"id": 433, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "Find slow queries using pg_stat_statements.", "sql": "SELECT query, calls, mean_exec_time, total_exec_time\nFROM pg_stat_statements\nORDER BY mean_exec_time DESC LIMIT 10;", "explanation": "pg_stat_statements tracks query statistics — enable the extension first.", "db": "ecommerce_db"}, {"id": 434, "section": "Topic 17 — Indexes & Performance (25 Qs)", "question": "VACUUM and ANALYZE a table.", "sql": "VACUUM ANALYZE orders;", "explanation": "VACUUM reclaims dead tuples; ANALYZE updates optimizer statistics.", "db": "ecommerce_db"}, {"id": 435, "section": "Topic 18 — Stored Procedures & Functions (30 Qs)", "question": "Create a simple SQL function.", "sql": "CREATE OR REPLACE FUNCTION get_user_email(uid INT)\nRETURNS TEXT AS $$\n  SELECT email FROM users WHERE user_id = uid;\n$$ LANGUAGE SQL;", "explanation": "SQL functions are the simplest — just a query.", "db": "ecommerce_db"}, {"id": 436, "section": "Topic 18 — Stored Procedures & Functions (30 Qs)", "question": "Call the function.", "sql": "SELECT get_user_email(1);", "explanation": "", "db": "ecommerce_db"}, {"id": 437, "section": "Topic 18 — Stored Procedures & Functions (30 Qs)", "question": "Create a function returning a table.", "sql": "CREATE OR REPLACE FUNCTION get_user_orders(uid INT)\nRETURNS TABLE(order_id INT, amount NUMERIC, status VARCHAR) AS $$\n  SELECT order_id, total_amount, status FROM orders WHERE user_id = uid;\n$$ LANGUAGE SQL;", "explanation": "RETURNS TABLE defines the output structure.", "db": "ecommerce_db"}, {"id": 438, "section": "Topic 18 — Stored Procedures & Functions (30 Qs)", "question": "Create a PL/pgSQL function with variables and logic.", "sql": "CREATE OR REPLACE FUNCTION calculate_discount(order_total NUMERIC)\nRETURNS NUMERIC AS $$\nDECLARE\n  discount_pct NUMERIC;\nBEGIN\n  IF order_total >= 5000 THEN discount_pct := 15;\n  ELSIF order_total >= 2000 THEN discount_pct := 10;\n  ELSIF order_total >= 500 THEN discount_pct := 5;\n  ELSE discount_pct := 0;\n  END IF;\n  RETURN ROUND(order_total * discount_pct / 100, 2);\nEND;\n$$ LANGUAGE plpgsql;", "explanation": "PL/pgSQL supports variables, IF/ELSE, loops, and exception handling.", "db": "ecommerce_db"}, {"id": 439, "section": "Topic 18 — Stored Procedures & Functions (30 Qs)", "question": "Create a function with exception handling.", "sql": "CREATE OR REPLACE FUNCTION safe_divide(a NUMERIC, b NUMERIC)\nRETURNS NUMERIC AS $$\nBEGIN\n  RETURN a / b;\nEXCEPTION\n  WHEN division_by_zero THEN RETURN NULL;\n  WHEN OTHERS THEN RAISE NOTICE 'Error: %', SQLERRM; RETURN NULL;\nEND;\n$$ LANGUAGE plpgsql;", "explanation": "EXCEPTION block catches runtime errors.", "db": "ecommerce_db"}, {"id": 440, "section": "Topic 18 — Stored Procedures & Functions (30 Qs)", "question": "Create a procedure (no return value) for placing an order.", "sql": "CREATE OR REPLACE PROCEDURE place_order(\n  p_user_id INT, p_address_id INT, p_total NUMERIC\n) AS $$\nDECLARE\n  v_order_id INT;\nBEGIN\n  INSERT INTO orders (user_id, address_id, total_amount, status)\n  VALUES (p_user_id, p_address_id, p_total, 'pending')\n  RETURNING order_id INTO v_order_id;\n  RAISE NOTICE 'Order % created', v_order_id;\nEND;\n$$ LANGUAGE plpgsql;", "explanation": "PROCEDURE (PostgreSQL 11+) — use CALL to execute.", "db": "ecommerce_db"}, {"id": 441, "section": "Topic 18 — Stored Procedures & Functions (30 Qs)", "question": "Call a procedure.", "sql": "CALL place_order(1, 2, 299.99);", "explanation": "", "db": "ecommerce_db"}, {"id": 442, "section": "Topic 18 — Stored Procedures & Functions (30 Qs)", "question": "Function with a loop.", "sql": "CREATE OR REPLACE FUNCTION factorial(n INT)\nRETURNS BIGINT AS $$\nDECLARE\n  result BIGINT := 1;\nBEGIN\n  FOR i IN 1..n LOOP\n    result := result * i;\n  END LOOP;\n  RETURN result;\nEND;\n$$ LANGUAGE plpgsql;", "explanation": "", "db": "ecommerce_db"}, {"id": 443, "section": "Topic 18 — Stored Procedures & Functions (30 Qs)", "question": "Function with SETOF for returning multiple rows.", "sql": "CREATE OR REPLACE FUNCTION top_products(n INT DEFAULT 10)\nRETURNS SETOF products AS $$\n  SELECT * FROM products ORDER BY base_price DESC LIMIT n;\n$$ LANGUAGE SQL;", "explanation": "SETOF returns zero or more rows of the specified type.", "db": "ecommerce_db"}, {"id": 444, "section": "Topic 18 — Stored Procedures & Functions (30 Qs)", "question": "Function with OUT parameters.", "sql": "CREATE OR REPLACE FUNCTION order_stats(\n  OUT total_orders INT, OUT total_revenue NUMERIC, OUT avg_order NUMERIC\n) AS $$\n  SELECT COUNT(*), SUM(total_amount), ROUND(AVG(total_amount), 2)\n  FROM orders;\n$$ LANGUAGE SQL;", "explanation": "OUT parameters define multiple return values.", "db": "ecommerce_db"}, {"id": 445, "section": "Topic 18 — Stored Procedures & Functions (30 Qs)", "question": "Create a function to calculate patient age.", "sql": "CREATE OR REPLACE FUNCTION patient_age(pid INT)\nRETURNS INT AS $$\n  SELECT EXTRACT(YEAR FROM AGE(dob))::INT FROM patients WHERE patient_id = pid;\n$$ LANGUAGE SQL;", "explanation": "", "db": "hospital_db"}, {"id": 446, "section": "Topic 18 — Stored Procedures & Functions (30 Qs)", "question": "Function with PERFORM (discard result).", "sql": "CREATE OR REPLACE FUNCTION log_page_view(uid INT, pid INT)\nRETURNS VOID AS $$\nBEGIN\n  INSERT INTO page_views (user_id, product_id, viewed_at)\n  VALUES (uid, pid, NOW());\n  -- PERFORM used when you don't need the result\n  PERFORM pg_notify('page_view', uid::TEXT || ':' || pid::TEXT);\nEND;\n$$ LANGUAGE plpgsql;", "explanation": "PERFORM executes a query but discards the result — use for side effects.", "db": "ecommerce_db"}, {"id": 447, "section": "Topic 18 — Stored Procedures & Functions (30 Qs)", "question": "Function with dynamic SQL using EXECUTE.", "sql": "CREATE OR REPLACE FUNCTION count_table(tbl TEXT)\nRETURNS BIGINT AS $$\nDECLARE\n  cnt BIGINT;\nBEGIN\n  EXECUTE format('SELECT COUNT(*) FROM %I', tbl) INTO cnt;\n  RETURN cnt;\nEND;\n$$ LANGUAGE plpgsql;", "explanation": "EXECUTE runs dynamic SQL. format(%I) safely quotes identifiers.", "db": "ecommerce_db"}, {"id": 448, "section": "Topic 18 — Stored Procedures & Functions (30 Qs)", "question": "Create a function with IMMUTABLE volatility.", "sql": "CREATE OR REPLACE FUNCTION full_name(first TEXT, last TEXT)\nRETURNS TEXT AS $$\n  SELECT first || ' ' || last;\n$$ LANGUAGE SQL IMMUTABLE;", "explanation": "IMMUTABLE: always returns same result for same args. Enables indexing.", "db": "ecommerce_db"}, {"id": 449, "section": "Topic 18 — Stored Procedures & Functions (30 Qs)", "question": "Create a function to transfer funds.", "sql": "CREATE OR REPLACE PROCEDURE transfer_funds(\n  p_from INT, p_to INT, p_amount NUMERIC\n) AS $$\nBEGIN\n  IF p_amount <= 0 THEN RAISE EXCEPTION 'Amount must be positive'; END IF;\n  UPDATE accounts SET balance = balance - p_amount WHERE account_id = p_from;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Source account not found'; END IF;\n  UPDATE accounts SET balance = balance + p_amount WHERE account_id = p_to;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Destination account not found'; END IF;\n  INSERT INTO transfers (from_account, to_account, amount, status)\n  VALUES (p_from, p_to, p_amount, 'completed');\nEND;\n$$ LANGUAGE plpgsql;", "explanation": "", "db": "bank_db"}, {"id": 450, "section": "Topic 18 — Stored Procedures & Functions (30 Qs)", "question": "Drop a function.", "sql": "DROP FUNCTION IF EXISTS get_user_email(INT);", "explanation": "Specify parameter types for overloaded functions.", "db": "ecommerce_db"}, {"id": 451, "section": "Topic 18 — Stored Procedures & Functions (30 Qs)", "question": "List all user-defined functions.", "sql": "SELECT routine_name, routine_type, data_type\nFROM information_schema.routines\nWHERE routine_schema = 'public'\nORDER BY routine_name;", "explanation": "", "db": "ecommerce_db"}, {"id": 452, "section": "Topic 18 — Stored Procedures & Functions (30 Qs)", "question": "Function returning JSON.", "sql": "CREATE OR REPLACE FUNCTION user_profile_json(uid INT)\nRETURNS JSONB AS $$\n  SELECT JSONB_BUILD_OBJECT(\n    'user', TO_JSONB(u.*),\n    'orders', (SELECT COALESCE(JSON_AGG(TO_JSONB(o.*)), '[]'::JSON)\n               FROM orders o WHERE o.user_id = uid)\n  ) FROM users u WHERE u.user_id = uid;\n$$ LANGUAGE SQL;", "explanation": "Functions can return complex JSON structures for API use.", "db": "ecommerce_db"}, {"id": 453, "section": "Topic 19 — Triggers (20 Qs)", "question": "Create a trigger function to auto-update `updated_at`.", "sql": "CREATE OR REPLACE FUNCTION update_timestamp()\nRETURNS TRIGGER AS $$\nBEGIN\n  NEW.updated_at := NOW();\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;", "explanation": "Trigger functions return TRIGGER type and use NEW/OLD record references.", "db": "ecommerce_db"}, {"id": 454, "section": "Topic 19 — Triggers (20 Qs)", "question": "Attach the trigger to the users table.", "sql": "CREATE TRIGGER trg_users_updated\nBEFORE UPDATE ON users\nFOR EACH ROW\nEXECUTE FUNCTION update_timestamp();", "explanation": "BEFORE UPDATE: trigger fires before the update is applied.", "db": "ecommerce_db"}, {"id": 455, "section": "Topic 19 — Triggers (20 Qs)", "question": "Create an audit log trigger.", "sql": "CREATE TABLE audit_log (\n  id SERIAL PRIMARY KEY, table_name TEXT, action TEXT,\n  old_data JSONB, new_data JSONB, changed_at TIMESTAMP DEFAULT NOW(), changed_by TEXT\n);\n\nCREATE OR REPLACE FUNCTION audit_trigger()\nRETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO audit_log (table_name, action, old_data, new_data)\n  VALUES (\n    TG_TABLE_NAME, TG_OP,\n    CASE WHEN TG_OP IN ('UPDATE','DELETE') THEN TO_JSONB(OLD) END,\n    CASE WHEN TG_OP IN ('INSERT','UPDATE') THEN TO_JSONB(NEW) END\n  );\n  RETURN COALESCE(NEW, OLD);\nEND;\n$$ LANGUAGE plpgsql;", "explanation": "TG_TABLE_NAME and TG_OP are special trigger variables.", "db": "ecommerce_db"}, {"id": 456, "section": "Topic 19 — Triggers (20 Qs)", "question": "Apply audit trigger to multiple tables.", "sql": "CREATE TRIGGER trg_audit_orders AFTER INSERT OR UPDATE OR DELETE ON orders\nFOR EACH ROW EXECUTE FUNCTION audit_trigger();\n\nCREATE TRIGGER trg_audit_products AFTER INSERT OR UPDATE OR DELETE ON products\nFOR EACH ROW EXECUTE FUNCTION audit_trigger();", "explanation": "Same trigger function can be reused across tables.", "db": "ecommerce_db"}, {"id": 457, "section": "Topic 19 — Triggers (20 Qs)", "question": "Trigger to maintain stock quantity on order.", "sql": "CREATE OR REPLACE FUNCTION update_stock_on_order()\nRETURNS TRIGGER AS $$\nBEGIN\n  UPDATE product_variants\n  SET stock_qty = stock_qty - NEW.quantity\n  WHERE variant_id = NEW.variant_id;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Variant % not found', NEW.variant_id; END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_order_item_stock\nAFTER INSERT ON order_items\nFOR EACH ROW EXECUTE FUNCTION update_stock_on_order();", "explanation": "", "db": "ecommerce_db"}, {"id": 458, "section": "Topic 19 — Triggers (20 Qs)", "question": "BEFORE INSERT trigger with validation.", "sql": "CREATE OR REPLACE FUNCTION validate_review()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF NEW.rating < 1 OR NEW.rating > 5 THEN\n    RAISE EXCEPTION 'Rating must be between 1 and 5, got %', NEW.rating;\n  END IF;\n  IF LENGTH(TRIM(COALESCE(NEW.body, ''))) < 10 THEN\n    RAISE EXCEPTION 'Review body must be at least 10 characters';\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_validate_review\nBEFORE INSERT OR UPDATE ON reviews\nFOR EACH ROW EXECUTE FUNCTION validate_review();", "explanation": "", "db": "ecommerce_db"}, {"id": 459, "section": "Topic 19 — Triggers (20 Qs)", "question": "Trigger to update hashtag post_count.", "sql": "CREATE OR REPLACE FUNCTION update_hashtag_count()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF TG_OP = 'INSERT' THEN\n    UPDATE hashtags SET post_count = post_count + 1 WHERE hashtag_id = NEW.hashtag_id;\n  ELSIF TG_OP = 'DELETE' THEN\n    UPDATE hashtags SET post_count = post_count - 1 WHERE hashtag_id = OLD.hashtag_id;\n  END IF;\n  RETURN COALESCE(NEW, OLD);\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_hashtag_count\nAFTER INSERT OR DELETE ON post_hashtags\nFOR EACH ROW EXECUTE FUNCTION update_hashtag_count();", "explanation": "", "db": "social_db"}, {"id": 460, "section": "Topic 19 — Triggers (20 Qs)", "question": "Statement-level trigger (not per row).", "sql": "CREATE OR REPLACE FUNCTION log_bulk_update()\nRETURNS TRIGGER AS $$\nBEGIN\n  RAISE NOTICE 'Bulk % on % at %', TG_OP, TG_TABLE_NAME, NOW();\n  RETURN NULL;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_bulk_orders\nAFTER UPDATE ON orders\nFOR EACH STATEMENT EXECUTE FUNCTION log_bulk_update();", "explanation": "FOR EACH STATEMENT fires once per SQL statement, not per row.", "db": "ecommerce_db"}, {"id": 461, "section": "Topic 19 — Triggers (20 Qs)", "question": "Conditional trigger with WHEN clause.", "sql": "CREATE TRIGGER trg_order_status_change\nAFTER UPDATE OF status ON orders\nFOR EACH ROW\nWHEN (OLD.status IS DISTINCT FROM NEW.status)\nEXECUTE FUNCTION audit_trigger();", "explanation": "WHEN clause filters which rows trigger the function.", "db": "ecommerce_db"}, {"id": 462, "section": "Topic 19 — Triggers (20 Qs)", "question": "INSTEAD OF trigger on a view.", "sql": "CREATE OR REPLACE FUNCTION insert_into_active_products()\nRETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO products (name, base_price, category_id, is_active)\n  VALUES (NEW.name, NEW.base_price, NEW.category_id, TRUE);\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_insert_active_product\nINSTEAD OF INSERT ON active_products\nFOR EACH ROW EXECUTE FUNCTION insert_into_active_products();", "explanation": "INSTEAD OF triggers make non-updatable views writable.", "db": "ecommerce_db"}, {"id": 463, "section": "Topic 19 — Triggers (20 Qs)", "question": "Drop a trigger.", "sql": "DROP TRIGGER IF EXISTS trg_users_updated ON users;", "explanation": "Must specify the table when dropping a trigger.", "db": "ecommerce_db"}, {"id": 464, "section": "Topic 19 — Triggers (20 Qs)", "question": "Disable and enable triggers.", "sql": "ALTER TABLE orders DISABLE TRIGGER trg_audit_orders;\n-- Perform bulk operations without trigger overhead\nALTER TABLE orders ENABLE TRIGGER trg_audit_orders;", "explanation": "Disable triggers temporarily for bulk loads.", "db": "ecommerce_db"}, {"id": 465, "section": "Topic 19 — Triggers (20 Qs)", "question": "List all triggers on a table.", "sql": "SELECT trigger_name, event_manipulation, action_timing, action_orientation\nFROM information_schema.triggers\nWHERE event_object_table = 'orders'\nORDER BY trigger_name;", "explanation": "", "db": "ecommerce_db"}, {"id": 466, "section": "Topic 19 — Triggers (20 Qs)", "question": "Trigger to auto-create notification on new comment.", "sql": "CREATE OR REPLACE FUNCTION notify_on_comment()\nRETURNS TRIGGER AS $$\nDECLARE\n  post_owner INT;\nBEGIN\n  SELECT user_id INTO post_owner FROM posts WHERE post_id = NEW.post_id;\n  IF post_owner != NEW.user_id THEN\n    INSERT INTO notifications (user_id, actor_id, type, post_id, comment_id, message)\n    VALUES (post_owner, NEW.user_id, 'comment', NEW.post_id, NEW.comment_id, 'commented on your post');\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_comment_notify\nAFTER INSERT ON comments\nFOR EACH ROW EXECUTE FUNCTION notify_on_comment();", "explanation": "", "db": "social_db"}, {"id": 467, "section": "Topic 20 — Transactions & Concurrency (25 Qs)", "question": "Basic transaction: Transfer between accounts.", "sql": "BEGIN;\nUPDATE accounts SET balance = balance - 1000 WHERE account_id = 1;\nUPDATE accounts SET balance = balance + 1000 WHERE account_id = 2;\nINSERT INTO transfers (from_account, to_account, amount, status)\nVALUES (1, 2, 1000, 'completed');\nCOMMIT;", "explanation": "BEGIN starts a transaction; COMMIT makes all changes permanent.", "db": "bank_db"}, {"id": 468, "section": "Topic 20 — Transactions & Concurrency (25 Qs)", "question": "Rollback a transaction.", "sql": "BEGIN;\nDELETE FROM orders WHERE status = 'cancelled';\n-- Oops, wrong approach\nROLLBACK;", "explanation": "ROLLBACK undoes all changes since BEGIN.", "db": "ecommerce_db"}, {"id": 469, "section": "Topic 20 — Transactions & Concurrency (25 Qs)", "question": "Savepoint within a transaction.", "sql": "BEGIN;\nINSERT INTO orders (user_id, total_amount) VALUES (1, 100);\nSAVEPOINT sp1;\nINSERT INTO orders (user_id, total_amount) VALUES (1, 200);\n-- Undo only the second insert\nROLLBACK TO sp1;\nCOMMIT;", "explanation": "SAVEPOINT creates a restore point within a transaction.", "db": "ecommerce_db"}, {"id": 470, "section": "Topic 20 — Transactions & Concurrency (25 Qs)", "question": "Set transaction isolation level.", "sql": "BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;\nSELECT * FROM accounts WHERE account_id = 1;\n-- ... do work ...\nCOMMIT;", "explanation": "SERIALIZABLE is the strictest level — prevents all anomalies.", "db": "ecommerce_db"}, {"id": 471, "section": "Topic 20 — Transactions & Concurrency (25 Qs)", "question": "Read Committed vs Repeatable Read.", "sql": "-- Read Committed (default): Each statement sees latest committed data\nBEGIN ISOLATION LEVEL READ COMMITTED;\nSELECT balance FROM accounts WHERE account_id = 1; -- Sees latest\n-- (another transaction commits a change)\nSELECT balance FROM accounts WHERE account_id = 1; -- May see new value\nCOMMIT;\n\n-- Repeatable Read: Snapshot at transaction start\nBEGIN ISOLATION LEVEL REPEATABLE READ;\nSELECT balance FROM accounts WHERE account_id = 1; -- Snapshot\n-- (another transaction commits)\nSELECT balance FROM accounts WHERE account_id = 1; -- Same value\nCOMMIT;", "explanation": "", "db": "bank_db"}, {"id": 472, "section": "Topic 20 — Transactions & Concurrency (25 Qs)", "question": "SELECT FOR UPDATE: Lock rows for update.", "sql": "BEGIN;\nSELECT * FROM accounts WHERE account_id = 1 FOR UPDATE;\n-- Row is now locked until COMMIT/ROLLBACK\nUPDATE accounts SET balance = balance - 500 WHERE account_id = 1;\nCOMMIT;", "explanation": "FOR UPDATE prevents other transactions from modifying the selected rows.", "db": "bank_db"}, {"id": 473, "section": "Topic 20 — Transactions & Concurrency (25 Qs)", "question": "SELECT FOR UPDATE SKIP LOCKED: Process available rows.", "sql": "BEGIN;\nSELECT * FROM orders WHERE status = 'pending'\nORDER BY placed_at LIMIT 1\nFOR UPDATE SKIP LOCKED;\n-- Process the order\nCOMMIT;", "explanation": "SKIP LOCKED enables parallel processing without blocking — great for job queues.", "db": "ecommerce_db"}, {"id": 474, "section": "Topic 20 — Transactions & Concurrency (25 Qs)", "question": "Advisory locks for application-level coordination.", "sql": "-- Acquire a lock (blocks if already held)\nSELECT pg_advisory_lock(12345);\n-- Do exclusive work\nSELECT pg_advisory_unlock(12345);\n\n-- Try-lock (non-blocking)\nSELECT pg_try_advisory_lock(12345) AS acquired;", "explanation": "Advisory locks are cooperative — not tied to specific rows.", "db": "ecommerce_db"}, {"id": 475, "section": "Topic 20 — Transactions & Concurrency (25 Qs)", "question": "Deadlock prevention with consistent ordering.", "sql": "-- WRONG: Can deadlock if two transactions lock in opposite order\n-- Transaction 1: UPDATE accounts SET ... WHERE id = 1; UPDATE ... WHERE id = 2;\n-- Transaction 2: UPDATE accounts SET ... WHERE id = 2; UPDATE ... WHERE id = 1;\n\n-- RIGHT: Always lock in the same order\nBEGIN;\nUPDATE accounts SET balance = balance - 100 WHERE account_id = LEAST(1, 2);\nUPDATE accounts SET balance = balance + 100 WHERE account_id = GREATEST(1, 2);\nCOMMIT;", "explanation": "Always acquire locks in consistent order to prevent deadlocks.", "db": "bank_db"}, {"id": 476, "section": "Topic 20 — Transactions & Concurrency (25 Qs)", "question": "Check current locks.", "sql": "SELECT l.locktype, l.relation::regclass, l.mode, l.granted, a.query\nFROM pg_locks l\nJOIN pg_stat_activity a ON l.pid = a.pid\nWHERE l.relation IS NOT NULL;", "explanation": "pg_locks shows all active locks in the database.", "db": "ecommerce_db"}, {"id": 477, "section": "Topic 20 — Transactions & Concurrency (25 Qs)", "question": "Optimistic concurrency with version column.", "sql": "-- Add version column\nALTER TABLE products ADD COLUMN version INT DEFAULT 1;\n\n-- Update only if version matches (optimistic lock)\nUPDATE products SET base_price = 99.99, version = version + 1\nWHERE product_id = 1 AND version = 5;\n-- If 0 rows affected, someone else modified it — retry", "explanation": "Optimistic locking checks a version/timestamp instead of database locks.", "db": "ecommerce_db"}, {"id": 478, "section": "Topic 21 — Arrays & Array Functions (20 Qs)", "question": "Create a table with an array column.", "sql": "CREATE TABLE product_tags (\n  product_id INT REFERENCES products(product_id),\n  tags TEXT[] DEFAULT '{}'\n);", "explanation": "TEXT[] declares a text array column.", "db": "ecommerce_db"}, {"id": 479, "section": "Topic 21 — Arrays & Array Functions (20 Qs)", "question": "Insert array values.", "sql": "INSERT INTO product_tags (product_id, tags)\nVALUES (1, ARRAY['electronics', 'sale', 'new']),\n       (2, '{clothing, winter, premium}');", "explanation": "ARRAY[] constructor or {} string literal both work.", "db": "ecommerce_db"}, {"id": 480, "section": "Topic 21 — Arrays & Array Functions (20 Qs)", "question": "Access array elements.", "sql": "SELECT product_id, tags[1] AS first_tag, tags[2] AS second_tag,\n  ARRAY_LENGTH(tags, 1) AS tag_count\nFROM product_tags;", "explanation": "PostgreSQL arrays are 1-indexed. ARRAY_LENGTH returns the length.", "db": "ecommerce_db"}, {"id": 481, "section": "Topic 21 — Arrays & Array Functions (20 Qs)", "question": "Check if an array contains a value.", "sql": "SELECT * FROM product_tags WHERE 'sale' = ANY(tags);", "explanation": "ANY checks if any element matches the value.", "db": "ecommerce_db"}, {"id": 482, "section": "Topic 21 — Arrays & Array Functions (20 Qs)", "question": "Check if array contains all specified values.", "sql": "SELECT * FROM product_tags WHERE tags @> ARRAY['sale', 'new'];", "explanation": "@> is the contains operator for arrays.", "db": "ecommerce_db"}, {"id": 483, "section": "Topic 21 — Arrays & Array Functions (20 Qs)", "question": "Array overlap: Check if arrays share any elements.", "sql": "SELECT * FROM product_tags WHERE tags && ARRAY['premium', 'luxury'];", "explanation": "&& returns true if arrays have elements in common.", "db": "ecommerce_db"}, {"id": 484, "section": "Topic 21 — Arrays & Array Functions (20 Qs)", "question": "UNNEST: Expand array to rows.", "sql": "SELECT product_id, UNNEST(tags) AS tag FROM product_tags;", "explanation": "UNNEST is the inverse of ARRAY_AGG.", "db": "ecommerce_db"}, {"id": 485, "section": "Topic 21 — Arrays & Array Functions (20 Qs)", "question": "ARRAY_AGG: Aggregate rows back to array.", "sql": "SELECT category_id, ARRAY_AGG(name ORDER BY name) AS products\nFROM products GROUP BY category_id;", "explanation": "", "db": "ecommerce_db"}, {"id": 486, "section": "Topic 21 — Arrays & Array Functions (20 Qs)", "question": "Append to an array.", "sql": "UPDATE product_tags SET tags = ARRAY_APPEND(tags, 'featured')\nWHERE product_id = 1;", "explanation": "ARRAY_APPEND adds an element to the end.", "db": "ecommerce_db"}, {"id": 487, "section": "Topic 21 — Arrays & Array Functions (20 Qs)", "question": "Remove from an array.", "sql": "UPDATE product_tags SET tags = ARRAY_REMOVE(tags, 'sale')\nWHERE product_id = 1;", "explanation": "ARRAY_REMOVE removes all occurrences of a value.", "db": "ecommerce_db"}, {"id": 488, "section": "Topic 21 — Arrays & Array Functions (20 Qs)", "question": "Concatenate two arrays.", "sql": "SELECT ARRAY[1,2,3] || ARRAY[4,5] AS combined;\n-- Also works with ARRAY_CAT\nSELECT ARRAY_CAT(ARRAY[1,2], ARRAY[3,4]) AS combined;", "explanation": "", "db": "ecommerce_db"}, {"id": 489, "section": "Topic 21 — Arrays & Array Functions (20 Qs)", "question": "Find the position of an element.", "sql": "SELECT ARRAY_POSITION(ARRAY['a','b','c','b'], 'b') AS pos;", "explanation": "Returns the position of the first occurrence.", "db": "ecommerce_db"}, {"id": 490, "section": "Topic 21 — Arrays & Array Functions (20 Qs)", "question": "Replace an array element.", "sql": "SELECT ARRAY_REPLACE(ARRAY['red','green','blue'], 'green', 'yellow') AS updated;", "explanation": "", "db": "ecommerce_db"}, {"id": 491, "section": "Topic 21 — Arrays & Array Functions (20 Qs)", "question": "Slice an array.", "sql": "SELECT (ARRAY[10,20,30,40,50])[2:4] AS slice;", "explanation": "Array slicing uses [start:end] syntax, inclusive.", "db": "ecommerce_db"}, {"id": 492, "section": "Topic 21 — Arrays & Array Functions (20 Qs)", "question": "Generate an array from a series.", "sql": "SELECT ARRAY(SELECT GENERATE_SERIES(1, 10)) AS nums;", "explanation": "ARRAY() constructor wraps a subquery result into an array.", "db": "ecommerce_db"}, {"id": 493, "section": "Topic 21 — Arrays & Array Functions (20 Qs)", "question": "Check array length and dimensions.", "sql": "SELECT\n  ARRAY_LENGTH(ARRAY[[1,2],[3,4]], 1) AS rows,\n  ARRAY_LENGTH(ARRAY[[1,2],[3,4]], 2) AS cols,\n  ARRAY_NDIMS(ARRAY[[1,2],[3,4]]) AS dimensions;", "explanation": "PostgreSQL supports multi-dimensional arrays.", "db": "ecommerce_db"}, {"id": 494, "section": "Topic 21 — Arrays & Array Functions (20 Qs)", "question": "GIN index on array column for fast containment queries.", "sql": "CREATE INDEX idx_tags_gin ON product_tags USING GIN (tags);\n\n-- This query now uses the GIN index\nSELECT * FROM product_tags WHERE tags @> ARRAY['sale'];", "explanation": "GIN indexes support @>, &&, and = operators on arrays.", "db": "ecommerce_db"}, {"id": 495, "section": "Topic 21 — Arrays & Array Functions (20 Qs)", "question": "Convert array to string and back.", "sql": "SELECT ARRAY_TO_STRING(ARRAY['a','b','c'], ', ') AS str;\nSELECT STRING_TO_ARRAY('a, b, c', ', ') AS arr;", "explanation": "ARRAY_TO_STRING and STRING_TO_ARRAY for conversion.", "db": "ecommerce_db"}, {"id": 496, "section": "Topic 22 — Full-Text Search (20 Qs)", "question": "Basic full-text search with `to_tsvector` and `to_tsquery`.", "sql": "SELECT name, base_price FROM products\nWHERE to_tsvector('english', name || ' ' || COALESCE(description, ''))\n  @@ to_tsquery('english', 'wireless & headphone');", "explanation": "to_tsvector converts text to searchable tokens; to_tsquery creates a query.", "db": "ecommerce_db"}, {"id": 497, "section": "Topic 22 — Full-Text Search (20 Qs)", "question": "Use `plainto_tsquery` for natural language input.", "sql": "SELECT name FROM products\nWHERE to_tsvector('english', name) @@ plainto_tsquery('english', 'blue cotton shirt');", "explanation": "plainto_tsquery handles space-separated words — ANDs them together.", "db": "ecommerce_db"}, {"id": 498, "section": "Topic 22 — Full-Text Search (20 Qs)", "question": "Use `phraseto_tsquery` for exact phrase search.", "sql": "SELECT name FROM products\nWHERE to_tsvector('english', name) @@ phraseto_tsquery('english', 'running shoes');", "explanation": "phraseto_tsquery requires words to be adjacent.", "db": "ecommerce_db"}, {"id": 499, "section": "Topic 22 — Full-Text Search (20 Qs)", "question": "Use `websearch_to_tsquery` for Google-like syntax.", "sql": "SELECT name FROM products\nWHERE to_tsvector('english', name) @@ websearch_to_tsquery('english', '\"running shoes\" -kids OR sneakers');", "explanation": "websearch_to_tsquery supports quotes, hyphens (NOT), and OR.", "db": "ecommerce_db"}, {"id": 500, "section": "Topic 22 — Full-Text Search (20 Qs)", "question": "Rank search results with `ts_rank`.", "sql": "SELECT name, ts_rank(to_tsvector('english', name || ' ' || COALESCE(description, '')),\n  to_tsquery('laptop')) AS rank\nFROM products\nWHERE to_tsvector('english', name || ' ' || COALESCE(description, '')) @@ to_tsquery('laptop')\nORDER BY rank DESC;", "explanation": "ts_rank scores results by relevance.", "db": "ecommerce_db"}, {"id": 501, "section": "Topic 22 — Full-Text Search (20 Qs)", "question": "Highlight search matches with `ts_headline`.", "sql": "SELECT ts_headline('english', name || '. ' || COALESCE(description, ''),\n  to_tsquery('laptop'),\n  'StartSel=<b>, StopSel=</b>, MaxWords=35'\n) AS highlighted\nFROM products\nWHERE to_tsvector('english', name || ' ' || COALESCE(description, '')) @@ to_tsquery('laptop');", "explanation": "ts_headline wraps matching words in tags for display.", "db": "ecommerce_db"}, {"id": 502, "section": "Topic 22 — Full-Text Search (20 Qs)", "question": "Create a stored tsvector column for performance.", "sql": "ALTER TABLE products ADD COLUMN search_vector TSVECTOR;\n\nUPDATE products SET search_vector =\n  to_tsvector('english', name || ' ' || COALESCE(description, ''));\n\n-- Keep it updated via trigger\nCREATE TRIGGER trg_products_search\nBEFORE INSERT OR UPDATE ON products\nFOR EACH ROW EXECUTE FUNCTION\n  tsvector_update_trigger(search_vector, 'pg_catalog.english', name, description);", "explanation": "Stored tsvector + trigger avoids recomputing on every query.", "db": "ecommerce_db"}, {"id": 503, "section": "Topic 22 — Full-Text Search (20 Qs)", "question": "Create a GIN index for fast full-text search.", "sql": "CREATE INDEX idx_products_search ON products USING GIN (search_vector);", "explanation": "GIN indexes make full-text search queries fast.", "db": "ecommerce_db"}, {"id": 504, "section": "Topic 22 — Full-Text Search (20 Qs)", "question": "Search with prefix matching (autocomplete).", "sql": "SELECT name FROM products\nWHERE to_tsvector('english', name) @@ to_tsquery('english', 'lap:*');", "explanation": "The :* suffix enables prefix matching.", "db": "ecommerce_db"}, {"id": 505, "section": "Topic 22 — Full-Text Search (20 Qs)", "question": "Search across multiple tables.", "sql": "SELECT 'product' AS type, name AS title, description AS content FROM products\nWHERE to_tsvector('english', name || ' ' || COALESCE(description, '')) @@ plainto_tsquery('wireless')\nUNION ALL\nSELECT 'review', title, body FROM reviews\nWHERE to_tsvector('english', title || ' ' || COALESCE(body, '')) @@ plainto_tsquery('wireless')\nORDER BY type;", "explanation": "UNION ALL to combine search results from multiple tables.", "db": "ecommerce_db"}, {"id": 506, "section": "Topic 22 — Full-Text Search (20 Qs)", "question": "Search posts with ranking.", "sql": "SELECT p.post_id, u.username, p.content,\n  ts_rank(to_tsvector('english', p.content), plainto_tsquery('programming tutorial')) AS rank\nFROM posts p JOIN users u ON p.user_id = u.user_id\nWHERE to_tsvector('english', p.content) @@ plainto_tsquery('programming tutorial')\nORDER BY rank DESC LIMIT 20;", "explanation": "", "db": "social_db"}, {"id": 507, "section": "Topic 22 — Full-Text Search (20 Qs)", "question": "Boolean operators in tsquery.", "sql": "SELECT name FROM products WHERE to_tsvector('english', name || ' ' || COALESCE(description, ''))\n  @@ to_tsquery('english', '(laptop | tablet) & !refurbished');", "explanation": "& = AND, | = OR, ! = NOT in tsquery.", "db": "ecommerce_db"}, {"id": 508, "section": "Topic 23 — Table Design & Constraints (20 Qs)", "question": "CREATE TABLE with all constraint types.", "sql": "CREATE TABLE demo_orders (\n  order_id SERIAL PRIMARY KEY,\n  customer_id INT NOT NULL REFERENCES users(user_id),\n  amount NUMERIC(12,2) CHECK (amount > 0),\n  status VARCHAR(30) DEFAULT 'pending' CHECK (status IN ('pending','confirmed','cancelled')),\n  code VARCHAR(20) UNIQUE,\n  placed_at TIMESTAMP DEFAULT NOW()\n);", "explanation": "Demonstrates PRIMARY KEY, FOREIGN KEY, CHECK, UNIQUE, DEFAULT, NOT NULL.", "db": "ecommerce_db"}, {"id": 509, "section": "Topic 23 — Table Design & Constraints (20 Qs)", "question": "Named constraints for better error messages.", "sql": "CREATE TABLE demo_items (\n  item_id SERIAL,\n  order_id INT NOT NULL,\n  qty INT NOT NULL,\n  price NUMERIC(10,2) NOT NULL,\n  CONSTRAINT pk_demo_items PRIMARY KEY (item_id),\n  CONSTRAINT fk_demo_items_order FOREIGN KEY (order_id) REFERENCES demo_orders(order_id) ON DELETE CASCADE,\n  CONSTRAINT chk_positive_qty CHECK (qty > 0),\n  CONSTRAINT chk_positive_price CHECK (price > 0)\n);", "explanation": "Named constraints make error messages readable and management easier.", "db": "ecommerce_db"}, {"id": 510, "section": "Topic 23 — Table Design & Constraints (20 Qs)", "question": "Add a constraint to an existing table.", "sql": "ALTER TABLE products\n  ADD CONSTRAINT chk_positive_price CHECK (base_price >= 0);", "explanation": "", "db": "ecommerce_db"}, {"id": 511, "section": "Topic 23 — Table Design & Constraints (20 Qs)", "question": "Drop a constraint.", "sql": "ALTER TABLE products DROP CONSTRAINT chk_positive_price;", "explanation": "", "db": "ecommerce_db"}, {"id": 512, "section": "Topic 23 — Table Design & Constraints (20 Qs)", "question": "Add a column with constraints.", "sql": "ALTER TABLE users ADD COLUMN last_login TIMESTAMP;\nALTER TABLE users ADD COLUMN login_count INT DEFAULT 0 CHECK (login_count >= 0);", "explanation": "", "db": "ecommerce_db"}, {"id": 513, "section": "Topic 23 — Table Design & Constraints (20 Qs)", "question": "Foreign key actions: CASCADE, SET NULL, RESTRICT.", "sql": "CREATE TABLE child_table (\n  id SERIAL PRIMARY KEY,\n  parent_id INT,\n  CONSTRAINT fk_cascade FOREIGN KEY (parent_id)\n    REFERENCES parent_table(id) ON DELETE CASCADE ON UPDATE CASCADE\n);\n-- CASCADE: Delete/update child rows automatically\n-- SET NULL: Set FK to NULL on parent delete\n-- RESTRICT: Prevent parent delete if children exist (default)\n-- SET DEFAULT: Set FK to default value", "explanation": "Referential integrity options control what happens on parent changes.", "db": "ecommerce_db"}, {"id": 514, "section": "Topic 23 — Table Design & Constraints (20 Qs)", "question": "Composite primary key.", "sql": "CREATE TABLE enrollment_pk (\n  student_id INT REFERENCES students(student_id),\n  section_id INT REFERENCES sections(section_id),\n  enrolled_at TIMESTAMP DEFAULT NOW(),\n  PRIMARY KEY (student_id, section_id)\n);", "explanation": "Composite PK ensures no duplicate enrollments.", "db": "university_db"}, {"id": 515, "section": "Topic 23 — Table Design & Constraints (20 Qs)", "question": "Exclusion constraint (prevent overlapping ranges).", "sql": "CREATE TABLE room_bookings (\n  booking_id SERIAL PRIMARY KEY,\n  room_id INT NOT NULL,\n  booked_from TIMESTAMP NOT NULL,\n  booked_until TIMESTAMP NOT NULL,\n  EXCLUDE USING GIST (\n    room_id WITH =,\n    tsrange(booked_from, booked_until) WITH &&\n  )\n);", "explanation": "Exclusion constraints prevent overlapping time ranges per room — requires btree_gist extension.", "db": "hospital_db"}, {"id": 516, "section": "Topic 23 — Table Design & Constraints (20 Qs)", "question": "Generated (computed) column.", "sql": "ALTER TABLE products ADD COLUMN price_with_tax NUMERIC(12,2)\n  GENERATED ALWAYS AS (base_price * 1.18) STORED;", "explanation": "GENERATED ALWAYS AS creates a computed column — STORED means physically stored.", "db": "ecommerce_db"}, {"id": 517, "section": "Topic 23 — Table Design & Constraints (20 Qs)", "question": "SERIAL vs IDENTITY vs UUID for primary keys.", "sql": "-- SERIAL (traditional)\nCREATE TABLE t1 (id SERIAL PRIMARY KEY);\n\n-- IDENTITY (SQL standard, preferred)\nCREATE TABLE t2 (id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY);\n\n-- UUID (distributed-friendly)\nCREATE TABLE t3 (id UUID DEFAULT gen_random_uuid() PRIMARY KEY);", "explanation": "IDENTITY is modern standard; UUID avoids sequence contention.", "db": "ecommerce_db"}, {"id": 518, "section": "Topic 23 — Table Design & Constraints (20 Qs)", "question": "Table partitioning by range.", "sql": "CREATE TABLE orders_partitioned (\n  order_id SERIAL,\n  placed_at TIMESTAMP NOT NULL,\n  total_amount NUMERIC(12,2)\n) PARTITION BY RANGE (placed_at);\n\nCREATE TABLE orders_2024 PARTITION OF orders_partitioned\n  FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');\nCREATE TABLE orders_2025 PARTITION OF orders_partitioned\n  FOR VALUES FROM ('2025-01-01') TO ('2026-01-01');", "explanation": "Range partitioning splits data by value ranges — great for time-series.", "db": "ecommerce_db"}, {"id": 519, "section": "Topic 23 — Table Design & Constraints (20 Qs)", "question": "Table partitioning by list.", "sql": "CREATE TABLE transactions_by_type (\n  txn_id BIGSERIAL,\n  type VARCHAR(30) NOT NULL,\n  amount NUMERIC(15,2)\n) PARTITION BY LIST (type);\n\nCREATE TABLE txn_credit PARTITION OF transactions_by_type FOR VALUES IN ('credit');\nCREATE TABLE txn_debit PARTITION OF transactions_by_type FOR VALUES IN ('debit');\nCREATE TABLE txn_transfer PARTITION OF transactions_by_type FOR VALUES IN ('transfer');", "explanation": "", "db": "bank_db"}, {"id": 520, "section": "Topic 23 — Table Design & Constraints (20 Qs)", "question": "Table partitioning by hash.", "sql": "CREATE TABLE page_views_hash (\n  view_id BIGSERIAL,\n  user_id INT,\n  viewed_at TIMESTAMP\n) PARTITION BY HASH (user_id);\n\nCREATE TABLE pv_hash_0 PARTITION OF page_views_hash FOR VALUES WITH (MODULUS 4, REMAINDER 0);\nCREATE TABLE pv_hash_1 PARTITION OF page_views_hash FOR VALUES WITH (MODULUS 4, REMAINDER 1);\nCREATE TABLE pv_hash_2 PARTITION OF page_views_hash FOR VALUES WITH (MODULUS 4, REMAINDER 2);\nCREATE TABLE pv_hash_3 PARTITION OF page_views_hash FOR VALUES WITH (MODULUS 4, REMAINDER 3);", "explanation": "Hash partitioning distributes data evenly across partitions.", "db": "ecommerce_db"}, {"id": 521, "section": "Topic 23 — Table Design & Constraints (20 Qs)", "question": "Rename a table and column.", "sql": "ALTER TABLE demo_orders RENAME TO sample_orders;\nALTER TABLE sample_orders RENAME COLUMN amount TO total_amount;", "explanation": "", "db": "ecommerce_db"}, {"id": 522, "section": "Topic 23 — Table Design & Constraints (20 Qs)", "question": "Change column type.", "sql": "ALTER TABLE products ALTER COLUMN description TYPE TEXT;\nALTER TABLE products ALTER COLUMN base_price TYPE NUMERIC(12,2);", "explanation": "", "db": "ecommerce_db"}, {"id": 523, "section": "Topic 24 — Type Casting & Conversions (15 Qs)", "question": "Cast using :: syntax (PostgreSQL-specific).", "sql": "SELECT '42'::INT AS num, '2025-01-15'::DATE AS dt, 3.14::TEXT AS txt;", "explanation": ":: is PostgreSQL's shorthand cast syntax.", "db": "ecommerce_db"}, {"id": 524, "section": "Topic 24 — Type Casting & Conversions (15 Qs)", "question": "Cast using CAST() function (SQL standard).", "sql": "SELECT CAST('42' AS INTEGER), CAST('2025-01-15' AS DATE), CAST(3.14 AS TEXT);", "explanation": "CAST() is the ANSI SQL standard way.", "db": "ecommerce_db"}, {"id": 525, "section": "Topic 24 — Type Casting & Conversions (15 Qs)", "question": "Implicit vs explicit casting.", "sql": "SELECT 5 + '3'::INT AS explicit_cast;\n-- PostgreSQL will NOT implicitly cast '3' here:\n-- SELECT 5 + '3'; -- This fails!\n-- But numeric types are implicitly compatible:\nSELECT 5 + 3.14; -- INT + NUMERIC = NUMERIC", "explanation": "PostgreSQL is stricter than MySQL about implicit casting.", "db": "ecommerce_db"}, {"id": 526, "section": "Topic 24 — Type Casting & Conversions (15 Qs)", "question": "TO_CHAR for formatting numbers and dates.", "sql": "SELECT\n  TO_CHAR(1234567.89, 'FM$999,999,999.00') AS formatted_money,\n  TO_CHAR(NOW(), 'Day, DD Month YYYY HH24:MI') AS formatted_date,\n  TO_CHAR(0.456, 'FM990.00%') AS formatted_pct;", "explanation": "TO_CHAR converts values to formatted strings.", "db": "ecommerce_db"}, {"id": 527, "section": "Topic 24 — Type Casting & Conversions (15 Qs)", "question": "TO_NUMBER: Parse formatted string to number.", "sql": "SELECT TO_NUMBER('$1,234,567.89', 'L9,999,999.99') AS parsed;", "explanation": "TO_NUMBER reverses TO_CHAR formatting.", "db": "ecommerce_db"}, {"id": 528, "section": "Topic 24 — Type Casting & Conversions (15 Qs)", "question": "TO_DATE and TO_TIMESTAMP: Parse date strings.", "sql": "SELECT TO_DATE('15/03/2025', 'DD/MM/YYYY') AS parsed_date;\nSELECT TO_TIMESTAMP('2025-03-15 14:30:00', 'YYYY-MM-DD HH24:MI:SS') AS parsed_ts;", "explanation": "", "db": "ecommerce_db"}, {"id": 529, "section": "Topic 24 — Type Casting & Conversions (15 Qs)", "question": "Cast BOOLEAN to INT and vice versa.", "sql": "SELECT TRUE::INT AS bool_to_int, 1::BOOLEAN AS int_to_bool, 0::BOOLEAN AS zero_to_bool;", "explanation": "", "db": "ecommerce_db"}, {"id": 530, "section": "Topic 24 — Type Casting & Conversions (15 Qs)", "question": "Convert between text and array.", "sql": "SELECT STRING_TO_ARRAY('a,b,c,d', ',') AS arr;\nSELECT ARRAY_TO_STRING(ARRAY['a','b','c'], '-') AS str;", "explanation": "", "db": "ecommerce_db"}, {"id": 531, "section": "Topic 24 — Type Casting & Conversions (15 Qs)", "question": "Cast INET and CIDR types.", "sql": "SELECT '192.168.1.1'::INET AS ip,\n  '192.168.1.0/24'::CIDR AS subnet,\n  '192.168.1.5'::INET << '192.168.1.0/24'::CIDR AS is_in_subnet;", "explanation": "<< checks if an IP is contained in a subnet.", "db": "ecommerce_db"}, {"id": 532, "section": "Topic 24 — Type Casting & Conversions (15 Qs)", "question": "Enum type for constrained values.", "sql": "CREATE TYPE order_status AS ENUM ('pending', 'confirmed', 'shipped', 'delivered', 'cancelled');\n\n-- Use in a table\nALTER TABLE orders ALTER COLUMN status TYPE order_status USING status::order_status;", "explanation": "ENUM enforces a fixed set of values — more efficient than CHECK constraints.", "db": "ecommerce_db"}, {"id": 533, "section": "Topic 25 — Common Query Patterns (25 Qs)", "question": "Find duplicates.", "sql": "SELECT email, COUNT(*) FROM users GROUP BY email HAVING COUNT(*) > 1;", "explanation": "Classic duplicate detection using GROUP BY + HAVING.", "db": "ecommerce_db"}, {"id": 534, "section": "Topic 25 — Common Query Patterns (25 Qs)", "question": "Delete duplicates keeping the latest.", "sql": "DELETE FROM reviews\nWHERE review_id NOT IN (\n  SELECT MAX(review_id) FROM reviews GROUP BY user_id, product_id\n);", "explanation": "Keep the row with the highest ID (latest) per group.", "db": "ecommerce_db"}, {"id": 535, "section": "Topic 25 — Common Query Patterns (25 Qs)", "question": "Pagination with keyset (seek method).", "sql": "-- Page 1:\nSELECT * FROM products ORDER BY product_id LIMIT 20;\n\n-- Page 2 (given last_id = 20):\nSELECT * FROM products WHERE product_id > 20 ORDER BY product_id LIMIT 20;", "explanation": "Keyset pagination is faster than OFFSET for large tables.", "db": "ecommerce_db"}, {"id": 536, "section": "Topic 25 — Common Query Patterns (25 Qs)", "question": "Pivot table: Rows to columns.", "sql": "SELECT product_id,\n  SUM(CASE WHEN EXTRACT(MONTH FROM created_at) = 1 THEN 1 ELSE 0 END) AS jan,\n  SUM(CASE WHEN EXTRACT(MONTH FROM created_at) = 2 THEN 1 ELSE 0 END) AS feb,\n  SUM(CASE WHEN EXTRACT(MONTH FROM created_at) = 3 THEN 1 ELSE 0 END) AS mar\nFROM reviews GROUP BY product_id;", "explanation": "Manual pivot using CASE expressions.", "db": "ecommerce_db"}, {"id": 537, "section": "Topic 25 — Common Query Patterns (25 Qs)", "question": "Unpivot: Columns to rows using UNNEST.", "sql": "SELECT product_id, attr, value FROM (\n  SELECT product_id,\n    UNNEST(ARRAY['size', 'color']) AS attr,\n    UNNEST(ARRAY[size, color]) AS value\n  FROM product_variants\n) t WHERE value IS NOT NULL;", "explanation": "UNNEST multiple arrays in parallel to unpivot columns.", "db": "ecommerce_db"}, {"id": 538, "section": "Topic 25 — Common Query Patterns (25 Qs)", "question": "Gaps and islands: Find consecutive date ranges.", "sql": "WITH days AS (\n  SELECT DISTINCT placed_at::DATE AS d FROM orders\n),\nislands AS (\n  SELECT d, d - ROW_NUMBER() OVER (ORDER BY d)::INT AS grp FROM days\n)\nSELECT MIN(d) AS start_date, MAX(d) AS end_date, COUNT(*) AS consecutive_days\nFROM islands GROUP BY grp ORDER BY start_date;", "explanation": "Classic gaps-and-islands technique using ROW_NUMBER.", "db": "ecommerce_db"}, {"id": 539, "section": "Topic 25 — Common Query Patterns (25 Qs)", "question": "Running difference: Calculate balance changes.", "sql": "SELECT txn_id, amount, type,\n  SUM(CASE WHEN type = 'credit' THEN amount ELSE -amount END)\n    OVER (ORDER BY txn_date) AS running_balance\nFROM transactions WHERE account_id = 1;", "explanation": "", "db": "bank_db"}, {"id": 540, "section": "Topic 25 — Common Query Patterns (25 Qs)", "question": "Self-join: Find pairs of products in the same category and price range.", "sql": "SELECT p1.name AS product_1, p2.name AS product_2, p1.category_id,\n  ABS(p1.base_price - p2.base_price) AS price_diff\nFROM products p1 JOIN products p2\n  ON p1.category_id = p2.category_id\n  AND p1.product_id < p2.product_id\n  AND ABS(p1.base_price - p2.base_price) < 10\nORDER BY price_diff;", "explanation": "", "db": "ecommerce_db"}, {"id": 541, "section": "Topic 25 — Common Query Patterns (25 Qs)", "question": "Recursive CTE for bill of materials / tree traversal.", "sql": "WITH RECURSIVE bom AS (\n  SELECT category_id, name, parent_id, 1 AS level, ARRAY[category_id] AS path\n  FROM categories WHERE parent_id IS NULL\n  UNION ALL\n  SELECT c.category_id, c.name, c.parent_id, b.level + 1, b.path || c.category_id\n  FROM categories c JOIN bom b ON c.parent_id = b.category_id\n  WHERE NOT c.category_id = ANY(b.path) -- prevent cycles\n)\nSELECT REPEAT('  ', level - 1) || name AS tree_name, level FROM bom ORDER BY path;", "explanation": "Array in path prevents infinite loops in cyclic data.", "db": "ecommerce_db"}, {"id": 542, "section": "Topic 25 — Common Query Patterns (25 Qs)", "question": "Lateral join: Top N per group.", "sql": "SELECT c.name AS category, p.name AS product, p.base_price\nFROM categories c\nCROSS JOIN LATERAL (\n  SELECT name, base_price FROM products\n  WHERE category_id = c.category_id\n  ORDER BY base_price DESC LIMIT 3\n) p;", "explanation": "LATERAL allows the subquery to reference the preceding table — more efficient than window functions for top-N.", "db": "ecommerce_db"}, {"id": 543, "section": "Topic 25 — Common Query Patterns (25 Qs)", "question": "TABLESAMPLE: Get a random sample efficiently.", "sql": "SELECT * FROM orders TABLESAMPLE BERNOULLI(1);", "explanation": "BERNOULLI(1) samples ~1% of rows randomly — much faster than ORDER BY RANDOM().", "db": "ecommerce_db"}, {"id": 544, "section": "Topic 25 — Common Query Patterns (25 Qs)", "question": "Conditional INSERT with WHERE NOT EXISTS.", "sql": "INSERT INTO follows (follower_id, following_id)\nSELECT 1, 5\nWHERE NOT EXISTS (\n  SELECT 1 FROM follows WHERE follower_id = 1 AND following_id = 5\n);", "explanation": "Alternative to ON CONFLICT for conditional inserts.", "db": "social_db"}, {"id": 545, "section": "Topic 25 — Common Query Patterns (25 Qs)", "question": "Clone table structure without data.", "sql": "CREATE TABLE orders_archive (LIKE orders INCLUDING ALL);", "explanation": "LIKE...INCLUDING ALL copies columns, constraints, indexes, defaults.", "db": "ecommerce_db"}, {"id": 546, "section": "Topic 25 — Common Query Patterns (25 Qs)", "question": "Merge/UPSERT with complex logic.", "sql": "INSERT INTO product_variants (product_id, size, color, price, stock_qty)\nVALUES (1, 'XL', 'Red', 29.99, 50)\nON CONFLICT (product_id, size, color)\nDO UPDATE SET\n  price = EXCLUDED.price,\n  stock_qty = product_variants.stock_qty + EXCLUDED.stock_qty;", "explanation": "EXCLUDED references the proposed insert row in ON CONFLICT.", "db": "ecommerce_db"}, {"id": 547, "section": "Topic 25 — Common Query Patterns (25 Qs)", "question": "Generate test data with GENERATE_SERIES.", "sql": "INSERT INTO page_views (user_id, product_id, viewed_at)\nSELECT\n  (RANDOM() * 100 + 1)::INT,\n  (RANDOM() * 50 + 1)::INT,\n  timestamp '2025-01-01' + (RANDOM() * 365)::INT * INTERVAL '1 day'\nFROM GENERATE_SERIES(1, 10000);", "explanation": "GENERATE_SERIES + RANDOM for realistic test data generation.", "db": "ecommerce_db"}, {"id": 548, "section": "Topic 25 — Common Query Patterns (25 Qs)", "question": "Moving window: YTD cumulative revenue.", "sql": "WITH monthly AS (\n  SELECT DATE_TRUNC('month', placed_at) AS month, SUM(total_amount) AS revenue\n  FROM orders WHERE EXTRACT(YEAR FROM placed_at) = 2025 GROUP BY month\n)\nSELECT month, revenue,\n  SUM(revenue) OVER (ORDER BY month) AS ytd_revenue\nFROM monthly;", "explanation": "", "db": "ecommerce_db"}, {"id": 549, "section": "Topic 26 — Schema Information & Admin (15 Qs)", "question": "List all tables in the current database.", "sql": "SELECT table_name, table_type\nFROM information_schema.tables\nWHERE table_schema = 'public'\nORDER BY table_name;", "explanation": "information_schema is the SQL standard system catalog.", "db": "ecommerce_db"}, {"id": 550, "section": "Topic 26 — Schema Information & Admin (15 Qs)", "question": "List all columns of a specific table.", "sql": "SELECT column_name, data_type, is_nullable, column_default\nFROM information_schema.columns\nWHERE table_name = 'orders' AND table_schema = 'public'\nORDER BY ordinal_position;", "explanation": "", "db": "ecommerce_db"}, {"id": 551, "section": "Topic 26 — Schema Information & Admin (15 Qs)", "question": "Find all foreign key relationships.", "sql": "SELECT\n  tc.table_name AS from_table,\n  kcu.column_name AS from_column,\n  ccu.table_name AS to_table,\n  ccu.column_name AS to_column\nFROM information_schema.table_constraints tc\nJOIN information_schema.key_column_usage kcu ON tc.constraint_name = kcu.constraint_name\nJOIN information_schema.constraint_column_usage ccu ON tc.constraint_name = ccu.constraint_name\nWHERE tc.constraint_type = 'FOREIGN KEY'\nORDER BY from_table;", "explanation": "", "db": "ecommerce_db"}, {"id": 552, "section": "Topic 26 — Schema Information & Admin (15 Qs)", "question": "Find table sizes and row counts.", "sql": "SELECT\n  relname AS table_name,\n  pg_size_pretty(pg_total_relation_size(relid)) AS total_size,\n  pg_size_pretty(pg_relation_size(relid)) AS data_size,\n  n_live_tup AS est_rows\nFROM pg_stat_user_tables\nORDER BY pg_total_relation_size(relid) DESC;", "explanation": "", "db": "ecommerce_db"}, {"id": 553, "section": "Topic 26 — Schema Information & Admin (15 Qs)", "question": "Find the current database, user, and version.", "sql": "SELECT\n  current_database() AS db,\n  current_user AS usr,\n  version() AS pg_version,\n  pg_postmaster_start_time() AS started_at;", "explanation": "", "db": "ecommerce_db"}, {"id": 554, "section": "Topic 26 — Schema Information & Admin (15 Qs)", "question": "Check active connections.", "sql": "SELECT pid, usename, application_name, client_addr, state, query_start, query\nFROM pg_stat_activity\nWHERE datname = current_database()\nORDER BY query_start DESC;", "explanation": "", "db": "ecommerce_db"}, {"id": 555, "section": "Topic 26 — Schema Information & Admin (15 Qs)", "question": "Cancel a long-running query.", "sql": "SELECT pg_cancel_backend(12345); -- Cancel query\nSELECT pg_terminate_backend(12345); -- Force kill connection", "explanation": "pg_cancel_backend sends SIGINT; pg_terminate_backend sends SIGTERM.", "db": "ecommerce_db"}, {"id": 556, "section": "Topic 26 — Schema Information & Admin (15 Qs)", "question": "Check database and table bloat.", "sql": "SELECT\n  schemaname, tablename,\n  pg_size_pretty(pg_total_relation_size(schemaname || '.' || tablename)) AS size,\n  n_dead_tup AS dead_tuples,\n  ROUND(n_dead_tup * 100.0 / NULLIF(n_live_tup + n_dead_tup, 0), 1) AS bloat_pct\nFROM pg_stat_user_tables\nWHERE n_dead_tup > 0\nORDER BY n_dead_tup DESC;", "explanation": "High dead_tup count indicates the table needs VACUUM.", "db": "ecommerce_db"}, {"id": 557, "section": "Topic 26 — Schema Information & Admin (15 Qs)", "question": "Export query results to CSV.", "sql": "COPY (SELECT * FROM orders WHERE status = 'delivered')\nTO '/tmp/delivered_orders.csv'\nWITH (FORMAT CSV, HEADER TRUE);", "explanation": "COPY TO exports data to a file on the server.", "db": "ecommerce_db"}, {"id": 558, "section": "Topic 26 — Schema Information & Admin (15 Qs)", "question": "Import CSV data.", "sql": "COPY orders (user_id, total_amount, status)\nFROM '/tmp/new_orders.csv'\nWITH (FORMAT CSV, HEADER TRUE, DELIMITER ',');", "explanation": "COPY FROM imports data from a CSV file.", "db": "ecommerce_db"}, {"id": 559, "section": "Topic 26 — Schema Information & Admin (15 Qs)", "question": "Grant and revoke permissions.", "sql": "GRANT SELECT, INSERT ON orders TO readonly_user;\nGRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA public TO admin_user;\nREVOKE DELETE ON orders FROM readonly_user;", "explanation": "PostgreSQL uses role-based access control.", "db": "ecommerce_db"}, {"id": 560, "section": "Topic 26 — Schema Information & Admin (15 Qs)", "question": "Create a read-only role.", "sql": "CREATE ROLE readonly;\nGRANT CONNECT ON DATABASE mydb TO readonly;\nGRANT USAGE ON SCHEMA public TO readonly;\nGRANT SELECT ON ALL TABLES IN SCHEMA public TO readonly;\nALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT ON TABLES TO readonly;", "explanation": "DEFAULT PRIVILEGES ensure future tables also get the grant.", "db": "ecommerce_db"}, {"id": 561, "section": "Topic 27 — Extensions & Advanced Features (20 Qs)", "question": "List installed extensions.", "sql": "SELECT extname, extversion FROM pg_extension ORDER BY extname;", "explanation": "", "db": "ecommerce_db"}, {"id": 562, "section": "Topic 27 — Extensions & Advanced Features (20 Qs)", "question": "Install the `pg_trgm` extension for fuzzy text search.", "sql": "CREATE EXTENSION IF NOT EXISTS pg_trgm;\n\n-- Trigram similarity search\nSELECT name, SIMILARITY(name, 'wirelss headfone') AS sim\nFROM products\nWHERE name % 'wirelss headfone'\nORDER BY sim DESC LIMIT 5;", "explanation": "pg_trgm uses trigram matching for fuzzy search — finds results despite typos.", "db": "ecommerce_db"}, {"id": 563, "section": "Topic 27 — Extensions & Advanced Features (20 Qs)", "question": "Create a GIN index with pg_trgm for fast fuzzy search.", "sql": "CREATE INDEX idx_products_name_trgm ON products USING GIN (name gin_trgm_ops);", "explanation": "gin_trgm_ops enables %, similarity(), and ILIKE to use the index.", "db": "ecommerce_db"}, {"id": 564, "section": "Topic 27 — Extensions & Advanced Features (20 Qs)", "question": "Install and use `uuid-ossp` extension.", "sql": "CREATE EXTENSION IF NOT EXISTS \"uuid-ossp\";\n\nSELECT uuid_generate_v4() AS random_uuid;\n\n-- Or use built-in (PG 13+)\nSELECT gen_random_uuid() AS random_uuid;", "explanation": "UUID v4 generates random universally unique identifiers.", "db": "ecommerce_db"}, {"id": 565, "section": "Topic 27 — Extensions & Advanced Features (20 Qs)", "question": "Install `tablefunc` for CROSSTAB (pivot tables).", "sql": "CREATE EXTENSION IF NOT EXISTS tablefunc;\n\nSELECT * FROM CROSSTAB(\n  'SELECT user_id, status, COUNT(*) FROM orders GROUP BY user_id, status ORDER BY 1, 2',\n  'SELECT DISTINCT status FROM orders ORDER BY 1'\n) AS ct(user_id INT, cancelled BIGINT, delivered BIGINT, pending BIGINT, shipped BIGINT);", "explanation": "CROSSTAB dynamically pivots rows to columns.", "db": "ecommerce_db"}, {"id": 566, "section": "Topic 27 — Extensions & Advanced Features (20 Qs)", "question": "Use `btree_gist` for exclusion constraints.", "sql": "CREATE EXTENSION IF NOT EXISTS btree_gist;\n\nCREATE TABLE schedules (\n  id SERIAL PRIMARY KEY,\n  room VARCHAR(20) NOT NULL,\n  during TSRANGE NOT NULL,\n  EXCLUDE USING GIST (room WITH =, during WITH &&)\n);", "explanation": "btree_gist allows mixing btree and gist types in exclusion constraints.", "db": "ecommerce_db"}, {"id": 567, "section": "Topic 27 — Extensions & Advanced Features (20 Qs)", "question": "Use `pg_stat_statements` to find slow queries.", "sql": "CREATE EXTENSION IF NOT EXISTS pg_stat_statements;\n\nSELECT query, calls, \n  ROUND(mean_exec_time::NUMERIC, 2) AS avg_ms,\n  ROUND(total_exec_time::NUMERIC, 2) AS total_ms,\n  rows\nFROM pg_stat_statements\nORDER BY mean_exec_time DESC LIMIT 10;", "explanation": "Essential for production query performance monitoring.", "db": "ecommerce_db"}, {"id": 568, "section": "Topic 27 — Extensions & Advanced Features (20 Qs)", "question": "Use `hstore` for key-value storage.", "sql": "CREATE EXTENSION IF NOT EXISTS hstore;\n\nSELECT 'color => red, size => XL, material => cotton'::hstore AS props;\nSELECT ('color => red, size => XL'::hstore) -> 'color' AS color;", "explanation": "hstore provides lightweight key-value storage — lighter than JSONB.", "db": "ecommerce_db"}, {"id": 569, "section": "Topic 27 — Extensions & Advanced Features (20 Qs)", "question": "Use `citext` for case-insensitive text.", "sql": "CREATE EXTENSION IF NOT EXISTS citext;\n\nCREATE TABLE demo_users (\n  id SERIAL PRIMARY KEY,\n  email CITEXT UNIQUE NOT NULL\n);\n\n-- These are considered equal:\nINSERT INTO demo_users (email) VALUES ('User@Example.com');\n-- INSERT INTO demo_users (email) VALUES ('user@example.com'); -- Would fail!", "explanation": "citext makes all text comparisons case-insensitive automatically.", "db": "ecommerce_db"}, {"id": 570, "section": "Topic 27 — Extensions & Advanced Features (20 Qs)", "question": "Use `pgcrypto` for password hashing.", "sql": "CREATE EXTENSION IF NOT EXISTS pgcrypto;\n\n-- Hash a password\nSELECT crypt('mypassword', gen_salt('bf', 8)) AS hashed;\n\n-- Verify a password\nSELECT (crypt('mypassword', stored_hash) = stored_hash) AS valid\nFROM (SELECT crypt('mypassword', gen_salt('bf')) AS stored_hash) sub;", "explanation": "pgcrypto provides bcrypt hashing — never store plain passwords.", "db": "ecommerce_db"}, {"id": 571, "section": "Topic 27 — Extensions & Advanced Features (20 Qs)", "question": "LISTEN/NOTIFY for real-time events.", "sql": "-- Terminal 1: Listen for events\nLISTEN order_placed;\n\n-- Terminal 2: Send a notification\nNOTIFY order_placed, '{\"order_id\": 42, \"amount\": 99.99}';\n\n-- Or with pg_notify function\nSELECT pg_notify('order_placed', '{\"order_id\": 42}');", "explanation": "LISTEN/NOTIFY enables pub/sub messaging within PostgreSQL.", "db": "ecommerce_db"}, {"id": 572, "section": "Topic 27 — Extensions & Advanced Features (20 Qs)", "question": "Logical replication setup (publication/subscription).", "sql": "-- On publisher\nCREATE PUBLICATION my_pub FOR TABLE orders, users;\n\n-- On subscriber\nCREATE SUBSCRIPTION my_sub\n  CONNECTION 'host=publisher_host dbname=mydb'\n  PUBLICATION my_pub;", "explanation": "Logical replication enables selective table replication.", "db": "ecommerce_db"}, {"id": 573, "section": "Topic 27 — Extensions & Advanced Features (20 Qs)", "question": "Foreign Data Wrapper (FDW) for external data.", "sql": "CREATE EXTENSION IF NOT EXISTS postgres_fdw;\n\nCREATE SERVER remote_server FOREIGN DATA WRAPPER postgres_fdw\n  OPTIONS (host 'remote_host', dbname 'remote_db', port '5432');\n\nCREATE USER MAPPING FOR CURRENT_USER\n  SERVER remote_server OPTIONS (user 'remote_user', password 'pass');\n\nCREATE FOREIGN TABLE remote_orders (\n  order_id INT, total_amount NUMERIC, status VARCHAR\n) SERVER remote_server OPTIONS (table_name 'orders');\n\nSELECT * FROM remote_orders LIMIT 10;", "explanation": "FDWs query external databases as if they were local tables.", "db": "ecommerce_db"}, {"id": 574, "section": "Topic 28 — Advanced Analytics & Reporting (30 Qs)", "question": "Cohort analysis: Retention by registration month.", "sql": "WITH cohort AS (\n  SELECT user_id, DATE_TRUNC('month', created_at) AS cohort_month FROM users\n),\nactivity AS (\n  SELECT DISTINCT o.user_id, DATE_TRUNC('month', o.placed_at) AS activity_month\n  FROM orders o\n)\nSELECT c.cohort_month,\n  EXTRACT(MONTH FROM AGE(a.activity_month, c.cohort_month)) AS months_since,\n  COUNT(DISTINCT a.user_id) AS active_users,\n  COUNT(DISTINCT a.user_id) * 100.0 / COUNT(DISTINCT c.user_id) AS retention_pct\nFROM cohort c LEFT JOIN activity a ON c.user_id = a.user_id AND a.activity_month >= c.cohort_month\nGROUP BY c.cohort_month, months_since\nORDER BY cohort_month, months_since;", "explanation": "Classic cohort retention analysis — tracks user engagement over time.", "db": "ecommerce_db"}, {"id": 575, "section": "Topic 28 — Advanced Analytics & Reporting (30 Qs)", "question": "Funnel analysis: Cart → Order → Payment conversion.", "sql": "WITH funnel AS (\n  SELECT\n    COUNT(DISTINCT c.user_id) AS cart_users,\n    COUNT(DISTINCT o.user_id) AS order_users,\n    COUNT(DISTINCT p.order_id) AS paid_orders\n  FROM carts c\n  LEFT JOIN orders o ON c.user_id = o.user_id\n  LEFT JOIN payments p ON o.order_id = p.order_id AND p.status = 'completed'\n)\nSELECT cart_users, order_users, paid_orders,\n  ROUND(order_users * 100.0 / NULLIF(cart_users, 0), 1) AS cart_to_order_pct,\n  ROUND(paid_orders * 100.0 / NULLIF(order_users, 0), 1) AS order_to_payment_pct\nFROM funnel;", "explanation": "E-commerce conversion funnel.", "db": "ecommerce_db"}, {"id": 576, "section": "Topic 28 — Advanced Analytics & Reporting (30 Qs)", "question": "RFM Analysis: Segment customers by Recency, Frequency, Monetary.", "sql": "WITH rfm AS (\n  SELECT user_id,\n    CURRENT_DATE - MAX(placed_at)::DATE AS recency,\n    COUNT(*) AS frequency,\n    SUM(total_amount) AS monetary\n  FROM orders GROUP BY user_id\n),\nscored AS (\n  SELECT *,\n    NTILE(5) OVER (ORDER BY recency DESC) AS r_score,\n    NTILE(5) OVER (ORDER BY frequency) AS f_score,\n    NTILE(5) OVER (ORDER BY monetary) AS m_score\n  FROM rfm\n)\nSELECT *, r_score + f_score + m_score AS rfm_total,\n  CASE\n    WHEN r_score + f_score + m_score >= 13 THEN 'Champions'\n    WHEN r_score + f_score + m_score >= 10 THEN 'Loyal'\n    WHEN r_score + f_score + m_score >= 7 THEN 'Potential'\n    WHEN r_score + f_score + m_score >= 4 THEN 'At Risk'\n    ELSE 'Lost'\n  END AS segment\nFROM scored ORDER BY rfm_total DESC;", "explanation": "RFM segmentation is a key marketing analytics technique.", "db": "ecommerce_db"}, {"id": 577, "section": "Topic 28 — Advanced Analytics & Reporting (30 Qs)", "question": "Month-over-month growth rate.", "sql": "WITH monthly AS (\n  SELECT DATE_TRUNC('month', placed_at) AS month, SUM(total_amount) AS revenue\n  FROM orders GROUP BY month\n)\nSELECT month, revenue,\n  LAG(revenue) OVER (ORDER BY month) AS prev_month,\n  ROUND((revenue - LAG(revenue) OVER (ORDER BY month)) / NULLIF(LAG(revenue) OVER (ORDER BY month), 0) * 100, 1) AS mom_growth_pct\nFROM monthly ORDER BY month;", "explanation": "", "db": "ecommerce_db"}, {"id": 578, "section": "Topic 28 — Advanced Analytics & Reporting (30 Qs)", "question": "Moving average with window: 30-day revenue trend.", "sql": "WITH daily AS (\n  SELECT placed_at::DATE AS day, SUM(total_amount) AS revenue FROM orders GROUP BY day\n)\nSELECT day, revenue,\n  ROUND(AVG(revenue) OVER (ORDER BY day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW), 2) AS ma_30\nFROM daily ORDER BY day;", "explanation": "", "db": "ecommerce_db"}, {"id": 579, "section": "Topic 28 — Advanced Analytics & Reporting (30 Qs)", "question": "ABC analysis: Classify products by revenue contribution.", "sql": "WITH product_rev AS (\n  SELECT pv.product_id, SUM(oi.quantity * oi.unit_price) AS revenue\n  FROM order_items oi JOIN product_variants pv ON oi.variant_id = pv.variant_id\n  GROUP BY pv.product_id\n),\ncumulative AS (\n  SELECT *, SUM(revenue) OVER (ORDER BY revenue DESC) AS cum_rev,\n    SUM(revenue) OVER () AS total_rev\n  FROM product_rev\n)\nSELECT p.name, c.revenue,\n  ROUND(c.cum_rev / c.total_rev * 100, 1) AS cum_pct,\n  CASE\n    WHEN c.cum_rev / c.total_rev <= 0.8 THEN 'A (Top 80%)'\n    WHEN c.cum_rev / c.total_rev <= 0.95 THEN 'B (Next 15%)'\n    ELSE 'C (Bottom 5%)'\n  END AS abc_class\nFROM cumulative c JOIN products p ON c.product_id = p.product_id\nORDER BY c.revenue DESC;", "explanation": "ABC/Pareto analysis — A items drive 80% of revenue.", "db": "ecommerce_db"}, {"id": 580, "section": "Topic 28 — Advanced Analytics & Reporting (30 Qs)", "question": "Market basket analysis: Products frequently bought together.", "sql": "SELECT p1.name AS product_1, p2.name AS product_2, COUNT(*) AS co_purchases\nFROM order_items oi1\nJOIN order_items oi2 ON oi1.order_id = oi2.order_id AND oi1.variant_id < oi2.variant_id\nJOIN product_variants pv1 ON oi1.variant_id = pv1.variant_id\nJOIN product_variants pv2 ON oi2.variant_id = pv2.variant_id\nJOIN products p1 ON pv1.product_id = p1.product_id\nJOIN products p2 ON pv2.product_id = p2.product_id\nGROUP BY p1.name, p2.name\nHAVING COUNT(*) > 5\nORDER BY co_purchases DESC LIMIT 20;", "explanation": "Find product pairs that frequently appear in the same order.", "db": "ecommerce_db"}, {"id": 581, "section": "Topic 28 — Advanced Analytics & Reporting (30 Qs)", "question": "Churn analysis: Find users who haven't ordered in 90 days.", "sql": "SELECT u.user_id, u.username, u.email,\n  MAX(o.placed_at) AS last_order,\n  CURRENT_DATE - MAX(o.placed_at)::DATE AS days_since_last\nFROM users u JOIN orders o ON u.user_id = o.user_id\nGROUP BY u.user_id, u.username, u.email\nHAVING MAX(o.placed_at) < NOW() - INTERVAL '90 days'\nORDER BY days_since_last DESC;", "explanation": "", "db": "ecommerce_db"}, {"id": 582, "section": "Topic 28 — Advanced Analytics & Reporting (30 Qs)", "question": "Customer lifetime value (CLV) calculation.", "sql": "WITH customer_stats AS (\n  SELECT user_id,\n    COUNT(*) AS total_orders,\n    SUM(total_amount) AS total_revenue,\n    MIN(placed_at) AS first_order,\n    MAX(placed_at) AS last_order,\n    EXTRACT(DAYS FROM MAX(placed_at) - MIN(placed_at)) AS lifespan_days\n  FROM orders GROUP BY user_id\n)\nSELECT u.username,\n  cs.total_orders, cs.total_revenue,\n  ROUND(cs.total_revenue / NULLIF(cs.total_orders, 0), 2) AS avg_order_value,\n  ROUND(cs.total_orders * 365.0 / NULLIF(cs.lifespan_days, 0), 1) AS annual_frequency,\n  ROUND(cs.total_revenue * 365.0 / NULLIF(cs.lifespan_days, 0), 2) AS annual_clv\nFROM customer_stats cs JOIN users u ON cs.user_id = u.user_id\nWHERE cs.total_orders > 1\nORDER BY annual_clv DESC;", "explanation": "", "db": "ecommerce_db"}, {"id": 583, "section": "Topic 28 — Advanced Analytics & Reporting (30 Qs)", "question": "Revenue by hour heatmap data.", "sql": "SELECT\n  TO_CHAR(placed_at, 'Day') AS day_name,\n  EXTRACT(DOW FROM placed_at) AS dow,\n  EXTRACT(HOUR FROM placed_at) AS hour,\n  COUNT(*) AS orders,\n  SUM(total_amount) AS revenue\nFROM orders\nGROUP BY day_name, dow, hour\nORDER BY dow, hour;", "explanation": "Generates data for a day-hour heatmap visualization.", "db": "ecommerce_db"}, {"id": 584, "section": "Topic 28 — Advanced Analytics & Reporting (30 Qs)", "question": "Readmission rate analysis.", "sql": "WITH discharged AS (\n  SELECT patient_id, discharged_at,\n    LEAD(admitted_at) OVER (PARTITION BY patient_id ORDER BY admitted_at) AS next_admission\n  FROM admissions WHERE discharged_at IS NOT NULL\n)\nSELECT\n  COUNT(*) AS total_discharges,\n  COUNT(*) FILTER (WHERE next_admission IS NOT NULL AND next_admission - discharged_at < INTERVAL '30 days') AS readmissions_30d,\n  ROUND(COUNT(*) FILTER (WHERE next_admission IS NOT NULL AND next_admission - discharged_at < INTERVAL '30 days') * 100.0 / COUNT(*), 1) AS readmission_rate\nFROM discharged;", "explanation": "30-day readmission rate — key hospital quality metric.", "db": "hospital_db"}, {"id": 585, "section": "Topic 28 — Advanced Analytics & Reporting (30 Qs)", "question": "Student performance trend over semesters.", "sql": "WITH semester_gpa AS (\n  SELECT e.student_id, sem.name AS semester, sem.year,\n    ROUND(SUM(e.grade_points * c.credits) / NULLIF(SUM(c.credits), 0), 2) AS semester_gpa\n  FROM enrollments e\n  JOIN sections sec ON e.section_id = sec.section_id\n  JOIN courses c ON sec.course_id = c.course_id\n  JOIN semesters sem ON sec.semester_id = sem.semester_id\n  WHERE e.grade_points IS NOT NULL\n  GROUP BY e.student_id, sem.name, sem.year\n)\nSELECT student_id, semester, year, semester_gpa,\n  AVG(semester_gpa) OVER (PARTITION BY student_id ORDER BY year ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumul_gpa\nFROM semester_gpa ORDER BY student_id, year;", "explanation": "", "db": "university_db"}, {"id": 586, "section": "Topic 28 — Advanced Analytics & Reporting (30 Qs)", "question": "Loan risk scoring dashboard.", "sql": "WITH loan_stats AS (\n  SELECT l.loan_id, l.customer_id, l.principal, l.interest_rate,\n    COUNT(lr.repayment_id) AS total_installments,\n    COUNT(*) FILTER (WHERE lr.status = 'overdue') AS overdue_count,\n    COUNT(*) FILTER (WHERE lr.paid_date > lr.due_date) AS late_payments,\n    COALESCE(SUM(lr.penalty), 0) AS total_penalties\n  FROM loans l LEFT JOIN loan_repayments lr ON l.loan_id = lr.loan_id\n  GROUP BY l.loan_id, l.customer_id, l.principal, l.interest_rate\n)\nSELECT *,\n  CASE\n    WHEN overdue_count > 3 OR late_payments > total_installments * 0.5 THEN 'High Risk'\n    WHEN overdue_count > 0 OR late_payments > total_installments * 0.2 THEN 'Medium Risk'\n    ELSE 'Low Risk'\n  END AS risk_level\nFROM loan_stats ORDER BY overdue_count DESC;", "explanation": "", "db": "bank_db"}, {"id": 587, "section": "Topic 28 — Advanced Analytics & Reporting (30 Qs)", "question": "Social media engagement score.", "sql": "WITH user_engagement AS (\n  SELECT u.user_id, u.username,\n    (SELECT COUNT(*) FROM posts WHERE user_id = u.user_id) AS posts,\n    (SELECT COUNT(*) FROM comments WHERE user_id = u.user_id) AS comments,\n    (SELECT COUNT(*) FROM likes WHERE user_id = u.user_id) AS likes_given,\n    (SELECT COUNT(*) FROM follows WHERE follower_id = u.user_id) AS following,\n    (SELECT COUNT(*) FROM follows WHERE following_id = u.user_id) AS followers\n  FROM users u\n)\nSELECT *, \n  ROUND(\n    posts * 5 + comments * 3 + likes_given * 1 + followers * 2 - \n    GREATEST(following - followers, 0) * 0.5\n  , 1) AS engagement_score\nFROM user_engagement ORDER BY engagement_score DESC;", "explanation": "Weighted engagement scoring formula.", "db": "social_db"}, {"id": 588, "section": "Topic 28 — Advanced Analytics & Reporting (30 Qs)", "question": "Time-series gap filling with GENERATE_SERIES.", "sql": "WITH date_range AS (\n  SELECT d::DATE AS day FROM GENERATE_SERIES(\n    (SELECT MIN(placed_at)::DATE FROM orders),\n    (SELECT MAX(placed_at)::DATE FROM orders),\n    '1 day'\n  ) d\n),\ndaily_orders AS (\n  SELECT placed_at::DATE AS day, COUNT(*) AS orders, SUM(total_amount) AS revenue\n  FROM orders GROUP BY day\n)\nSELECT dr.day, COALESCE(do.orders, 0) AS orders, COALESCE(do.revenue, 0) AS revenue\nFROM date_range dr LEFT JOIN daily_orders do ON dr.day = do.day\nORDER BY dr.day;", "explanation": "LEFT JOIN with generated series fills gaps with zero — essential for charts.", "db": "ecommerce_db"}, {"id": 589, "section": "Topic 29 — Query Optimization (20 Qs)", "question": "Identify sequential scans on large tables.", "sql": "SELECT schemaname, relname, seq_scan, seq_tup_read,\n  idx_scan, idx_tup_fetch,\n  CASE WHEN seq_scan > 0 THEN seq_tup_read / seq_scan END AS avg_seq_tuples\nFROM pg_stat_user_tables\nWHERE seq_scan > 0\nORDER BY seq_tup_read DESC;", "explanation": "High seq_scan with many tuples suggests missing indexes.", "db": "ecommerce_db"}, {"id": 590, "section": "Topic 29 — Query Optimization (20 Qs)", "question": "Rewrite correlated subquery as JOIN.", "sql": "-- SLOW: Correlated subquery runs once per row\nSELECT p.name, (SELECT AVG(rating) FROM reviews WHERE product_id = p.product_id) AS avg_rating\nFROM products p;\n\n-- FAST: Single JOIN + GROUP BY\nSELECT p.name, ROUND(AVG(r.rating), 2) AS avg_rating\nFROM products p LEFT JOIN reviews r ON p.product_id = r.product_id\nGROUP BY p.name;", "explanation": "JOINs are generally faster than correlated subqueries.", "db": "ecommerce_db"}, {"id": 591, "section": "Topic 29 — Query Optimization (20 Qs)", "question": "Use EXISTS instead of COUNT for existence checks.", "sql": "-- SLOW: Counts all matching rows\nSELECT * FROM users u WHERE (SELECT COUNT(*) FROM orders WHERE user_id = u.user_id) > 0;\n\n-- FAST: Stops at first match\nSELECT * FROM users u WHERE EXISTS (SELECT 1 FROM orders WHERE user_id = u.user_id);", "explanation": "EXISTS short-circuits — stops scanning at the first match.", "db": "ecommerce_db"}, {"id": 592, "section": "Topic 29 — Query Optimization (20 Qs)", "question": "Avoid function calls in WHERE for index usage.", "sql": "-- BAD: Index on created_at won't be used\nSELECT * FROM orders WHERE EXTRACT(YEAR FROM placed_at) = 2025;\n\n-- GOOD: Range scan uses the index\nSELECT * FROM orders WHERE placed_at >= '2025-01-01' AND placed_at < '2026-01-01';", "explanation": "Function calls on indexed columns prevent index usage.", "db": "ecommerce_db"}, {"id": 593, "section": "Topic 29 — Query Optimization (20 Qs)", "question": "Use EXPLAIN to diagnose a slow query.", "sql": "EXPLAIN (ANALYZE, BUFFERS, FORMAT TEXT)\nSELECT p.name, c.name AS category, COUNT(r.review_id) AS reviews\nFROM products p\nJOIN categories c ON p.category_id = c.category_id\nLEFT JOIN reviews r ON p.product_id = r.product_id\nGROUP BY p.name, c.name\nORDER BY reviews DESC;\n\n-- Key things to look for:\n-- 1. Seq Scan vs Index Scan\n-- 2. Rows (estimated vs actual)\n-- 3. Sort Method (quicksort vs external merge)\n-- 4. Hash vs Nested Loop Join\n-- 5. Buffers (shared hit vs read)", "explanation": "Read EXPLAIN plans bottom-up. Focus on high-cost nodes.", "db": "ecommerce_db"}, {"id": 594, "section": "Topic 29 — Query Optimization (20 Qs)", "question": "Optimize IN with VALUES for large lists.", "sql": "-- BAD: Very long IN list\nSELECT * FROM orders WHERE order_id IN (1,2,3,...,10000);\n\n-- GOOD: JOIN with VALUES\nSELECT o.* FROM orders o\nJOIN (VALUES (1),(2),(3)) AS v(id) ON o.order_id = v.id;\n\n-- BETTER: Use ANY with array\nSELECT * FROM orders WHERE order_id = ANY(ARRAY[1,2,3]);", "explanation": "ANY with arrays is more efficient than long IN lists.", "db": "ecommerce_db"}, {"id": 595, "section": "Topic 29 — Query Optimization (20 Qs)", "question": "Use materialized CTE vs inline for performance.", "sql": "-- PostgreSQL 12+ can inline CTEs (optimization fence removed)\n-- Force materialization when you want it:\nWITH expensive_calc AS MATERIALIZED (\n  SELECT product_id, SUM(quantity * unit_price) AS revenue\n  FROM order_items GROUP BY product_id\n)\nSELECT * FROM expensive_calc WHERE revenue > 10000\nUNION ALL\nSELECT * FROM expensive_calc WHERE revenue < 100;", "explanation": "MATERIALIZED keyword prevents the CTE from being inlined.", "db": "ecommerce_db"}, {"id": 596, "section": "Topic 29 — Query Optimization (20 Qs)", "question": "Batch INSERT vs single INSERT performance.", "sql": "-- SLOW: 1000 individual inserts\nINSERT INTO page_views (user_id, product_id) VALUES (1, 1);\nINSERT INTO page_views (user_id, product_id) VALUES (1, 2);\n-- ... 998 more\n\n-- FAST: Single multi-row insert\nINSERT INTO page_views (user_id, product_id) VALUES\n  (1, 1), (1, 2), (1, 3), ... ;\n\n-- FASTEST: COPY for bulk loads\nCOPY page_views (user_id, product_id) FROM '/tmp/views.csv' CSV;", "explanation": "COPY is 5-10x faster than INSERT for bulk data.", "db": "ecommerce_db"}, {"id": 597, "section": "Topic 29 — Query Optimization (20 Qs)", "question": "Partial index for common query patterns.", "sql": "-- If 90% of queries filter active = TRUE:\nCREATE INDEX idx_products_active ON products (category_id, base_price)\nWHERE is_active = TRUE;\n\n-- Much smaller index, much faster queries for the common case\nSELECT * FROM products\nWHERE is_active = TRUE AND category_id = 5\nORDER BY base_price;", "explanation": "Partial indexes are smaller and faster for filtered queries.", "db": "ecommerce_db"}, {"id": 598, "section": "Topic 29 — Query Optimization (20 Qs)", "question": "Avoid SELECT * in production queries.", "sql": "-- BAD: Fetches all columns, prevents covering index\nSELECT * FROM orders WHERE user_id = 5;\n\n-- GOOD: Only needed columns, can use covering index\nSELECT order_id, total_amount, status\nFROM orders WHERE user_id = 5;", "explanation": "SELECT * increases I/O and prevents index-only scans.", "db": "ecommerce_db"}, {"id": 599, "section": "Topic 29 — Query Optimization (20 Qs)", "question": "Use connection pooling for scalability.", "sql": "-- PgBouncer configuration example:\n-- [databases]\n-- mydb = host=localhost dbname=mydb\n--\n-- [pgbouncer]\n-- pool_mode = transaction\n-- max_client_conn = 1000\n-- default_pool_size = 20\n\n-- Check connections\nSELECT count(*) FROM pg_stat_activity WHERE state = 'active';", "explanation": "PgBouncer manages connection pools — essential for production.", "db": "ecommerce_db"}, {"id": 600, "section": "Topic 30 — Advanced Concurrency Patterns (15 Qs)", "question": "Implement a job queue with SKIP LOCKED.", "sql": "CREATE TABLE job_queue (\n  job_id SERIAL PRIMARY KEY,\n  payload JSONB NOT NULL,\n  status VARCHAR(20) DEFAULT 'pending',\n  created_at TIMESTAMP DEFAULT NOW(),\n  started_at TIMESTAMP,\n  completed_at TIMESTAMP\n);\n\n-- Worker picks up a job (multiple workers can run concurrently)\nWITH next_job AS (\n  SELECT job_id FROM job_queue\n  WHERE status = 'pending'\n  ORDER BY created_at\n  LIMIT 1\n  FOR UPDATE SKIP LOCKED\n)\nUPDATE job_queue SET status = 'processing', started_at = NOW()\nFROM next_job WHERE job_queue.job_id = next_job.job_id\nRETURNING job_queue.*;", "explanation": "SKIP LOCKED enables concurrent workers without contention.", "db": "ecommerce_db"}, {"id": 601, "section": "Topic 30 — Advanced Concurrency Patterns (15 Qs)", "question": "Idempotent upsert with advisory lock.", "sql": "SELECT pg_advisory_xact_lock(hashtext('process_order_' || 42::TEXT));\n\nINSERT INTO orders (order_id, user_id, total_amount, status)\nVALUES (42, 1, 99.99, 'pending')\nON CONFLICT (order_id) DO NOTHING;", "explanation": "Advisory lock + upsert prevents duplicate processing in distributed systems.", "db": "ecommerce_db"}, {"id": 602, "section": "Topic 30 — Advanced Concurrency Patterns (15 Qs)", "question": "Optimistic locking with RETURNING for retry detection.", "sql": "UPDATE products\nSET base_price = 149.99, version = version + 1\nWHERE product_id = 1 AND version = 3\nRETURNING *;\n\n-- If RETURNING returns 0 rows:\n-- Another transaction modified the row — retry with fresh data", "explanation": "Optimistic locking is non-blocking — ideal for low-contention scenarios.", "db": "ecommerce_db"}, {"id": 603, "section": "Topic 30 — Advanced Concurrency Patterns (15 Qs)", "question": "Read-only transaction for consistent reports.", "sql": "BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;\n\n-- All queries in this transaction see the same snapshot\nSELECT COUNT(*) FROM orders;\nSELECT SUM(total_amount) FROM orders;\nSELECT AVG(total_amount) FROM orders;\n-- All three queries see consistent data\n\nCOMMIT;", "explanation": "READ ONLY + REPEATABLE READ gives a consistent snapshot for reports.", "db": "ecommerce_db"}, {"id": 604, "section": "Topic 30 — Advanced Concurrency Patterns (15 Qs)", "question": "Implement row-level security (RLS).", "sql": "ALTER TABLE orders ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY user_orders ON orders\n  FOR ALL\n  USING (user_id = current_setting('app.current_user_id')::INT);\n\n-- Set the user context\nSET app.current_user_id = '5';\n\n-- This only returns orders for user 5\nSELECT * FROM orders;", "explanation": "RLS enforces data isolation at the database level — essential for multi-tenant apps.", "db": "ecommerce_db"}, {"id": 605, "section": "Topic 30 — Advanced Concurrency Patterns (15 Qs)", "question": "Deferrable constraints for circular references.", "sql": "CREATE TABLE departments_v2 (\n  dept_id SERIAL PRIMARY KEY,\n  name VARCHAR(100),\n  manager_id INT\n);\n\nCREATE TABLE employees_v2 (\n  emp_id SERIAL PRIMARY KEY,\n  name VARCHAR(100),\n  dept_id INT REFERENCES departments_v2(dept_id) DEFERRABLE INITIALLY DEFERRED\n);\n\nALTER TABLE departments_v2\n  ADD CONSTRAINT fk_manager FOREIGN KEY (manager_id)\n  REFERENCES employees_v2(emp_id) DEFERRABLE INITIALLY DEFERRED;\n\n-- Now you can insert both in one transaction\nBEGIN;\nINSERT INTO departments_v2 (dept_id, name, manager_id) VALUES (1, 'Engineering', 1);\nINSERT INTO employees_v2 (emp_id, name, dept_id) VALUES (1, 'Alice', 1);\nCOMMIT; -- Constraints checked here", "explanation": "DEFERRABLE delays constraint checking to COMMIT time — solves chicken-and-egg problems.", "db": "ecommerce_db"}, {"id": 606, "section": "Topic 31 — Real-world Challenges (25 Qs)", "question": "Calculate order fulfillment SLA compliance.", "sql": "WITH fulfillment AS (\n  SELECT order_id,\n    EXTRACT(EPOCH FROM (shipped_at - placed_at)) / 3600 AS hours_to_ship,\n    CASE\n      WHEN shipped_at IS NULL THEN 'Not Shipped'\n      WHEN shipped_at - placed_at <= INTERVAL '24 hours' THEN 'Within SLA'\n      WHEN shipped_at - placed_at <= INTERVAL '48 hours' THEN 'Near SLA'\n      ELSE 'SLA Breach'\n    END AS sla_status\n  FROM orders WHERE status IN ('shipped', 'delivered', 'pending')\n)\nSELECT sla_status, COUNT(*) AS orders,\n  ROUND(COUNT(*) * 100.0 / SUM(COUNT(*)) OVER (), 1) AS pct\nFROM fulfillment GROUP BY sla_status;", "explanation": "SLA analysis with tiered classification.", "db": "ecommerce_db"}, {"id": 607, "section": "Topic 31 — Real-world Challenges (25 Qs)", "question": "Detect suspicious login patterns (multiple IPs).", "sql": "WITH user_ips AS (\n  SELECT user_id, ip_address, COUNT(*) AS views,\n    COUNT(DISTINCT ip_address) OVER (PARTITION BY user_id) AS distinct_ips\n  FROM page_views\n  WHERE viewed_at >= NOW() - INTERVAL '24 hours'\n  GROUP BY user_id, ip_address\n)\nSELECT * FROM user_ips WHERE distinct_ips > 5\nORDER BY distinct_ips DESC, user_id;", "explanation": "Anomaly detection for security monitoring.", "db": "ecommerce_db"}, {"id": 608, "section": "Topic 31 — Real-world Challenges (25 Qs)", "question": "Inventory reorder report: Products below safety stock.", "sql": "SELECT p.name, pv.variant_id, pv.size, pv.color, pv.stock_qty,\n  COALESCE((\n    SELECT ROUND(AVG(oi.quantity) * 30, 0)\n    FROM order_items oi WHERE oi.variant_id = pv.variant_id\n    AND oi.order_id IN (SELECT order_id FROM orders WHERE placed_at >= NOW() - INTERVAL '90 days')\n  ), 0) AS monthly_demand,\n  CASE WHEN pv.stock_qty < 10 THEN 'Critical'\n    WHEN pv.stock_qty < 30 THEN 'Low'\n    ELSE 'OK'\n  END AS stock_status\nFROM product_variants pv JOIN products p ON pv.product_id = p.product_id\nWHERE pv.stock_qty < 30\nORDER BY pv.stock_qty;", "explanation": "", "db": "ecommerce_db"}, {"id": 609, "section": "Topic 31 — Real-world Challenges (25 Qs)", "question": "Generate a financial statement (P&L summary).", "sql": "WITH revenue AS (\n  SELECT DATE_TRUNC('month', placed_at) AS month,\n    SUM(total_amount) AS gross_revenue,\n    SUM(discount_amount) AS discounts,\n    SUM(total_amount - COALESCE(discount_amount, 0)) AS net_revenue,\n    SUM(tax_amount) AS taxes,\n    SUM(shipping_fee) AS shipping\n  FROM orders WHERE status != 'cancelled'\n  GROUP BY month\n)\nSELECT TO_CHAR(month, 'YYYY-MM') AS period,\n  gross_revenue, discounts, net_revenue, taxes, shipping,\n  net_revenue - taxes AS profit_before_costs,\n  LAG(net_revenue) OVER (ORDER BY month) AS prev_month_rev,\n  ROUND((net_revenue - LAG(net_revenue) OVER (ORDER BY month)) / NULLIF(LAG(net_revenue) OVER (ORDER BY month), 0) * 100, 1) AS growth_pct\nFROM revenue ORDER BY month;", "explanation": "", "db": "ecommerce_db"}, {"id": 610, "section": "Topic 31 — Real-world Challenges (25 Qs)", "question": "Doctor utilization rate.", "sql": "WITH doc_hours AS (\n  SELECT d.doctor_id,\n    s.first_name || ' ' || s.last_name AS doctor_name,\n    COUNT(a.appointment_id) AS appointments,\n    SUM(a.duration_min) AS booked_minutes,\n    -- Assume 8 hours/day, 22 working days/month\n    8 * 60 * 22 AS available_minutes\n  FROM doctors d\n  JOIN staff s ON d.staff_id = s.staff_id\n  LEFT JOIN appointments a ON d.doctor_id = a.doctor_id\n    AND a.scheduled_at >= DATE_TRUNC('month', CURRENT_DATE)\n    AND a.status != 'cancelled'\n  GROUP BY d.doctor_id, s.first_name, s.last_name\n)\nSELECT *, ROUND(booked_minutes * 100.0 / available_minutes, 1) AS utilization_pct\nFROM doc_hours ORDER BY utilization_pct DESC;", "explanation": "", "db": "hospital_db"}, {"id": 611, "section": "Topic 31 — Real-world Challenges (25 Qs)", "question": "Student at-risk report (low attendance + low grades).", "sql": "WITH risk AS (\n  SELECT s.student_id, s.first_name, s.last_name, s.gpa,\n    ROUND(AVG(CASE WHEN a.status = 'present' THEN 1 ELSE 0 END) * 100, 1) AS attendance_pct\n  FROM students s\n  LEFT JOIN attendance a ON s.student_id = a.student_id\n  GROUP BY s.student_id, s.first_name, s.last_name, s.gpa\n)\nSELECT *, \n  CASE\n    WHEN gpa < 2.0 AND attendance_pct < 60 THEN 'High Risk'\n    WHEN gpa < 2.5 OR attendance_pct < 75 THEN 'At Risk'\n    ELSE 'OK'\n  END AS risk_level\nFROM risk WHERE gpa < 2.5 OR attendance_pct < 75\nORDER BY gpa, attendance_pct;", "explanation": "", "db": "university_db"}, {"id": 612, "section": "Topic 31 — Real-world Challenges (25 Qs)", "question": "Fraud detection: Unusual transaction amounts.", "sql": "WITH txn_stats AS (\n  SELECT account_id, AVG(amount) AS avg_amt, STDDEV(amount) AS std_amt\n  FROM transactions GROUP BY account_id\n)\nSELECT t.txn_id, t.account_id, t.amount, t.txn_date,\n  ROUND((t.amount - ts.avg_amt) / NULLIF(ts.std_amt, 0), 2) AS z_score\nFROM transactions t JOIN txn_stats ts ON t.account_id = ts.account_id\nWHERE ABS((t.amount - ts.avg_amt) / NULLIF(ts.std_amt, 0)) > 3\nORDER BY z_score DESC;", "explanation": "Z-score > 3 indicates a statistical outlier — potential fraud.", "db": "bank_db"}, {"id": 613, "section": "Topic 31 — Real-world Challenges (25 Qs)", "question": "Content moderation dashboard.", "sql": "WITH mod_stats AS (\n  SELECT\n    COUNT(*) AS total_reports,\n    COUNT(*) FILTER (WHERE status = 'pending') AS pending,\n    COUNT(*) FILTER (WHERE status = 'resolved') AS resolved,\n    COUNT(*) FILTER (WHERE status = 'dismissed') AS dismissed,\n    COUNT(DISTINCT reporter_id) AS unique_reporters,\n    COUNT(DISTINCT COALESCE(post_id, 0) + COALESCE(comment_id, 0)) AS flagged_content\n  FROM reports WHERE created_at >= NOW() - INTERVAL '7 days'\n)\nSELECT *, ROUND(resolved * 100.0 / NULLIF(total_reports, 0), 1) AS resolution_rate\nFROM mod_stats;", "explanation": "", "db": "social_db"}, {"id": 614, "section": "Topic 31 — Real-world Challenges (25 Qs)", "question": "Build a warehouse shipping manifest.", "sql": "SELECT o.order_id,\n  u.full_name AS customer,\n  a.street || ', ' || a.city || ', ' || a.state || ' ' || a.postal_code AS ship_to,\n  STRING_AGG(p.name || ' (x' || oi.quantity || ')', ', ' ORDER BY p.name) AS items,\n  o.total_amount,\n  s.carrier, s.tracking_no\nFROM orders o\nJOIN users u ON o.user_id = u.user_id\nJOIN addresses a ON o.address_id = a.address_id\nJOIN order_items oi ON o.order_id = oi.order_id\nJOIN product_variants pv ON oi.variant_id = pv.variant_id\nJOIN products p ON pv.product_id = p.product_id\nLEFT JOIN shipments s ON o.order_id = s.order_id\nWHERE o.status = 'shipped'\nGROUP BY o.order_id, u.full_name, a.street, a.city, a.state, a.postal_code,\n  o.total_amount, s.carrier, s.tracking_no\nORDER BY o.placed_at;", "explanation": "Complex real-world JOIN with aggregation.", "db": "ecommerce_db"}, {"id": 615, "section": "Topic 31 — Real-world Challenges (25 Qs)", "question": "Generate a payroll summary.", "sql": "SELECT e.employee_id, e.name, e.role, b.name AS branch,\n  e.salary AS monthly_salary,\n  ROUND(e.salary * 12, 2) AS annual_salary,\n  ROUND(e.salary * 0.12, 2) AS pf_contribution,\n  ROUND(CASE\n    WHEN e.salary * 12 <= 500000 THEN 0\n    WHEN e.salary * 12 <= 1000000 THEN (e.salary * 12 - 500000) * 0.2\n    ELSE 100000 + (e.salary * 12 - 1000000) * 0.3\n  END / 12, 2) AS monthly_tax,\n  ROUND(e.salary - e.salary * 0.12 - CASE\n    WHEN e.salary * 12 <= 500000 THEN 0\n    WHEN e.salary * 12 <= 1000000 THEN (e.salary * 12 - 500000) * 0.2\n    ELSE 100000 + (e.salary * 12 - 1000000) * 0.3\n  END / 12, 2) AS net_salary\nFROM employees e JOIN branches b ON e.branch_id = b.branch_id\nORDER BY e.salary DESC;", "explanation": "Complex payroll with tax slab calculation.", "db": "bank_db"}, {"id": 616, "section": "Topic 32 — Database Design Patterns (15 Qs)", "question": "Soft delete pattern.", "sql": "-- Add soft delete columns\nALTER TABLE products ADD COLUMN deleted_at TIMESTAMP;\nALTER TABLE products ADD COLUMN deleted_by INT;\n\n-- Create a view hiding deleted rows\nCREATE VIEW active_products_v2 AS\nSELECT * FROM products WHERE deleted_at IS NULL;\n\n-- Soft delete instead of hard delete\nUPDATE products SET deleted_at = NOW(), deleted_by = 1 WHERE product_id = 42;\n\n-- Partial index for queries on active rows only\nCREATE INDEX idx_products_active_v2 ON products (category_id) WHERE deleted_at IS NULL;", "explanation": "Soft deletes preserve data for auditing and recovery.", "db": "ecommerce_db"}, {"id": 617, "section": "Topic 32 — Database Design Patterns (15 Qs)", "question": "Temporal table pattern (history tracking).", "sql": "CREATE TABLE products_history (\n  history_id SERIAL PRIMARY KEY,\n  product_id INT NOT NULL,\n  name VARCHAR(200),\n  base_price NUMERIC(10,2),\n  valid_from TIMESTAMP NOT NULL DEFAULT NOW(),\n  valid_until TIMESTAMP,\n  operation CHAR(1) NOT NULL -- I=Insert, U=Update, D=Delete\n);\n\n-- Trigger to auto-capture history\nCREATE OR REPLACE FUNCTION track_product_history()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF TG_OP = 'UPDATE' THEN\n    INSERT INTO products_history (product_id, name, base_price, valid_until, operation)\n    VALUES (OLD.product_id, OLD.name, OLD.base_price, NOW(), 'U');\n  ELSIF TG_OP = 'DELETE' THEN\n    INSERT INTO products_history (product_id, name, base_price, valid_until, operation)\n    VALUES (OLD.product_id, OLD.name, OLD.base_price, NOW(), 'D');\n  END IF;\n  RETURN COALESCE(NEW, OLD);\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER trg_product_history\nAFTER UPDATE OR DELETE ON products\nFOR EACH ROW EXECUTE FUNCTION track_product_history();", "explanation": "Temporal tables maintain a complete change history.", "db": "ecommerce_db"}, {"id": 618, "section": "Topic 32 — Database Design Patterns (15 Qs)", "question": "Multi-tenant schema pattern.", "sql": "-- Option 1: Shared table with tenant_id\nCREATE TABLE mt_orders (\n  order_id SERIAL PRIMARY KEY,\n  tenant_id INT NOT NULL,\n  user_id INT NOT NULL,\n  total NUMERIC(12,2),\n  CONSTRAINT fk_tenant FOREIGN KEY (tenant_id) REFERENCES tenants(id)\n);\n\n-- Always partition by tenant\nCREATE INDEX idx_mt_orders_tenant ON mt_orders (tenant_id, order_id);\n\n-- RLS for automatic tenant isolation\nALTER TABLE mt_orders ENABLE ROW LEVEL SECURITY;\nCREATE POLICY tenant_isolation ON mt_orders\n  USING (tenant_id = current_setting('app.tenant_id')::INT);", "explanation": "Shared table + RLS is the most scalable multi-tenant pattern.", "db": "ecommerce_db"}, {"id": 619, "section": "Topic 32 — Database Design Patterns (15 Qs)", "question": "Event sourcing pattern.", "sql": "CREATE TABLE events (\n  event_id BIGSERIAL PRIMARY KEY,\n  aggregate_type VARCHAR(50) NOT NULL,\n  aggregate_id UUID NOT NULL,\n  event_type VARCHAR(100) NOT NULL,\n  payload JSONB NOT NULL,\n  metadata JSONB DEFAULT '{}',\n  created_at TIMESTAMP DEFAULT NOW()\n);\n\n-- Reconstruct current state from events\nWITH order_events AS (\n  SELECT * FROM events\n  WHERE aggregate_type = 'order' AND aggregate_id = 'abc-123'\n  ORDER BY created_at\n)\nSELECT\n  aggregate_id,\n  (SELECT payload->>'status' FROM order_events ORDER BY created_at DESC LIMIT 1) AS current_status,\n  MIN(created_at) AS created,\n  MAX(created_at) AS last_updated,\n  COUNT(*) AS event_count\nFROM order_events;", "explanation": "Event sourcing stores state changes as immutable events.", "db": "ecommerce_db"}, {"id": 620, "section": "Topic 32 — Database Design Patterns (15 Qs)", "question": "EAV (Entity-Attribute-Value) pattern.", "sql": "CREATE TABLE entity_attributes (\n  entity_id INT NOT NULL,\n  entity_type VARCHAR(50) NOT NULL,\n  attribute_name VARCHAR(100) NOT NULL,\n  attribute_value TEXT,\n  PRIMARY KEY (entity_id, entity_type, attribute_name)\n);\n\n-- Insert custom attributes\nINSERT INTO entity_attributes VALUES\n  (1, 'product', 'warranty_years', '2'),\n  (1, 'product', 'material', 'aluminum'),\n  (1, 'product', 'origin_country', 'Japan');\n\n-- Pivot EAV to columns\nSELECT entity_id,\n  MAX(attribute_value) FILTER (WHERE attribute_name = 'warranty_years') AS warranty,\n  MAX(attribute_value) FILTER (WHERE attribute_name = 'material') AS material,\n  MAX(attribute_value) FILTER (WHERE attribute_name = 'origin_country') AS origin\nFROM entity_attributes WHERE entity_type = 'product'\nGROUP BY entity_id;", "explanation": "EAV enables dynamic attributes — but JSONB is usually better in PostgreSQL.", "db": "ecommerce_db"}, {"id": 621, "section": "Topic 32 — Database Design Patterns (15 Qs)", "question": "Polymorphic associations pattern.", "sql": "CREATE TABLE activity_feed (\n  activity_id SERIAL PRIMARY KEY,\n  user_id INT NOT NULL,\n  target_type VARCHAR(50) NOT NULL, -- 'post', 'comment', 'review'\n  target_id INT NOT NULL,\n  action VARCHAR(50) NOT NULL, -- 'created', 'liked', 'shared'\n  created_at TIMESTAMP DEFAULT NOW()\n);\n\n-- Query with dynamic join\nSELECT af.*,\n  CASE af.target_type\n    WHEN 'post' THEN (SELECT content FROM posts WHERE post_id = af.target_id)\n    WHEN 'comment' THEN (SELECT content FROM comments WHERE comment_id = af.target_id)\n    WHEN 'review' THEN (SELECT title FROM reviews WHERE review_id = af.target_id)\n  END AS target_content\nFROM activity_feed af\nWHERE af.user_id = 1\nORDER BY af.created_at DESC;", "explanation": "Polymorphic association links one table to multiple target types.", "db": "social_db"}, {"id": 622, "section": "Topic 32 — Database Design Patterns (15 Qs)", "question": "Tree structure: Materialized path pattern.", "sql": "-- Store full path as a string\nALTER TABLE categories ADD COLUMN path TEXT;\n\n-- Example paths: /electronics, /electronics/phones, /electronics/phones/smartphones\n\n-- Find all descendants\nSELECT * FROM categories WHERE path LIKE '/electronics/%';\n\n-- Find ancestors by splitting path\nSELECT * FROM categories\nWHERE category_id = ANY(\n  STRING_TO_ARRAY(TRIM('/' FROM '/electronics/phones/smartphones'), '/')::INT[]\n);", "explanation": "Materialized path is simple and fast for reads — slower for moves.", "db": "ecommerce_db"}, {"id": 623, "section": "Topic 32 — Database Design Patterns (15 Qs)", "question": "Implement a type-safe state machine.", "sql": "CREATE TYPE order_state AS ENUM ('draft','pending','confirmed','shipped','delivered','cancelled');\n\nCREATE TABLE order_transitions (\n  from_state order_state NOT NULL,\n  to_state order_state NOT NULL,\n  PRIMARY KEY (from_state, to_state)\n);\n\nINSERT INTO order_transitions VALUES\n  ('draft', 'pending'), ('pending', 'confirmed'), ('pending', 'cancelled'),\n  ('confirmed', 'shipped'), ('confirmed', 'cancelled'),\n  ('shipped', 'delivered');\n\n-- Validate transition before update\nCREATE OR REPLACE FUNCTION validate_order_transition()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM order_transitions\n    WHERE from_state = OLD.status::order_state AND to_state = NEW.status::order_state\n  ) THEN\n    RAISE EXCEPTION 'Invalid transition: % -> %', OLD.status, NEW.status;\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;", "explanation": "State machine pattern enforces valid status transitions at database level.", "db": "ecommerce_db"}];
